    op.execute("CREATE TABLE IF NOT EXISTS canonical_fact_candidate_dispositions (\n\tcandidate_disposition_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tcandidate_universe_id VARCHAR(128) NOT NULL, \n\tcandidate_ordinal INTEGER NOT NULL, \n\tobservation_id VARCHAR(128) NOT NULL, \n\tsource_fact_cell_id VARCHAR(128) NOT NULL, \n\tbinding_revision_id VARCHAR(128) NOT NULL, \n\tbinding_commitment_sha256 VARCHAR(64) NOT NULL, \n\tmapping_commitment_sha256 VARCHAR(64) NOT NULL, \n\tobservation_payload_sha256 VARCHAR(64) NOT NULL, \n\tsource_publication_id VARCHAR(128), \n\tsource_publication_seal_id VARCHAR(128), \n\tsource_publication_member_id VARCHAR(128), \n\tsource_publication_member_sha256 VARCHAR(64), \n\tsource_record_commitment_sha256 VARCHAR(64), \n\tfiling_disposition_id VARCHAR(128), \n\tsource_lane VARCHAR(32) NOT NULL, \n\teligibility VARCHAR(16) NOT NULL, \n\treason_code VARCHAR(128) NOT NULL, \n\treason_details_json TEXT NOT NULL, \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (candidate_disposition_id), \n\tCONSTRAINT uq_canonical_fact_candidate_ordinal UNIQUE (candidate_universe_id, candidate_ordinal), \n\tCONSTRAINT uq_canonical_fact_candidate_observation UNIQUE (candidate_universe_id, observation_id), \n\tCONSTRAINT ck_canonical_fact_candidate_shape CHECK (candidate_ordinal >= 0 AND eligibility IN ('eligible','ineligible') AND source_lane IN ('filing_xbrl','reported_source_publication','derived_terminal_exclusion','missing_publication_exclusion') AND ((eligibility='eligible' AND source_publication_id IS NOT NULL AND source_publication_seal_id IS NOT NULL AND source_publication_member_id IS NOT NULL AND source_publication_member_sha256 IS NOT NULL AND source_record_commitment_sha256 IS NOT NULL) OR (eligibility='ineligible' AND source_publication_id IS NULL AND source_publication_seal_id IS NULL AND source_publication_member_id IS NULL AND source_publication_member_sha256 IS NULL AND source_record_commitment_sha256 IS NULL)) AND json_valid(reason_details_json) AND json_type(reason_details_json)='object'), \n\tCONSTRAINT ck_canonical_fact_candidate_hashes CHECK (length(observation_payload_sha256) = 64 AND observation_payload_sha256 NOT GLOB '*[^0-9a-f]*' AND length(binding_commitment_sha256) = 64 AND binding_commitment_sha256 NOT GLOB '*[^0-9a-f]*' AND length(mapping_commitment_sha256) = 64 AND mapping_commitment_sha256 NOT GLOB '*[^0-9a-f]*' AND (source_publication_member_sha256 IS NULL OR (length(source_publication_member_sha256) = 64 AND source_publication_member_sha256 NOT GLOB '*[^0-9a-f]*')) AND (source_record_commitment_sha256 IS NULL OR (length(source_record_commitment_sha256) = 64 AND source_record_commitment_sha256 NOT GLOB '*[^0-9a-f]*'))), \n\tCONSTRAINT ck_canonical_fact_candidate_clocks CHECK (effective_at <= knowledge_at AND knowledge_at <= recorded_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(candidate_universe_id) REFERENCES canonical_fact_candidate_universe_revisions (candidate_universe_id), \n\tFOREIGN KEY(observation_id) REFERENCES fact_observations_v2 (observation_id), \n\tFOREIGN KEY(binding_revision_id) REFERENCES fact_cell_canonical_binding_revisions (binding_revision_id), \n\tFOREIGN KEY(filing_disposition_id) REFERENCES filing_xbrl_extraction_dispositions (disposition_id)\n)")
