    op.execute("CREATE TABLE IF NOT EXISTS expected_documents (\n\texpected_document_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tsnapshot_id VARCHAR(128) NOT NULL, \n\texpected_document_key VARCHAR(256) NOT NULL, \n\tissuer_id VARCHAR(128) NOT NULL, \n\tticker VARCHAR(32), \n\tsource_kind VARCHAR(32) NOT NULL, \n\tdocument_type VARCHAR(64) NOT NULL, \n\tform_type VARCHAR(64), \n\taccession_number VARCHAR(64), \n\tsource_url TEXT, \n\tprimary_document TEXT, \n\tperiod_start DATETIME, \n\tperiod_end DATETIME, \n\tfiling_at DATETIME, \n\texpected_at DATETIME, \n\texpectation_basis VARCHAR(32) NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (expected_document_id), \n\tCONSTRAINT uq_expected_document_snapshot_key UNIQUE (snapshot_id, expected_document_key), \n\tCONSTRAINT ck_expected_document_source_kind CHECK (source_kind IN ('sec_filing', 'ir_document', 'earnings_call')), \n\tCONSTRAINT ck_expected_document_basis CHECK (expectation_basis IN ('authoritative', 'publisher_candidate', 'policy_inferred')), \n\tCONSTRAINT ck_expected_document_period CHECK (period_start IS NULL OR period_end IS NULL OR period_end >= period_start), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(snapshot_id) REFERENCES source_inventory_snapshots (snapshot_id)\n)")
    op.execute('CREATE TABLE IF NOT EXISTS expected_earnings (\n\tid INTEGER NOT NULL, \n\tticker VARCHAR NOT NULL, \n\texpected_date VARCHAR(10) NOT NULL, \n\tfiscal_period_end VARCHAR(10), \n\tfiscal_period_label VARCHAR(16), \n\tdetected_source VARCHAR(16) NOT NULL, \n\tfirst_seen_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tlast_seen_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, \n\tfact_seen_at DATETIME, \n\tPRIMARY KEY (id)\n)')
    op.execute("CREATE TABLE IF NOT EXISTS extractions (\n\tid INTEGER NOT NULL, \n\tsource_doc_id INTEGER NOT NULL, \n\tchar_offset_start INTEGER, \n\tchar_offset_end INTEGER, \n\textraction_kind VARCHAR(48) NOT NULL, \n\textractor_id VARCHAR(64) NOT NULL, \n\textractor_version VARCHAR(16) NOT NULL, \n\tpayload_json TEXT NOT NULL, \n\tconfidence FLOAT DEFAULT '1.0' NOT NULL, \n\textracted_at DATETIME NOT NULL, \n\tsuperseded_by_extraction_id INTEGER, \n\tlinks_to_json TEXT, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(superseded_by_extraction_id) REFERENCES extractions (id) ON DELETE SET NULL\n)")
    op.execute("CREATE TABLE IF NOT EXISTS fact_cell_canonical_binding_revisions (\n            binding_revision_id TEXT PRIMARY KEY,\n            idempotency_key TEXT NOT NULL UNIQUE,\n            fact_cell_id TEXT NOT NULL REFERENCES fact_cells_v2(fact_cell_id),\n            source_observation_id TEXT NOT NULL\n                REFERENCES fact_observations_v2(observation_id),\n            revision INTEGER NOT NULL CHECK(revision > 0),\n            supersedes_binding_revision_id TEXT\n                REFERENCES fact_cell_canonical_binding_revisions(\n                    binding_revision_id),\n            canonical_metric_cell_id TEXT\n                REFERENCES canonical_metric_cells(canonical_metric_cell_id),\n            mapping_revision_id TEXT\n                REFERENCES metric_mapping_revisions(mapping_revision_id),\n            source_component_id TEXT\n                REFERENCES source_taxonomy_components(component_id),\n            binding_status TEXT NOT NULL\n                CHECK(binding_status IN ('bound','quarantined','retired')),\n            reason_code TEXT,\n            reason_details_json TEXT\n                CHECK(reason_details_json IS NULL OR\n                      (json_valid(reason_details_json)\n                       AND json_type(reason_details_json)='object')),\n            reason_details_sha256 TEXT\n                CHECK(reason_details_sha256 IS NULL OR\n                      (length(reason_details_sha256)=64\n                       AND reason_details_sha256 NOT GLOB '*[^0-9a-f]*')),\n            commitment_json TEXT NOT NULL\n                CHECK(json_valid(commitment_json)\n                      AND json_type(commitment_json)='object'),\n            commitment_sha256 TEXT NOT NULL\n                CHECK(length(commitment_sha256)=64\n                      AND commitment_sha256 NOT GLOB '*[^0-9a-f]*'),\n            effective_at DATETIME NOT NULL,\n            knowledge_at DATETIME NOT NULL,\n            recorded_at DATETIME NOT NULL,\n            UNIQUE(source_observation_id, revision),\n            CHECK((revision=1)=(supersedes_binding_revision_id IS NULL)),\n            CHECK(\n                (binding_status='bound'\n                 AND canonical_metric_cell_id IS NOT NULL\n                 AND mapping_revision_id IS NOT NULL\n                 AND source_component_id IS NOT NULL\n                 AND reason_code IS NULL\n                 AND reason_details_json IS NULL\n                 AND reason_details_sha256 IS NULL)\n                OR\n                (binding_status='quarantined'\n                 AND canonical_metric_cell_id IS NULL\n                 AND mapping_revision_id IS NULL\n                 AND source_component_id IS NULL\n                 AND reason_code IS NOT NULL\n                 AND reason_details_json IS NOT NULL\n                 AND reason_details_sha256 IS NOT NULL)\n                OR\n                (binding_status='retired'\n                 AND canonical_metric_cell_id IS NOT NULL\n                 AND mapping_revision_id IS NOT NULL\n                 AND source_component_id IS NOT NULL\n                 AND (\n                    (reason_code IS NULL\n                     AND reason_details_json IS NULL\n                     AND reason_details_sha256 IS NULL)\n                    OR\n                    (reason_code IS NOT NULL\n                     AND reason_details_json IS NOT NULL\n                     AND reason_details_sha256 IS NOT NULL)\n                 ))\n            ),\n            CHECK(effective_at <= knowledge_at AND knowledge_at <= recorded_at)\n        )")
    op.execute("CREATE TABLE IF NOT EXISTS fact_cell_identity_seals_v2 (\n\tfact_cell_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tsemantic_key_version VARCHAR(64) NOT NULL, \n\tsemantic_identity_json TEXT NOT NULL, \n\tsemantic_key_sha256 VARCHAR(64) NOT NULL, \n\tdimension_count INTEGER NOT NULL, \n\tdimension_set_json TEXT NOT NULL, \n\tdimension_set_sha256 VARCHAR(64) NOT NULL, \n\tsealed_at DATETIME NOT NULL, \n\tPRIMARY KEY (fact_cell_id), \n\tCONSTRAINT ck_fact_cell_identity_seal_v2_version CHECK (semantic_key_version = 'fact_cell_semantic_key.v3'), \n\tCONSTRAINT ck_fact_cell_identity_seal_v2_count CHECK (dimension_count >= 0), \n\tCONSTRAINT ck_fact_cell_identity_seal_v2_json CHECK (json_valid(semantic_identity_json) AND json_type(semantic_identity_json) = 'object' AND json_valid(dimension_set_json) AND json_type(dimension_set_json) = 'array'), \n\tCONSTRAINT ck_fact_cell_identity_seal_v2_hashes CHECK (length(semantic_key_sha256) = 64 AND semantic_key_sha256 NOT GLOB '*[^0-9a-f]*' AND length(dimension_set_sha256) = 64 AND dimension_set_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tFOREIGN KEY(fact_cell_id) REFERENCES fact_cells_v2 (fact_cell_id), \n\tUNIQUE (idempotency_key), \n\tUNIQUE (semantic_key_sha256)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS fact_cells_v2 (\n\tfact_cell_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\treporting_entity_id VARCHAR(128) NOT NULL, \n\tscope_security_id VARCHAR(128), \n\tsemantic_key_version VARCHAR(64) NOT NULL, \n\tsemantic_key_sha256 VARCHAR(64) NOT NULL, \n\tconcept_namespace TEXT NOT NULL, \n\tconcept_name TEXT NOT NULL, \n\ttaxonomy_name TEXT NOT NULL, \n\ttaxonomy_version TEXT, \n\taccounting_basis VARCHAR(32) NOT NULL, \n\tconsolidation_scope VARCHAR(32) NOT NULL, \n\tperiod_kind VARCHAR(16) NOT NULL, \n\tperiod_start DATETIME, \n\tperiod_end DATETIME NOT NULL, \n\tfiscal_year INTEGER, \n\tfiscal_period VARCHAR(16), \n\tcanonical_dimensions_json TEXT NOT NULL, \n\tcanonical_dimensions_sha256 VARCHAR(64) NOT NULL, \n\tunit_key TEXT NOT NULL, \n\tcurrency VARCHAR(3), \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (fact_cell_id), \n\tCONSTRAINT ck_fact_cell_v2_semantic_version CHECK (semantic_key_version = 'fact_cell_semantic_key.v2'), \n\tCONSTRAINT ck_fact_cell_v2_hashes CHECK ((length(semantic_key_sha256) = 64 AND semantic_key_sha256 NOT GLOB '*[^0-9a-f]*') AND (length(canonical_dimensions_sha256) = 64 AND canonical_dimensions_sha256 NOT GLOB '*[^0-9a-f]*')), \n\tCONSTRAINT ck_fact_cell_v2_required_text CHECK (length(trim(concept_namespace)) > 0 AND length(trim(concept_name)) > 0 AND length(trim(taxonomy_name)) > 0 AND length(trim(unit_key)) > 0), \n\tCONSTRAINT ck_fact_cell_v2_accounting_basis CHECK (accounting_basis IN ('us_gaap', 'ifrs', 'local_gaap', 'management', 'non_gaap', 'other')), \n\tCONSTRAINT ck_fact_cell_v2_consolidation_scope CHECK (consolidation_scope IN ('consolidated', 'parent_only', 'subsidiary', 'segment', 'security_specific', 'other')), \n\tCONSTRAINT ck_fact_cell_v2_period CHECK ((period_kind = 'instant' AND period_start IS NULL) OR (period_kind = 'duration' AND period_start IS NOT NULL AND period_end >= period_start)), \n\tCONSTRAINT ck_fact_cell_v2_fiscal_period CHECK (fiscal_period IS NULL OR fiscal_period IN ('FY', 'Q1', 'Q2', 'Q3', 'Q4', 'H1', 'H2', 'YTD', 'TTM', 'OTHER')), \n\tCONSTRAINT ck_fact_cell_v2_currency CHECK (currency IS NULL OR (length(currency) = 3 AND currency = upper(currency))), \n\tCONSTRAINT ck_fact_cell_v2_dimensions CHECK (json_valid(canonical_dimensions_json) AND json_type(canonical_dimensions_json) = 'array'), \n\tCONSTRAINT ck_fact_cell_v2_clocks CHECK (knowledge_at >= effective_at AND recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(reporting_entity_id) REFERENCES reporting_entities (reporting_entity_id), \n\tFOREIGN KEY(scope_security_id) REFERENCES securities (security_id), \n\tUNIQUE (semantic_key_sha256)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS fact_derivation_basis_commitments_v2 (\n\tderivation_seal_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tinput_basis VARCHAR(16) NOT NULL, \n\tformula_id VARCHAR(128) NOT NULL, \n\tformula_version VARCHAR(128) NOT NULL, \n\tformula_definition_sha256 VARCHAR(64) NOT NULL, \n\texecution_config_sha256 VARCHAR(64) NOT NULL, \n\tknowledge_cutoff DATETIME NOT NULL, \n\tcanonical_basis_json TEXT NOT NULL, \n\tcanonical_basis_sha256 VARCHAR(64) NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (derivation_seal_id), \n\tCONSTRAINT ck_fact_derivation_basis_v2_kind CHECK (input_basis IN ('as_reported', 'as_known')), \n\tCONSTRAINT ck_fact_derivation_basis_v2_hashes CHECK (length(formula_definition_sha256) = 64 AND formula_definition_sha256 NOT GLOB '*[^0-9a-f]*' AND length(execution_config_sha256) = 64 AND execution_config_sha256 NOT GLOB '*[^0-9a-f]*' AND length(canonical_basis_sha256) = 64 AND canonical_basis_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tCONSTRAINT ck_fact_derivation_basis_v2_json CHECK (json_valid(canonical_basis_json) AND json_type(canonical_basis_json) = 'object'), \n\tFOREIGN KEY(derivation_seal_id) REFERENCES fact_derivation_seals_v2 (derivation_seal_id), \n\tUNIQUE (idempotency_key)\n)")
    op.execute('CREATE TABLE IF NOT EXISTS fact_derivation_input_edges_v2 (\n\tedge_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\toutput_observation_id VARCHAR(128) NOT NULL, \n\tinput_observation_id VARCHAR(128) NOT NULL, \n\tinput_resolution_revision_id VARCHAR(128), \n\tinput_role VARCHAR(128) NOT NULL, \n\tinput_ordinal INTEGER NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (edge_id), \n\tCONSTRAINT uq_fact_derivation_edge_v2_ordinal UNIQUE (output_observation_id, input_ordinal), \n\tCONSTRAINT uq_fact_derivation_edge_v2_input UNIQUE (output_observation_id, input_observation_id, input_role), \n\tCONSTRAINT ck_fact_derivation_edge_v2_shape CHECK (output_observation_id <> input_observation_id AND input_ordinal >= 0 AND length(trim(input_role)) > 0), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(output_observation_id) REFERENCES fact_observations_v2 (observation_id), \n\tFOREIGN KEY(input_observation_id) REFERENCES fact_observations_v2 (observation_id), \n\tFOREIGN KEY(input_resolution_revision_id) REFERENCES fact_resolution_revisions_v2 (resolution_revision_id)\n)')
    op.execute("CREATE TABLE IF NOT EXISTS fact_derivation_seals_v2 (\n\tderivation_seal_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\toutput_observation_id VARCHAR(128) NOT NULL, \n\tinput_count INTEGER NOT NULL, \n\tcanonical_input_digest_sha256 VARCHAR(64) NOT NULL, \n\tformula_config_sha256 VARCHAR(64) NOT NULL, \n\tseal_method VARCHAR(128) NOT NULL, \n\tseal_method_version VARCHAR(64) NOT NULL, \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (derivation_seal_id), \n\tCONSTRAINT ck_fact_derivation_seal_v2_input_count CHECK (input_count > 0), \n\tCONSTRAINT ck_fact_derivation_seal_v2_hashes CHECK ((length(canonical_input_digest_sha256) = 64 AND canonical_input_digest_sha256 NOT GLOB '*[^0-9a-f]*') AND (length(formula_config_sha256) = 64 AND formula_config_sha256 NOT GLOB '*[^0-9a-f]*')), \n\tCONSTRAINT ck_fact_derivation_seal_v2_clocks CHECK (knowledge_at >= effective_at AND recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tUNIQUE (output_observation_id), \n\tFOREIGN KEY(output_observation_id) REFERENCES fact_observations_v2 (observation_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS fact_dimensions_normalized_v2 (\n\tdimension_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tfact_cell_id VARCHAR(128) NOT NULL, \n\tdimension_ordinal INTEGER NOT NULL, \n\taxis_namespace TEXT NOT NULL, \n\taxis_name TEXT NOT NULL, \n\tmember_kind VARCHAR(16) NOT NULL, \n\texplicit_member_namespace TEXT, \n\texplicit_member_name TEXT, \n\ttyped_member_value_json TEXT, \n\ttyped_member_value_sha256 VARCHAR(64), \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (dimension_id), \n\tCONSTRAINT uq_fact_dimension_normalized_v2_ordinal UNIQUE (fact_cell_id, dimension_ordinal), \n\tCONSTRAINT uq_fact_dimension_normalized_v2_axis UNIQUE (fact_cell_id, axis_namespace, axis_name), \n\tCONSTRAINT ck_fact_dimension_normalized_v2_ordinal CHECK (dimension_ordinal >= 0), \n\tCONSTRAINT ck_fact_dimension_normalized_v2_axis CHECK (length(trim(axis_namespace)) > 0 AND length(trim(axis_name)) > 0), \n\tCONSTRAINT ck_fact_dimension_normalized_v2_member CHECK ((member_kind = 'explicit' AND explicit_member_namespace IS NOT NULL AND explicit_member_name IS NOT NULL AND typed_member_value_json IS NULL AND typed_member_value_sha256 IS NULL) OR (member_kind = 'typed' AND explicit_member_namespace IS NULL AND explicit_member_name IS NULL AND typed_member_value_json IS NOT NULL AND typed_member_value_sha256 IS NOT NULL)), \n\tCONSTRAINT ck_fact_dimension_normalized_v2_typed_json CHECK (typed_member_value_json IS NULL OR (json_valid(typed_member_value_json) AND json_type(typed_member_value_json) = 'object')), \n\tCONSTRAINT ck_fact_dimension_normalized_v2_typed_hash CHECK (typed_member_value_sha256 IS NULL OR (length(typed_member_value_sha256) = 64 AND typed_member_value_sha256 NOT GLOB '*[^0-9a-f]*')), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(fact_cell_id) REFERENCES fact_cells_v2 (fact_cell_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS fact_extraction_run_completeness_seals_v2 (\n\textraction_seal_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\textraction_run_id VARCHAR(128) NOT NULL, \n\texpected_node_count INTEGER NOT NULL, \n\tobserved_node_count INTEGER NOT NULL, \n\treported_fact_count INTEGER NOT NULL, \n\tnode_set_json TEXT NOT NULL, \n\tnode_set_sha256 VARCHAR(64) NOT NULL, \n\tobservation_set_json TEXT NOT NULL, \n\tobservation_set_sha256 VARCHAR(64) NOT NULL, \n\textractor_config_sha256 VARCHAR(64) NOT NULL, \n\textraction_output_sha256 VARCHAR(64) NOT NULL, \n\tcompleteness_policy_name VARCHAR(128) NOT NULL, \n\tcompleteness_policy_version VARCHAR(64) NOT NULL, \n\tcompleteness_policy_sha256 VARCHAR(64) NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (extraction_seal_id), \n\tCONSTRAINT ck_fact_extraction_seal_v2_counts CHECK (expected_node_count >= 0 AND observed_node_count = expected_node_count AND reported_fact_count >= 0), \n\tCONSTRAINT ck_fact_extraction_seal_v2_json CHECK (json_valid(node_set_json) AND json_type(node_set_json) = 'array' AND json_valid(observation_set_json) AND json_type(observation_set_json) = 'array'), \n\tCONSTRAINT ck_fact_extraction_seal_v2_hashes CHECK (length(node_set_sha256) = 64 AND node_set_sha256 NOT GLOB '*[^0-9a-f]*' AND length(observation_set_sha256) = 64 AND observation_set_sha256 NOT GLOB '*[^0-9a-f]*' AND length(extractor_config_sha256) = 64 AND extractor_config_sha256 NOT GLOB '*[^0-9a-f]*' AND length(extraction_output_sha256) = 64 AND extraction_output_sha256 NOT GLOB '*[^0-9a-f]*' AND length(completeness_policy_sha256) = 64 AND completeness_policy_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tCONSTRAINT ck_fact_extraction_seal_v2_clocks CHECK (recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tUNIQUE (extraction_run_id), \n\tFOREIGN KEY(extraction_run_id) REFERENCES evidence_extraction_runs (extraction_run_id)\n)")
