    op.execute("CREATE TABLE IF NOT EXISTS heterogeneous_retrieval_trace_candidates (\n\ttrace_id VARCHAR(128) NOT NULL, \n\tcandidate_ordinal INTEGER NOT NULL, \n\tcandidate_kind VARCHAR(16) NOT NULL, \n\tcandidate_id VARCHAR(128) NOT NULL, \n\tsource_commitment_sha256 VARCHAR(64) NOT NULL, \n\tlexical_score TEXT, \n\tsemantic_score TEXT, \n\tnormalized_score TEXT NOT NULL, \n\tranker_name VARCHAR(128) NOT NULL, \n\tfilter_outcome VARCHAR(16) NOT NULL, \n\tfilter_reason VARCHAR(128), \n\tevidence_locator_json TEXT NOT NULL, \n\tlineage_json TEXT NOT NULL, \n\tlineage_sha256 VARCHAR(64) NOT NULL, \n\tcandidate_json TEXT NOT NULL, \n\tcandidate_sha256 VARCHAR(64) NOT NULL, \n\tPRIMARY KEY (trace_id, candidate_ordinal), \n\tCONSTRAINT uq_heterogeneous_retrieval_trace_candidate UNIQUE (trace_id, candidate_kind, candidate_id), \n\tCONSTRAINT ck_heterogeneous_retrieval_candidate_shape CHECK (candidate_ordinal>=0 AND candidate_kind IN ('narrative','fact') AND filter_outcome IN ('included','filtered') AND ((filter_outcome='included' AND filter_reason IS NULL) OR (filter_outcome='filtered' AND filter_reason IS NOT NULL))), \n\tCONSTRAINT ck_heterogeneous_retrieval_candidate_json CHECK (json_valid(evidence_locator_json) AND json_type(evidence_locator_json)='object' AND json_valid(lineage_json) AND json_type(lineage_json)='object' AND json_valid(candidate_json) AND json_type(candidate_json)='object'), \n\tCONSTRAINT ck_heterogeneous_retrieval_candidate_hashes CHECK (length(source_commitment_sha256)=64 AND source_commitment_sha256 NOT GLOB '*[^0-9a-f]*' AND length(lineage_sha256)=64 AND lineage_sha256 NOT GLOB '*[^0-9a-f]*' AND length(candidate_sha256)=64 AND candidate_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tFOREIGN KEY(trace_id) REFERENCES heterogeneous_retrieval_trace_headers (trace_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS heterogeneous_retrieval_trace_headers (\n\ttrace_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tresearch_snapshot_id VARCHAR(128) NOT NULL, \n\tresearch_snapshot_sha256 VARCHAR(64) NOT NULL, \n\tfact_generation_id VARCHAR(128) NOT NULL, \n\tfact_projection_seal_sha256 VARCHAR(64) NOT NULL, \n\tnarrative_commitments_json TEXT NOT NULL, \n\tnarrative_commitments_sha256 VARCHAR(64) NOT NULL, \n\tsemantic_receipts_json TEXT NOT NULL, \n\tsemantic_receipts_sha256 VARCHAR(64) NOT NULL, \n\tquery_sha256 VARCHAR(64) NOT NULL, \n\tquery_json TEXT NOT NULL, \n\tranker_json TEXT NOT NULL, \n\tranker_sha256 VARCHAR(64) NOT NULL, \n\tfilters_json TEXT NOT NULL, \n\tfilters_sha256 VARCHAR(64) NOT NULL, \n\tcandidate_limit INTEGER NOT NULL, \n\tresult_limit INTEGER NOT NULL, \n\tcutoff_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, population_run_id VARCHAR(128), population_receipt_set_sha256 VARCHAR(64), population_observed_through DATETIME, \n\tPRIMARY KEY (trace_id), \n\tCONSTRAINT ck_heterogeneous_retrieval_trace_bounds CHECK (candidate_limit BETWEEN 1 AND 1000 AND result_limit BETWEEN 1 AND candidate_limit), \n\tCONSTRAINT ck_heterogeneous_retrieval_trace_json CHECK (json_valid(query_json) AND json_type(query_json)='object' AND json_valid(narrative_commitments_json) AND json_type(narrative_commitments_json)='array' AND json_valid(semantic_receipts_json) AND json_type(semantic_receipts_json)='array' AND json_valid(ranker_json) AND json_type(ranker_json)='object' AND json_valid(filters_json) AND json_type(filters_json)='object'), \n\tCONSTRAINT ck_heterogeneous_retrieval_trace_hashes CHECK (length(research_snapshot_sha256)=64 AND research_snapshot_sha256 NOT GLOB '*[^0-9a-f]*' AND length(fact_projection_seal_sha256)=64 AND fact_projection_seal_sha256 NOT GLOB '*[^0-9a-f]*' AND length(narrative_commitments_sha256)=64 AND narrative_commitments_sha256 NOT GLOB '*[^0-9a-f]*' AND length(semantic_receipts_sha256)=64 AND semantic_receipts_sha256 NOT GLOB '*[^0-9a-f]*' AND length(query_sha256)=64 AND query_sha256 NOT GLOB '*[^0-9a-f]*' AND length(ranker_sha256)=64 AND ranker_sha256 NOT GLOB '*[^0-9a-f]*' AND length(filters_sha256)=64 AND filters_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tCONSTRAINT ck_heterogeneous_retrieval_trace_clocks CHECK (recorded_at>=cutoff_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(research_snapshot_id) REFERENCES research_snapshot_seals (research_snapshot_id), \n\tFOREIGN KEY(fact_generation_id) REFERENCES canonical_fact_projection_seals (generation_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS heterogeneous_retrieval_trace_results (\n\ttrace_id VARCHAR(128) NOT NULL, \n\tresult_ordinal INTEGER NOT NULL, \n\tcandidate_ordinal INTEGER NOT NULL, \n\tfinal_score TEXT NOT NULL, \n\tresult_json TEXT NOT NULL, \n\tresult_sha256 VARCHAR(64) NOT NULL, \n\tPRIMARY KEY (trace_id, result_ordinal), \n\tFOREIGN KEY(trace_id, candidate_ordinal) REFERENCES heterogeneous_retrieval_trace_candidates (trace_id, candidate_ordinal), \n\tCONSTRAINT uq_heterogeneous_retrieval_result_candidate UNIQUE (trace_id, candidate_ordinal), \n\tCONSTRAINT ck_heterogeneous_retrieval_result_shape CHECK (result_ordinal>=0 AND candidate_ordinal>=0 AND json_valid(result_json) AND json_type(result_json)='object' AND length(result_sha256)=64 AND result_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tFOREIGN KEY(trace_id) REFERENCES heterogeneous_retrieval_trace_headers (trace_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS heterogeneous_retrieval_trace_seals (\n\ttrace_id VARCHAR(128) NOT NULL, \n\tcandidate_count INTEGER NOT NULL, \n\tresult_count INTEGER NOT NULL, \n\tcanonical_candidate_set_json TEXT NOT NULL, \n\tcandidate_set_sha256 VARCHAR(64) NOT NULL, \n\tcanonical_result_set_json TEXT NOT NULL, \n\tresult_set_sha256 VARCHAR(64) NOT NULL, \n\ttrace_json TEXT NOT NULL, \n\ttrace_sha256 VARCHAR(64) NOT NULL, \n\tsealed_at DATETIME NOT NULL, \n\tPRIMARY KEY (trace_id), \n\tCONSTRAINT ck_heterogeneous_retrieval_seal_shape CHECK (candidate_count>=0 AND result_count>=0 AND json_valid(canonical_candidate_set_json) AND json_type(canonical_candidate_set_json)='array' AND json_valid(canonical_result_set_json) AND json_type(canonical_result_set_json)='array' AND json_valid(trace_json) AND json_type(trace_json)='object'), \n\tCONSTRAINT ck_heterogeneous_retrieval_seal_hashes CHECK (length(candidate_set_sha256)=64 AND candidate_set_sha256 NOT GLOB '*[^0-9a-f]*' AND length(result_set_sha256)=64 AND result_set_sha256 NOT GLOB '*[^0-9a-f]*' AND length(trace_sha256)=64 AND trace_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tFOREIGN KEY(trace_id) REFERENCES heterogeneous_retrieval_trace_headers (trace_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS image_ocr_assessments (\n\tassessment_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tdocument_version_id VARCHAR(128) NOT NULL, \n\tinput_sha256 VARCHAR(64) NOT NULL, \n\tobserved_sha256 VARCHAR(64), \n\tobserved_byte_size INTEGER, \n\tmedia_type VARCHAR(32) NOT NULL, \n\twidth INTEGER, \n\theight INTEGER, \n\tpixel_count INTEGER, \n\tpage_count INTEGER NOT NULL, \n\tdetector_name VARCHAR(128) NOT NULL, \n\tdetector_config_sha256 VARCHAR(64) NOT NULL, \n\tdetector_code_version VARCHAR(255) NOT NULL, \n\toutcome VARCHAR(32) NOT NULL, \n\treason_code VARCHAR(128), \n\tassessed_at DATETIME NOT NULL, \n\tPRIMARY KEY (assessment_id), \n\tCONSTRAINT ck_image_ocr_assessment_hashes CHECK (length(input_sha256) = 64 AND (observed_sha256 IS NULL OR length(observed_sha256) = 64) AND length(detector_config_sha256) = 64), \n\tCONSTRAINT ck_image_ocr_assessment_bytes CHECK (observed_byte_size IS NULL OR observed_byte_size >= 0), \n\tCONSTRAINT ck_image_ocr_assessment_media_type CHECK (media_type IN ('image/jpeg', 'image/png')), \n\tCONSTRAINT ck_image_ocr_assessment_dimensions CHECK ((width IS NULL AND height IS NULL AND pixel_count IS NULL) OR (width > 0 AND height > 0 AND pixel_count = width * height)), \n\tCONSTRAINT ck_image_ocr_assessment_outcome CHECK (outcome IN ('ocr_required', 'unsupported', 'unreadable', 'quarantined')), \n\tCONSTRAINT ck_image_ocr_assessment_shape CHECK ((outcome = 'ocr_required' AND reason_code IS NULL AND page_count = 1 AND width IS NOT NULL) OR (outcome <> 'ocr_required' AND reason_code IS NOT NULL AND page_count IN (0, 1))), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(document_version_id) REFERENCES evidence_document_versions (document_version_id)\n)")
    op.execute('CREATE TABLE IF NOT EXISTS image_ocr_extraction_governance (\n\textraction_run_id VARCHAR(128) NOT NULL, \n\tassessment_id VARCHAR(128) NOT NULL, \n\tengine_name VARCHAR(128) NOT NULL, \n\tengine_version VARCHAR(255) NOT NULL, \n\tengine_binary_sha256 VARCHAR(64) NOT NULL, \n\tmodel_name VARCHAR(128) NOT NULL, \n\tmodel_version VARCHAR(255) NOT NULL, \n\tmodel_manifest_sha256 VARCHAR(64) NOT NULL, \n\tmodel_artifacts_json TEXT NOT NULL, \n\tlanguages_json TEXT NOT NULL, \n\tengine_config_json TEXT NOT NULL, \n\textractor_config_sha256 VARCHAR(64) NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (extraction_run_id), \n\tCONSTRAINT ck_image_ocr_governance_hashes CHECK (length(engine_binary_sha256) = 64 AND length(model_manifest_sha256) = 64 AND length(extractor_config_sha256) = 64), \n\tFOREIGN KEY(extraction_run_id) REFERENCES evidence_extraction_runs (extraction_run_id), \n\tFOREIGN KEY(assessment_id) REFERENCES image_ocr_assessments (assessment_id)\n)')
    op.execute("CREATE TABLE IF NOT EXISTS image_ocr_results (\n\textraction_run_id VARCHAR(128) NOT NULL, \n\tpage_number INTEGER NOT NULL, \n\tnode_id VARCHAR(128), \n\toutcome VARCHAR(32) NOT NULL, \n\toutput_sha256 VARCHAR(64), \n\tmean_confidence FLOAT, \n\tlocator_json TEXT NOT NULL, \n\tlocator_sha256 VARCHAR(64) NOT NULL, \n\treason_code VARCHAR(128), \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (extraction_run_id), \n\tCONSTRAINT ck_image_ocr_result_page CHECK (page_number = 1), \n\tCONSTRAINT ck_image_ocr_result_outcome CHECK (outcome IN ('accepted', 'quarantined', 'failed')), \n\tCONSTRAINT ck_image_ocr_result_hashes CHECK (length(locator_sha256) = 64 AND (output_sha256 IS NULL OR length(output_sha256) = 64)), \n\tCONSTRAINT ck_image_ocr_result_confidence CHECK (mean_confidence IS NULL OR (mean_confidence >= 0.0 AND mean_confidence <= 100.0)), \n\tCONSTRAINT ck_image_ocr_result_shape CHECK ((outcome = 'accepted' AND node_id IS NOT NULL AND output_sha256 IS NOT NULL AND mean_confidence IS NOT NULL AND reason_code IS NULL) OR (outcome = 'quarantined' AND node_id IS NULL AND output_sha256 IS NOT NULL AND mean_confidence IS NOT NULL AND reason_code IS NOT NULL) OR (outcome = 'failed' AND node_id IS NULL AND output_sha256 IS NULL AND mean_confidence IS NULL AND reason_code IS NOT NULL)), \n\tFOREIGN KEY(extraction_run_id) REFERENCES image_ocr_extraction_governance (extraction_run_id), \n\tUNIQUE (node_id), \n\tFOREIGN KEY(node_id) REFERENCES evidence_nodes (node_id)\n)")
    op.execute('CREATE TABLE IF NOT EXISTS ingestion_runs (\n\tid INTEGER NOT NULL, \n\trun_id VARCHAR NOT NULL, \n\tstarted_at DATETIME NOT NULL, \n\tended_at DATETIME, \n\tdirective VARCHAR NOT NULL, \n\tticker_scope TEXT NOT NULL, \n\tstatus VARCHAR NOT NULL, \n\terror_summary TEXT, pipeline_key VARCHAR(64), attempt_id VARCHAR(128), \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_ingestion_runs_run_id UNIQUE (run_id)\n)')
    op.execute("CREATE TABLE IF NOT EXISTS insider_transactions (\n\tid INTEGER NOT NULL, \n\tticker VARCHAR(16) NOT NULL, \n\tinsider_entity_id INTEGER, \n\tinsider_name VARCHAR(255) NOT NULL, \n\tinsider_title VARCHAR(255), \n\tinsider_relation VARCHAR(64), \n\ttransaction_date DATETIME NOT NULL, \n\tfiling_date DATETIME NOT NULL, \n\tfiling_doc_id INTEGER, \n\ttransaction_type VARCHAR(32) NOT NULL, \n\tshares NUMERIC(24, 6) NOT NULL, \n\tprice_per_share NUMERIC(24, 6), \n\ttransaction_value NUMERIC(24, 6), \n\tshares_owned_after NUMERIC(24, 6), \n\townership_pct FLOAT, \n\tis_10b5_1 BOOLEAN DEFAULT '0' NOT NULL, \n\tacquired_or_disposed VARCHAR(1), \n\townership_form VARCHAR(1), \n\tform_filed VARCHAR(8) DEFAULT '4' NOT NULL, \n\tregulator VARCHAR(16) DEFAULT 'SEC' NOT NULL, \n\tsource_url VARCHAR(1024), \n\tnotes TEXT, \n\tingested_at DATETIME NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_insider_tx UNIQUE (ticker, insider_name, transaction_date, transaction_type, shares, form_filed)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS insight_notes (\n\tid INTEGER NOT NULL, \n\tscope_key TEXT NOT NULL, \n\tkind TEXT NOT NULL, \n\tbody_md TEXT NOT NULL, \n\tsource_note_ids TEXT DEFAULT '[]' NOT NULL, \n\tmeta_json TEXT, \n\tas_of TEXT NOT NULL, \n\twindow_start TEXT, \n\twindow_end TEXT, \n\twatermark_id INTEGER, \n\tsupersedes_id INTEGER, \n\tstatus TEXT DEFAULT 'current' NOT NULL, \n\tesi FLOAT, \n\tprovenance TEXT DEFAULT 'derived' NOT NULL, \n\tcreated_at TEXT NOT NULL, \n\tupdated_at TEXT NOT NULL, \n\tPRIMARY KEY (id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS insights (\n\tid INTEGER NOT NULL, \n\tscope VARCHAR(32) DEFAULT 'ticker' NOT NULL, \n\tticker VARCHAR(16), \n\tlens VARCHAR(64) NOT NULL, \n\tprompt_version VARCHAR(32) DEFAULT 'v1' NOT NULL, \n\tgenerated_at DATETIME NOT NULL, \n\tcontent_md TEXT NOT NULL, \n\tcontent_json TEXT, \n\tinput_artifact_ids TEXT, \n\tinput_facts_window VARCHAR(128), \n\tsuperseded_by_id INTEGER, \n\tdirty BOOLEAN DEFAULT '0' NOT NULL, \n\tdirty_reason VARCHAR(128), \n\texpires_at DATETIME, \n\tllm_call_id INTEGER, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(superseded_by_id) REFERENCES insights (id) ON DELETE SET NULL\n)")
    op.execute("CREATE TABLE IF NOT EXISTS investor_calibration (\n\tid INTEGER NOT NULL, \n\tuser_id TEXT DEFAULT 'bhanu' NOT NULL, \n\tsource_key TEXT NOT NULL, \n\tticker TEXT NOT NULL, \n\tobserved_at TEXT NOT NULL, \n\taction TEXT, \n\tentry_price FLOAT, \n\tentry_recorded_at TEXT NOT NULL, \n\thorizon_days INTEGER DEFAULT 180 NOT NULL, \n\tmeasured_at TEXT, \n\texit_price FLOAT, \n\tforward_return FLOAT, \n\toutcome TEXT, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_investor_calibration_outcome CHECK (outcome IS NULL OR outcome IN ('win', 'loss', 'flat', 'no_price')), \n\tCONSTRAINT uq_investor_calibration UNIQUE (user_id, source_key, ticker, observed_at)\n)")
    op.execute('CREATE TABLE IF NOT EXISTS "ir_fetch_status" (\n\tticker TEXT NOT NULL, \n\tlast_attempt_at TEXT NOT NULL, \n\tlast_status TEXT NOT NULL, \n\tdiscovered INTEGER, \n\tdownloaded INTEGER, \n\treason TEXT, \n\tupdated_at TEXT NOT NULL, \n\tPRIMARY KEY (ticker), \n\tCONSTRAINT ck_ir_fetch_status_last_status CHECK (last_status IN (\'ok\', \'failed\', \'skipped\'))\n)')
    op.execute("CREATE TABLE IF NOT EXISTS issuer_authority_surface_revisions (\n\tsurface_revision_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tissuer_id VARCHAR(128) NOT NULL, \n\tsurface_key VARCHAR(128) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tsurface_kind VARCHAR(32) NOT NULL, \n\tsource_url TEXT NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tauthority_level VARCHAR(16) NOT NULL, \n\tsource_observation_id VARCHAR(128), \n\tverification_method VARCHAR(128) NOT NULL, \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tsupersedes_surface_revision_id VARCHAR(128), \n\tPRIMARY KEY (surface_revision_id), \n\tCONSTRAINT uq_issuer_authority_surface_revision UNIQUE (issuer_id, surface_key, revision), \n\tCONSTRAINT ck_issuer_authority_surface_revision CHECK (revision > 0), \n\tCONSTRAINT ck_issuer_authority_surface_kind CHECK (surface_kind IN ('sec_submissions', 'sec_companyfacts', 'ir_home', 'ir_archive', 'ir_events', 'ir_presentations', 'ir_financials', 'ir_sec_filings', 'earnings_feed', 'other')), \n\tCONSTRAINT ck_issuer_authority_surface_status CHECK (status IN ('candidate', 'verified', 'retired', 'unavailable')), \n\tCONSTRAINT ck_issuer_authority_surface_level CHECK (authority_level IN ('regulator', 'publisher', 'third_party')), \n\tCONSTRAINT ck_issuer_authority_surface_evidence CHECK (status <> 'verified' OR source_observation_id IS NOT NULL), \n\tCONSTRAINT ck_issuer_authority_surface_clocks CHECK (knowledge_at >= effective_at AND recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(issuer_id) REFERENCES issuer_entities (issuer_id), \n\tFOREIGN KEY(source_observation_id) REFERENCES evidence_source_observations (observation_id), \n\tFOREIGN KEY(supersedes_surface_revision_id) REFERENCES issuer_authority_surface_revisions (surface_revision_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS issuer_entities (\n\tissuer_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tentity_kind VARCHAR(32) NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tPRIMARY KEY (issuer_id), \n\tCONSTRAINT ck_issuer_entity_kind CHECK (entity_kind IN ('operating_company', 'fund', 'partnership', 'other')), \n\tUNIQUE (idempotency_key)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS issuer_identifier_assertions (\n\tassertion_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tissuer_id VARCHAR(128) NOT NULL, \n\tidentifier_type VARCHAR(32) NOT NULL, \n\tidentifier_value TEXT NOT NULL, \n\tnormalized_value TEXT NOT NULL, \n\tauthority VARCHAR(32) NOT NULL, \n\tsource_observation_id VARCHAR(128), \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (assertion_id), \n\tCONSTRAINT ck_issuer_identifier_type CHECK (identifier_type IN ('sec_cik', 'lei', 'isin', 'figi', 'sedar_profile', 'companies_house')), \n\tCONSTRAINT ck_issuer_identifier_authority CHECK (authority IN ('issuer_publisher', 'sec_registry', 'exchange_registry', 'regulator', 'manual', 'imported')), \n\tCONSTRAINT ck_issuer_identifier_evidence CHECK (authority = 'manual' OR source_observation_id IS NOT NULL), \n\tCONSTRAINT ck_issuer_identifier_clocks CHECK (knowledge_at >= effective_at AND recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(issuer_id) REFERENCES issuer_entities (issuer_id), \n\tFOREIGN KEY(source_observation_id) REFERENCES evidence_source_observations (observation_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS issuer_identifier_resolution_outcomes (\n\tresolution_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tresolution_key VARCHAR(512) NOT NULL, \n\trevision INTEGER NOT NULL, \n\toutcome VARCHAR(16) NOT NULL, \n\tselected_assertion_id VARCHAR(128), \n\tcandidate_digest_sha256 VARCHAR(64) NOT NULL, \n\tpolicy_name VARCHAR(128) NOT NULL, \n\tpolicy_version VARCHAR(64) NOT NULL, \n\tpolicy_config_sha256 VARCHAR(64) NOT NULL, \n\treason_code VARCHAR(128) NOT NULL, \n\treason_details_json TEXT NOT NULL, \n\tmaterial_dissent BOOLEAN NOT NULL, \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tsupersedes_resolution_id VARCHAR(128), \n\tPRIMARY KEY (resolution_id), \n\tCONSTRAINT uq_issuer_identifier_resolution_revision UNIQUE (resolution_key, revision), \n\tCONSTRAINT ck_issuer_identifier_resolution_revision CHECK (revision > 0), \n\tCONSTRAINT ck_issuer_identifier_resolution_outcome CHECK (outcome IN ('selected', 'unresolved', 'rejected')), \n\tCONSTRAINT ck_issuer_identifier_resolution_selection CHECK ((outcome = 'selected' AND selected_assertion_id IS NOT NULL) OR (outcome IN ('unresolved', 'rejected') AND selected_assertion_id IS NULL)), \n\tCONSTRAINT ck_issuer_identifier_resolution_hashes CHECK (length(candidate_digest_sha256) = 64 AND length(policy_config_sha256) = 64), \n\tCONSTRAINT ck_issuer_identifier_resolution_clocks CHECK (knowledge_at >= effective_at AND recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(selected_assertion_id) REFERENCES issuer_identifier_assertions (assertion_id), \n\tFOREIGN KEY(supersedes_resolution_id) REFERENCES issuer_identifier_resolution_outcomes (resolution_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS issuer_profile_revisions (\n\tprofile_revision_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tissuer_id VARCHAR(128) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tlegal_name TEXT NOT NULL, \n\tdomicile_country VARCHAR(2), \n\tfiling_regime VARCHAR(32), \n\tfiscal_year_end VARCHAR(5), \n\tstatus VARCHAR(16) NOT NULL, \n\tdecision_kind VARCHAR(16) NOT NULL, \n\treason_code VARCHAR(128) NOT NULL, \n\treason_details_json TEXT NOT NULL, \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tsupersedes_profile_revision_id VARCHAR(128), \n\tPRIMARY KEY (profile_revision_id), \n\tCONSTRAINT uq_issuer_profile_revision UNIQUE (issuer_id, revision), \n\tCONSTRAINT ck_issuer_profile_revision CHECK (revision > 0), \n\tCONSTRAINT ck_issuer_profile_status CHECK (status IN ('active', 'inactive', 'merged', 'dissolved')), \n\tCONSTRAINT ck_issuer_profile_decision_kind CHECK (decision_kind IN ('deterministic', 'manual', 'imported')), \n\tCONSTRAINT ck_issuer_profile_country CHECK (domicile_country IS NULL OR length(domicile_country) = 2), \n\tCONSTRAINT ck_issuer_profile_fye CHECK (fiscal_year_end IS NULL OR fiscal_year_end GLOB '[0-1][0-9]-[0-3][0-9]'), \n\tCONSTRAINT ck_issuer_profile_clocks CHECK (knowledge_at >= effective_at AND recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(issuer_id) REFERENCES issuer_entities (issuer_id), \n\tFOREIGN KEY(supersedes_profile_revision_id) REFERENCES issuer_profile_revisions (profile_revision_id)\n)")
