    op.execute("CREATE TABLE IF NOT EXISTS ocr_page_results (\n\textraction_run_id VARCHAR(128) NOT NULL, \n\tpage_number INTEGER NOT NULL, \n\tnode_id VARCHAR(128), \n\toutcome VARCHAR(32) NOT NULL, \n\toutput_sha256 VARCHAR(64), \n\tmean_confidence FLOAT, \n\tlocator_json TEXT NOT NULL, \n\tlocator_sha256 VARCHAR(64) NOT NULL, \n\treason_code VARCHAR(128), \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (extraction_run_id, page_number), \n\tCONSTRAINT ck_ocr_page_result_page CHECK (page_number > 0), \n\tCONSTRAINT ck_ocr_page_result_outcome CHECK (outcome IN ('accepted', 'quarantined', 'failed')), \n\tCONSTRAINT ck_ocr_page_result_hashes CHECK (length(locator_sha256) = 64 AND (output_sha256 IS NULL OR length(output_sha256) = 64)), \n\tCONSTRAINT ck_ocr_page_result_confidence CHECK (mean_confidence IS NULL OR (mean_confidence >= 0.0 AND mean_confidence <= 100.0)), \n\tCONSTRAINT ck_ocr_page_result_shape CHECK ((outcome = 'accepted' AND node_id IS NOT NULL AND output_sha256 IS NOT NULL AND mean_confidence IS NOT NULL AND reason_code IS NULL) OR (outcome = 'quarantined' AND node_id IS NULL AND output_sha256 IS NOT NULL AND mean_confidence IS NOT NULL AND reason_code IS NOT NULL) OR (outcome = 'failed' AND node_id IS NULL AND output_sha256 IS NULL AND mean_confidence IS NULL AND reason_code IS NOT NULL)), \n\tFOREIGN KEY(extraction_run_id) REFERENCES ocr_extraction_governance (extraction_run_id), \n\tUNIQUE (node_id), \n\tFOREIGN KEY(node_id) REFERENCES evidence_nodes (node_id)\n)")
    op.execute('CREATE TABLE IF NOT EXISTS ocr_preflight_pages (\n\tassessment_id VARCHAR(128) NOT NULL, \n\tpage_number INTEGER NOT NULL, \n\tnative_character_count INTEGER NOT NULL, \n\tnative_text_sha256 VARCHAR(64) NOT NULL, \n\trequires_ocr BOOLEAN NOT NULL, \n\tPRIMARY KEY (assessment_id, page_number), \n\tCONSTRAINT ck_ocr_preflight_page_number CHECK (page_number > 0), \n\tCONSTRAINT ck_ocr_preflight_native_characters CHECK (native_character_count >= 0), \n\tCONSTRAINT ck_ocr_preflight_text_hash CHECK (length(native_text_sha256) = 64), \n\tFOREIGN KEY(assessment_id) REFERENCES ocr_document_assessments (assessment_id)\n)')
    op.execute('CREATE TABLE IF NOT EXISTS ontology_snapshot_headers (\n            ontology_snapshot_id TEXT PRIMARY KEY,\n            idempotency_key TEXT NOT NULL UNIQUE,\n            cutoff_at DATETIME NOT NULL,\n            recorded_at DATETIME NOT NULL,\n            CHECK(recorded_at >= cutoff_at)\n        )')
