    op.execute("CREATE TABLE IF NOT EXISTS optimizer_nominations (\n\tid INTEGER NOT NULL, \n\tnomination_run_id TEXT NOT NULL, \n\tpurpose TEXT NOT NULL, \n\tkind TEXT NOT NULL, \n\tpriority INTEGER NOT NULL, \n\theadroom_usd_30d FLOAT, \n\tcost_usd_30d FLOAT, \n\tcalls_30d INTEGER, \n\tincumbent_model TEXT NOT NULL, \n\tcandidates_json TEXT DEFAULT '[]' NOT NULL, \n\trationale TEXT NOT NULL, \n\trisk_tier TEXT NOT NULL, \n\tsuggested_min_n INTEGER, \n\tsource TEXT NOT NULL, \n\tladder_sha TEXT NOT NULL, \n\tstatus TEXT DEFAULT 'pending' NOT NULL, \n\texpires_at TEXT, \n\tcreated_at TEXT NOT NULL, \n\tupdated_at TEXT NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_optimizer_nominations_kind CHECK (kind IN ('model_downgrade','prompt_experiment','exclude')), \n\tCONSTRAINT ck_optimizer_nominations_risk CHECK (risk_tier IN ('safe','candidate','risky')), \n\tCONSTRAINT ck_optimizer_nominations_source CHECK (source IN ('opus','deterministic_fallback')), \n\tCONSTRAINT ck_optimizer_nominations_status CHECK (status IN ('pending','swept','skipped','expired'))\n)")
    op.execute('CREATE TABLE IF NOT EXISTS owner_profile_facts (\n\tid INTEGER NOT NULL, \n\tuser_id TEXT DEFAULT \'bhanu\' NOT NULL, \n\tcategory TEXT NOT NULL, \n\t"key" TEXT NOT NULL, \n\tvalue_json TEXT NOT NULL, \n\tnarrative TEXT NOT NULL, \n\tprovenance TEXT NOT NULL, \n\tstatus TEXT DEFAULT \'proposed\' NOT NULL, \n\taffirmed_at TEXT, \n\treview_horizon_days INTEGER, \n\tsource_detail TEXT, \n\tcreated_at TEXT NOT NULL, \n\tis_latest INTEGER DEFAULT \'1\' NOT NULL, \n\tsuperseded_at TEXT, \n\tsuperseded_by_id INTEGER, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_owner_profile_facts_category CHECK (category IN (\'capacity\',\'appetite\',\'behavioral\')), \n\tCONSTRAINT ck_owner_profile_facts_provenance CHECK (provenance IN (\'wealthplan_import\',\'cio_context_import\',\'owner\',\'derived\')), \n\tCONSTRAINT ck_owner_profile_facts_status CHECK (status IN (\'proposed\',\'affirmed\',\'rejected\'))\n)')
