    op.execute("CREATE TABLE IF NOT EXISTS pdf_table_extraction_artifact_headers (\n\tartifact_id VARCHAR(128) NOT NULL, \n\tdocument_version_id VARCHAR(128) NOT NULL, \n\textraction_run_id VARCHAR(128) NOT NULL, \n\tschema_version VARCHAR(64) NOT NULL, \n\tdisposition VARCHAR(32) NOT NULL, \n\tquarantine_reason VARCHAR(128), \n\traw_pdf_sha256 VARCHAR(64) NOT NULL, \n\traw_byte_count INTEGER NOT NULL, \n\tpdf_page_count INTEGER, \n\tdetector_name VARCHAR(128) NOT NULL, \n\tdetector_version VARCHAR(128) NOT NULL, \n\tpymupdf_version VARCHAR(64) NOT NULL, \n\tmupdf_version VARCHAR(64) NOT NULL, \n\textractor_code_version VARCHAR(255) NOT NULL, \n\tdetector_config_json TEXT NOT NULL, \n\tdetector_config_sha256 VARCHAR(64) NOT NULL, \n\tdetector_identity_sha256 VARCHAR(64) NOT NULL, \n\tordered_page_table_seal_sha256 VARCHAR(64) NOT NULL, \n\tartifact_json TEXT NOT NULL, \n\tartifact_sha256 VARCHAR(64) NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (artifact_id), \n\tCONSTRAINT ck_pdf_table_artifact_identity CHECK (schema_version='pdf-table-extraction@1' AND detector_name='PyMuPDF.Page.find_tables' AND detector_version='pymupdf-dual-table-detector@1'), \n\tCONSTRAINT ck_pdf_table_artifact_disposition CHECK ((disposition='sealed' AND quarantine_reason IS NULL AND pdf_page_count IS NOT NULL) OR (disposition='quarantined' AND quarantine_reason IS NOT NULL)), \n\tCONSTRAINT ck_pdf_table_artifact_hashes CHECK (raw_byte_count>=0 AND (pdf_page_count IS NULL OR pdf_page_count>=0) AND length(raw_pdf_sha256)=64 AND raw_pdf_sha256 NOT GLOB '*[^0-9a-f]*' AND length(detector_config_sha256)=64 AND detector_config_sha256 NOT GLOB '*[^0-9a-f]*' AND length(detector_identity_sha256)=64 AND detector_identity_sha256 NOT GLOB '*[^0-9a-f]*' AND length(ordered_page_table_seal_sha256)=64 AND ordered_page_table_seal_sha256 NOT GLOB '*[^0-9a-f]*' AND length(artifact_sha256)=64 AND artifact_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tCONSTRAINT ck_pdf_table_artifact_json CHECK (json_valid(detector_config_json) AND json_type(detector_config_json)='object' AND json_valid(artifact_json) AND json_type(artifact_json)='object'), \n\tFOREIGN KEY(document_version_id) REFERENCES evidence_document_versions (document_version_id), \n\tUNIQUE (extraction_run_id), \n\tFOREIGN KEY(extraction_run_id) REFERENCES evidence_extraction_runs (extraction_run_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS pdf_table_extraction_artifact_members (\n\tartifact_id VARCHAR(128) NOT NULL, \n\tmember_ordinal INTEGER NOT NULL, \n\tmember_kind VARCHAR(16) NOT NULL, \n\tnative_id VARCHAR(512) NOT NULL, \n\tnative_parent_id VARCHAR(512), \n\tlocator_json TEXT NOT NULL, \n\tlocator_sha256 VARCHAR(64) NOT NULL, \n\tdisposition VARCHAR(32), \n\tcanonical_object_json TEXT NOT NULL, \n\tcanonical_object_sha256 VARCHAR(64) NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (artifact_id, member_ordinal), \n\tCONSTRAINT uq_pdf_table_artifact_native_member UNIQUE (artifact_id, native_id), \n\tCONSTRAINT ck_pdf_table_artifact_member CHECK (member_ordinal>=0 AND member_kind IN ('page','table','row','cell') AND ((member_kind='page' AND disposition IN ('tables_detected','no_tables_detected','quarantined')) OR (member_kind<>'page' AND disposition IS NULL)) AND json_valid(locator_json) AND json_type(locator_json)='object' AND json_valid(canonical_object_json) AND json_type(canonical_object_json)='object' AND length(locator_sha256)=64 AND locator_sha256 NOT GLOB '*[^0-9a-f]*' AND length(canonical_object_sha256)=64 AND canonical_object_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tFOREIGN KEY(artifact_id) REFERENCES pdf_table_extraction_artifact_headers (artifact_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS pdf_table_extraction_artifact_seals (\n\tartifact_id VARCHAR(128) NOT NULL, \n\tmember_count INTEGER NOT NULL, \n\tcanonical_member_set_json TEXT NOT NULL, \n\tmember_set_sha256 VARCHAR(64) NOT NULL, \n\tsealed_at DATETIME NOT NULL, \n\tPRIMARY KEY (artifact_id), \n\tCONSTRAINT ck_pdf_table_artifact_seal CHECK (member_count>=0 AND json_valid(canonical_member_set_json) AND json_type(canonical_member_set_json)='array' AND length(member_set_sha256)=64 AND member_set_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tFOREIGN KEY(artifact_id) REFERENCES pdf_table_extraction_artifact_headers (artifact_id)\n)")
