    op.execute("CREATE TABLE IF NOT EXISTS population_cutover_audit_receipts (\n\tpopulation_run_id VARCHAR(128) NOT NULL, \n\tverifier_name VARCHAR(128) NOT NULL, \n\tverifier_version VARCHAR(64) NOT NULL, \n\tverifier_code_sha256 VARCHAR(64) NOT NULL, \n\tverifier_config_sha256 VARCHAR(64) NOT NULL, \n\tknowledge_cutoff DATETIME NOT NULL, \n\tobserved_through DATETIME NOT NULL, \n\tverified_at DATETIME NOT NULL, \n\trequired_gate_count INTEGER NOT NULL, \n\teligible_count INTEGER NOT NULL, \n\tverified_count INTEGER NOT NULL, \n\tfailed_count INTEGER NOT NULL, \n\tcanonical_evidence_json TEXT NOT NULL, \n\tevidence_sha256 VARCHAR(64) NOT NULL, \n\tcanonical_receipt_json TEXT NOT NULL, \n\treceipt_sha256 VARCHAR(64) NOT NULL, \n\tPRIMARY KEY (population_run_id), \n\tCONSTRAINT ck_population_cutover_audit_identity CHECK (verifier_name='population-cutover-readiness-auditor' AND verifier_version='2' AND length(verifier_code_sha256)=64 AND verifier_code_sha256 NOT GLOB '*[^0-9a-f]*' AND length(verifier_config_sha256)=64 AND verifier_config_sha256 NOT GLOB '*[^0-9a-f]*' AND length(evidence_sha256)=64 AND evidence_sha256 NOT GLOB '*[^0-9a-f]*' AND length(receipt_sha256)=64 AND receipt_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tCONSTRAINT ck_population_cutover_audit_counts CHECK (required_gate_count=13 AND eligible_count>0 AND verified_count=eligible_count AND failed_count=0), \n\tCONSTRAINT ck_population_cutover_audit_payload CHECK (observed_through>=knowledge_cutoff AND verified_at>=observed_through AND json_valid(canonical_evidence_json) AND json_type(canonical_evidence_json)='object' AND json_valid(canonical_receipt_json) AND json_type(canonical_receipt_json)='object'), \n\tFOREIGN KEY(population_run_id) REFERENCES population_run_headers (population_run_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS population_cutover_receipts (\n\tpopulation_run_id VARCHAR(128) NOT NULL, \n\trequired_plane_count INTEGER NOT NULL, \n\tcomplete_plane_count INTEGER NOT NULL, \n\taudit_receipt_sha256 VARCHAR(64) NOT NULL, \n\tcanonical_receipt_set_json TEXT NOT NULL, \n\treceipt_set_sha256 VARCHAR(64) NOT NULL, \n\tknowledge_cutoff DATETIME NOT NULL, \n\tobserved_through DATETIME NOT NULL, \n\tsealed_at DATETIME NOT NULL, \n\tPRIMARY KEY (population_run_id), \n\tCONSTRAINT ck_population_cutover_plane_counts CHECK (required_plane_count=7 AND complete_plane_count=7), \n\tCONSTRAINT ck_population_cutover_payload CHECK (length(audit_receipt_sha256)=64 AND audit_receipt_sha256 NOT GLOB '*[^0-9a-f]*' AND length(receipt_set_sha256)=64 AND receipt_set_sha256 NOT GLOB '*[^0-9a-f]*' AND json_valid(canonical_receipt_set_json) AND json_type(canonical_receipt_set_json)='object' AND observed_through>=knowledge_cutoff AND sealed_at>=observed_through), \n\tFOREIGN KEY(population_run_id) REFERENCES population_run_headers (population_run_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS population_parity_receipts (\n\tpopulation_run_id VARCHAR(128) NOT NULL, \n\teligible_legacy_count INTEGER NOT NULL, \n\tcanonical_count INTEGER NOT NULL, \n\tmatched_count INTEGER NOT NULL, \n\tmismatched_count INTEGER NOT NULL, \n\tabsent_count INTEGER NOT NULL, \n\textra_count INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tcanonical_report_json TEXT NOT NULL, \n\treport_sha256 VARCHAR(64) NOT NULL, \n\tknowledge_cutoff DATETIME NOT NULL, \n\tobserved_through DATETIME NOT NULL, \n\tverified_at DATETIME NOT NULL, \n\tPRIMARY KEY (population_run_id), \n\tCONSTRAINT ck_population_parity_conservation CHECK (eligible_legacy_count>0 AND canonical_count>0 AND matched_count>=0 AND mismatched_count>=0 AND absent_count>=0 AND extra_count>=0 AND eligible_legacy_count=matched_count+mismatched_count+absent_count AND canonical_count=matched_count+extra_count), \n\tCONSTRAINT ck_population_parity_status CHECK (status IN ('complete','blocked') AND ((status='complete' AND mismatched_count=0 AND absent_count=0 AND extra_count=0) OR (status='blocked' AND (mismatched_count>0 OR absent_count>0 OR extra_count>0)))), \n\tCONSTRAINT ck_population_parity_payload CHECK (length(report_sha256)=64 AND report_sha256 NOT GLOB '*[^0-9a-f]*' AND json_valid(canonical_report_json) AND json_type(canonical_report_json)='object'), \n\tFOREIGN KEY(population_run_id) REFERENCES population_run_headers (population_run_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS population_plane_receipts (\n\tpopulation_run_id VARCHAR(128) NOT NULL, \n\tplane_name VARCHAR(64) NOT NULL, \n\texpected_count INTEGER NOT NULL, \n\tmaterialized_count INTEGER NOT NULL, \n\texcluded_count INTEGER NOT NULL, \n\tfailed_count INTEGER NOT NULL, \n\tinput_commitment_sha256 VARCHAR(64) NOT NULL, \n\toutput_commitment_sha256 VARCHAR(64) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tcanonical_details_json TEXT NOT NULL, \n\tdetails_sha256 VARCHAR(64) NOT NULL, \n\tknowledge_cutoff DATETIME NOT NULL, \n\tobserved_through DATETIME NOT NULL, \n\tverified_at DATETIME NOT NULL, \n\tPRIMARY KEY (population_run_id, plane_name), \n\tCONSTRAINT ck_population_plane_name CHECK (plane_name IN ('identity_scope','source_fact_ontology','canonical_resolution','canonical_projection','document_processing','research_snapshot','retrieval_runtime')), \n\tCONSTRAINT ck_population_plane_conservation CHECK (expected_count>0 AND materialized_count>=0 AND excluded_count>=0 AND failed_count>=0 AND expected_count=materialized_count+excluded_count+failed_count), \n\tCONSTRAINT ck_population_plane_status CHECK (status IN ('complete','blocked') AND ((status='complete' AND failed_count=0 AND materialized_count>0) OR (status='blocked' AND (failed_count>0 OR materialized_count=0)))), \n\tCONSTRAINT ck_population_plane_payload CHECK (length(input_commitment_sha256)=64 AND input_commitment_sha256 NOT GLOB '*[^0-9a-f]*' AND length(output_commitment_sha256)=64 AND output_commitment_sha256 NOT GLOB '*[^0-9a-f]*' AND length(details_sha256)=64 AND details_sha256 NOT GLOB '*[^0-9a-f]*' AND json_valid(canonical_details_json) AND json_type(canonical_details_json)='object'), \n\tFOREIGN KEY(population_run_id) REFERENCES population_run_headers (population_run_id)\n)")
