    op.execute("CREATE TABLE IF NOT EXISTS search_index_memberships (\n\tindex_run_id VARCHAR(128) NOT NULL, \n\tchunk_id VARCHAR(128) NOT NULL, \n\tmembership_status VARCHAR(16) NOT NULL, \n\tfailure_reason TEXT, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (index_run_id, chunk_id), \n\tCONSTRAINT ck_search_index_membership_status CHECK (membership_status IN ('included', 'missing', 'quarantined', 'failed')), \n\tFOREIGN KEY(index_run_id) REFERENCES search_index_runs (index_run_id), \n\tFOREIGN KEY(chunk_id) REFERENCES search_chunks (chunk_id)\n)")
