    op.execute("CREATE TABLE IF NOT EXISTS security_listing_assertions (\n\tassertion_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tsecurity_id VARCHAR(128) NOT NULL, \n\tmarket_mic VARCHAR(8) NOT NULL, \n\tticker TEXT NOT NULL, \n\tnormalized_ticker TEXT NOT NULL, \n\tcurrency VARCHAR(3) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tauthority VARCHAR(32) NOT NULL, \n\tsource_observation_id VARCHAR(128), \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (assertion_id), \n\tCONSTRAINT ck_security_listing_mic CHECK (length(market_mic) BETWEEN 4 AND 8), \n\tCONSTRAINT ck_security_listing_currency CHECK (length(currency) = 3), \n\tCONSTRAINT ck_security_listing_status CHECK (status IN ('listed', 'delisted', 'suspended')), \n\tCONSTRAINT ck_security_listing_authority CHECK (authority IN ('issuer_publisher', 'sec_registry', 'exchange_registry', 'regulator', 'manual', 'imported')), \n\tCONSTRAINT ck_security_listing_evidence CHECK (authority = 'manual' OR source_observation_id IS NOT NULL), \n\tCONSTRAINT ck_security_listing_clocks CHECK (knowledge_at >= effective_at AND recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(security_id) REFERENCES securities (security_id), \n\tFOREIGN KEY(source_observation_id) REFERENCES evidence_source_observations (observation_id)\n)")
