    op.execute("CREATE TABLE IF NOT EXISTS signals (\n\tid INTEGER NOT NULL, \n\tticker TEXT NOT NULL, \n\tsignal_type TEXT NOT NULL, \n\ttitle TEXT NOT NULL, \n\tbody TEXT, \n\turl TEXT, \n\tfirm TEXT, \n\tevent_date TEXT(10), \n\tpublished_at TEXT NOT NULL, \n\tweight FLOAT DEFAULT (1.0) NOT NULL, \n\tcadence TEXT DEFAULT 'event' NOT NULL, \n\tsource_feed TEXT, \n\tnews_id INTEGER, \n\tcreated_at TEXT NOT NULL, quality_score FLOAT, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_signals_signal_type CHECK (signal_type IN ('buyside_rating', 'consensus_rating', 'estimate_revision', 'general_news', 'investor_day', 'media_appearance')), \n\tCONSTRAINT ck_signals_cadence CHECK (cadence IN ('event', 'quarterly', 'scheduled'))\n)")
