    op.execute("CREATE TABLE IF NOT EXISTS source_coverage_assessments (\n\tassessment_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\texpected_document_id VARCHAR(128) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tcoverage_status VARCHAR(32) NOT NULL, \n\tdocument_version_id VARCHAR(128), \n\textraction_run_id VARCHAR(128), \n\tmanifest_id VARCHAR(128), \n\tindex_run_id VARCHAR(128), \n\treason_code VARCHAR(128) NOT NULL, \n\treason_details_json TEXT NOT NULL, \n\tdecision_kind VARCHAR(16) NOT NULL, \n\tpolicy_name VARCHAR(128) NOT NULL, \n\tpolicy_version VARCHAR(128) NOT NULL, \n\tpolicy_config_sha256 VARCHAR(64) NOT NULL, \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tsupersedes_assessment_id VARCHAR(128), \n\tmaterial_dissent BOOLEAN NOT NULL, \n\tPRIMARY KEY (assessment_id), \n\tCONSTRAINT uq_source_coverage_assessment_revision UNIQUE (expected_document_id, revision), \n\tCONSTRAINT ck_source_coverage_revision CHECK (revision > 0), \n\tCONSTRAINT ck_source_coverage_status CHECK (coverage_status IN ('available', 'not_published', 'not_discovered', 'fetch_failed', 'quarantined', 'captured', 'extracted', 'indexed', 'unsupported', 'authority_unavailable')), \n\tCONSTRAINT ck_source_coverage_lineage CHECK ((coverage_status NOT IN ('captured', 'extracted', 'indexed') OR document_version_id IS NOT NULL) AND (coverage_status NOT IN ('extracted', 'indexed') OR extraction_run_id IS NOT NULL) AND (coverage_status <> 'indexed' OR (manifest_id IS NOT NULL AND index_run_id IS NOT NULL))), \n\tCONSTRAINT ck_source_coverage_decision_kind CHECK (decision_kind IN ('deterministic', 'manual', 'imported')), \n\tCONSTRAINT ck_source_coverage_policy_hash CHECK (length(policy_config_sha256) = 64), \n\tCONSTRAINT ck_source_coverage_clocks CHECK (knowledge_at >= effective_at AND recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(expected_document_id) REFERENCES expected_documents (expected_document_id), \n\tFOREIGN KEY(document_version_id) REFERENCES evidence_document_versions (document_version_id), \n\tFOREIGN KEY(extraction_run_id) REFERENCES evidence_extraction_runs (extraction_run_id), \n\tFOREIGN KEY(manifest_id) REFERENCES search_corpus_manifests (manifest_id), \n\tFOREIGN KEY(index_run_id) REFERENCES search_index_runs (index_run_id), \n\tFOREIGN KEY(supersedes_assessment_id) REFERENCES source_coverage_assessments (assessment_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS source_dimension_mapping_revisions (\n            dimension_mapping_revision_id TEXT PRIMARY KEY,\n            idempotency_key TEXT NOT NULL UNIQUE,\n            source_component_id TEXT NOT NULL\n                REFERENCES source_taxonomy_components(component_id),\n            revision INTEGER NOT NULL CHECK(revision > 0),\n            supersedes_dimension_mapping_revision_id TEXT\n                REFERENCES source_dimension_mapping_revisions(\n                    dimension_mapping_revision_id),\n            disposition TEXT NOT NULL CHECK(disposition IN\n                ('exact','equivalent','ambiguous','not_applicable','quarantined')),\n            canonical_axis_id TEXT REFERENCES canonical_axes(axis_id),\n            canonical_member_id TEXT,\n            policy_name TEXT NOT NULL,\n            policy_version TEXT NOT NULL,\n            policy_config_sha256 TEXT NOT NULL\n                CHECK(length(policy_config_sha256)=64\n                      AND policy_config_sha256 NOT GLOB '*[^0-9a-f]*'),\n            evidence_json TEXT NOT NULL\n                CHECK(json_valid(evidence_json) AND json_type(evidence_json)='object'),\n            evidence_sha256 TEXT NOT NULL\n                CHECK(length(evidence_sha256)=64\n                      AND evidence_sha256 NOT GLOB '*[^0-9a-f]*'),\n            reviewer_identity TEXT,\n            audited_policy_path TEXT,\n            commitment_json TEXT NOT NULL\n                CHECK(json_valid(commitment_json)\n                      AND json_type(commitment_json)='object'),\n            commitment_sha256 TEXT NOT NULL\n                CHECK(length(commitment_sha256)=64\n                      AND commitment_sha256 NOT GLOB '*[^0-9a-f]*'),\n            effective_at DATETIME NOT NULL,\n            knowledge_at DATETIME NOT NULL,\n            recorded_at DATETIME NOT NULL,\n            UNIQUE(source_component_id, revision),\n            FOREIGN KEY(canonical_axis_id, canonical_member_id)\n                REFERENCES canonical_members(axis_id, member_id),\n            CHECK((revision=1)=(supersedes_dimension_mapping_revision_id IS NULL)),\n            CHECK(\n                (disposition IN ('exact','equivalent')\n                 AND canonical_axis_id IS NOT NULL)\n                OR\n                (disposition IN ('ambiguous','not_applicable','quarantined')\n                 AND canonical_axis_id IS NULL AND canonical_member_id IS NULL)\n            ),\n            CHECK(effective_at <= knowledge_at AND knowledge_at <= recorded_at)\n        )")
    op.execute("CREATE TABLE IF NOT EXISTS source_fact_publication_members (\n\tpublication_member_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tpublication_id VARCHAR(128) NOT NULL, \n\tmember_ordinal INTEGER NOT NULL, \n\trecord_kind VARCHAR(32) NOT NULL, \n\trecord_id VARCHAR(128) NOT NULL, \n\trecord_idempotency_key VARCHAR(256) NOT NULL, \n\trecord_commitment_version VARCHAR(64) NOT NULL, \n\trecord_commitment_sha256 VARCHAR(64) NOT NULL, \n\tcanonical_member_json TEXT NOT NULL, \n\tcanonical_member_sha256 VARCHAR(64) NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (publication_member_id), \n\tCONSTRAINT uq_source_fact_publication_member_ordinal UNIQUE (publication_id, member_ordinal), \n\tCONSTRAINT uq_source_fact_publication_member_record UNIQUE (publication_id, record_kind, record_id), \n\tCONSTRAINT ck_source_fact_publication_member_ordinal CHECK (member_ordinal >= 0), \n\tCONSTRAINT ck_source_fact_publication_member_kind CHECK (record_kind IN ('fact_cell','fact_observation','observation_relation','derivation_seal','extraction_seal','resolution_revision')), \n\tCONSTRAINT ck_source_fact_publication_member_commitment_version CHECK (record_commitment_version = 'source_fact_record_commitment.v1'), \n\tCONSTRAINT ck_source_fact_publication_member_hashes CHECK (length(record_commitment_sha256) = 64 AND record_commitment_sha256 NOT GLOB '*[^0-9a-f]*' AND length(canonical_member_sha256) = 64 AND canonical_member_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tCONSTRAINT ck_source_fact_publication_member_json CHECK (json_valid(canonical_member_json) AND json_type(canonical_member_json) = 'object'), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(publication_id) REFERENCES source_fact_publications (publication_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS source_fact_publication_seals (\n\tpublication_seal_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tpublication_id VARCHAR(128) NOT NULL, \n\tmember_count INTEGER NOT NULL, \n\tcanonical_member_set_json TEXT NOT NULL, \n\tmember_set_sha256 VARCHAR(64) NOT NULL, \n\tpublication_payload_sha256 VARCHAR(64) NOT NULL, \n\tsealed_at DATETIME NOT NULL, \n\tPRIMARY KEY (publication_seal_id), \n\tCONSTRAINT ck_source_fact_publication_seal_count CHECK (member_count >= 0), \n\tCONSTRAINT ck_source_fact_publication_seal_json CHECK (json_valid(canonical_member_set_json) AND json_type(canonical_member_set_json) = 'array'), \n\tCONSTRAINT ck_source_fact_publication_seal_hashes CHECK (length(member_set_sha256) = 64 AND member_set_sha256 NOT GLOB '*[^0-9a-f]*' AND length(publication_payload_sha256) = 64 AND publication_payload_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tUNIQUE (idempotency_key), \n\tUNIQUE (publication_id), \n\tFOREIGN KEY(publication_id) REFERENCES source_fact_publications (publication_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS source_fact_publication_stream (\n\tpublication_sequence INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, \n\tstream_id VARCHAR(64) NOT NULL, \n\tpublication_id VARCHAR(128) NOT NULL, \n\tpublication_seal_id VARCHAR(128) NOT NULL, \n\tpublication_payload_sha256 VARCHAR(64) NOT NULL, \n\tmember_set_sha256 VARCHAR(64) NOT NULL, \n\tsequence_basis VARCHAR(32) NOT NULL, \n\tsealed_at DATETIME NOT NULL, \n\tassigned_at DATETIME NOT NULL, \n\tevent_version VARCHAR(64) NOT NULL, \n\tcanonical_event_json TEXT NOT NULL, \n\tevent_sha256 VARCHAR(64) NOT NULL, \n\tCONSTRAINT ck_source_fact_publication_stream_sequence CHECK (publication_sequence > 0), \n\tCONSTRAINT ck_source_fact_publication_stream_id CHECK (stream_id = 'source-fact-publication-stream-v1'), \n\tCONSTRAINT ck_source_fact_publication_stream_basis CHECK (sequence_basis IN ('legacy_backfill','transactional_publish')), \n\tCONSTRAINT ck_source_fact_publication_stream_version CHECK (event_version = 'source_fact_publication_event.v1'), \n\tCONSTRAINT ck_source_fact_publication_stream_clocks CHECK (assigned_at >= sealed_at), \n\tCONSTRAINT ck_source_fact_publication_stream_json CHECK (json_valid(canonical_event_json) AND json_type(canonical_event_json) = 'object'), \n\tCONSTRAINT ck_source_fact_publication_stream_hashes CHECK (length(publication_payload_sha256)=64 AND publication_payload_sha256 NOT GLOB '*[^0-9a-f]*' AND length(member_set_sha256)=64 AND member_set_sha256 NOT GLOB '*[^0-9a-f]*' AND length(event_sha256)=64 AND event_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tUNIQUE (publication_id), \n\tFOREIGN KEY(publication_id) REFERENCES source_fact_publications (publication_id), \n\tUNIQUE (publication_seal_id), \n\tFOREIGN KEY(publication_seal_id) REFERENCES source_fact_publication_seals (publication_seal_id)\n)")
    op.execute('CREATE TABLE IF NOT EXISTS source_fact_publication_stream_clock (\n\tsingleton_key INTEGER NOT NULL, \n\tnext_sequence INTEGER NOT NULL, \n\tPRIMARY KEY (singleton_key), \n\tCONSTRAINT ck_source_fact_publication_stream_clock CHECK (singleton_key = 1 AND next_sequence > 0)\n)')
    op.execute("CREATE TABLE IF NOT EXISTS source_fact_publications (\n\tpublication_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tpayload_version VARCHAR(64) NOT NULL, \n\tcanonical_publication_payload_json TEXT NOT NULL, \n\tpublication_payload_sha256 VARCHAR(64) NOT NULL, \n\tmember_set_sha256 VARCHAR(64) NOT NULL, \n\tcell_count INTEGER NOT NULL, \n\tobservation_count INTEGER NOT NULL, \n\trelation_count INTEGER NOT NULL, \n\tderivation_seal_count INTEGER NOT NULL, \n\textraction_seal_count INTEGER NOT NULL, \n\tresolution_revision_count INTEGER NOT NULL, \n\tmember_count INTEGER NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (publication_id), \n\tCONSTRAINT ck_source_fact_publication_version CHECK (payload_version = 'source_fact_publication.v1'), \n\tCONSTRAINT ck_source_fact_publication_json CHECK (json_valid(canonical_publication_payload_json) AND json_type(canonical_publication_payload_json) = 'object'), \n\tCONSTRAINT ck_source_fact_publication_hashes CHECK (length(publication_payload_sha256) = 64 AND publication_payload_sha256 NOT GLOB '*[^0-9a-f]*' AND length(member_set_sha256) = 64 AND member_set_sha256 NOT GLOB '*[^0-9a-f]*'), \n\tCONSTRAINT ck_source_fact_publication_counts CHECK (cell_count >= 0 AND observation_count >= 0 AND relation_count >= 0 AND derivation_seal_count >= 0 AND extraction_seal_count >= 0 AND resolution_revision_count >= 0 AND member_count = cell_count + observation_count + relation_count + derivation_seal_count + extraction_seal_count + resolution_revision_count), \n\tCONSTRAINT ck_source_fact_publication_clocks CHECK (recorded_at >= created_at), \n\tUNIQUE (idempotency_key)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS source_inventory_components (\n\tcomponent_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tsnapshot_id VARCHAR(128) NOT NULL, \n\tcomponent_key VARCHAR(256) NOT NULL, \n\tcomponent_kind VARCHAR(32) NOT NULL, \n\tsource_url TEXT NOT NULL, \n\tsource_observation_id VARCHAR(128), \n\toutcome VARCHAR(16) NOT NULL, \n\trequired BOOLEAN NOT NULL, \n\tfailure_reason VARCHAR(128), \n\tordinal INTEGER NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tPRIMARY KEY (component_id), \n\tCONSTRAINT uq_source_inventory_component_key UNIQUE (snapshot_id, component_key), \n\tCONSTRAINT uq_source_inventory_component_ordinal UNIQUE (snapshot_id, ordinal), \n\tCONSTRAINT ck_source_inventory_component_kind CHECK (component_kind IN ('primary', 'historical_page', 'crawl_page', 'event_feed', 'other')), \n\tCONSTRAINT ck_source_inventory_component_outcome CHECK (outcome IN ('succeeded', 'failed')), \n\tCONSTRAINT ck_source_inventory_component_ordinal CHECK (ordinal >= 0), \n\tCONSTRAINT ck_source_inventory_component_lineage CHECK ((outcome = 'succeeded' AND source_observation_id IS NOT NULL AND failure_reason IS NULL) OR (outcome = 'failed' AND source_observation_id IS NULL AND failure_reason IS NOT NULL)), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(snapshot_id) REFERENCES source_inventory_snapshots (snapshot_id), \n\tFOREIGN KEY(source_observation_id) REFERENCES evidence_source_observations (observation_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS source_inventory_snapshot_seals (\n\tsnapshot_id VARCHAR(128) NOT NULL, \n\texpected_component_count INTEGER NOT NULL, \n\tcomponent_digest_sha256 VARCHAR(64) NOT NULL, \n\tcompletion_status VARCHAR(16) NOT NULL, \n\tsealed_at DATETIME NOT NULL, \n\tPRIMARY KEY (snapshot_id), \n\tCONSTRAINT ck_source_inventory_seal_count CHECK (expected_component_count > 0), \n\tCONSTRAINT ck_source_inventory_seal_digest CHECK (length(component_digest_sha256) = 64), \n\tCONSTRAINT ck_source_inventory_seal_status CHECK (completion_status IN ('complete', 'incomplete')), \n\tFOREIGN KEY(snapshot_id) REFERENCES source_inventory_snapshots (snapshot_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS source_inventory_snapshots (\n\tsnapshot_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tinventory_key VARCHAR(256) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tissuer_id VARCHAR(128) NOT NULL, \n\tticker VARCHAR(32), \n\tsource_kind VARCHAR(32) NOT NULL, \n\tsource_url TEXT NOT NULL, \n\tsource_observation_id VARCHAR(128), \n\toutcome VARCHAR(16) NOT NULL, \n\tauthoritative BOOLEAN NOT NULL, \n\tretrieval_config_sha256 VARCHAR(64) NOT NULL, \n\tcollector_code_version VARCHAR(255) NOT NULL, \n\tstarted_at DATETIME NOT NULL, \n\tcompleted_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tsupersedes_snapshot_id VARCHAR(128), \n\tPRIMARY KEY (snapshot_id), \n\tCONSTRAINT uq_source_inventory_snapshot_revision UNIQUE (inventory_key, revision), \n\tCONSTRAINT ck_source_inventory_revision CHECK (revision > 0), \n\tCONSTRAINT ck_source_inventory_kind CHECK (source_kind IN ('sec_submissions', 'ir_crawl', 'earnings_events')), \n\tCONSTRAINT ck_source_inventory_outcome CHECK (outcome IN ('succeeded', 'partial', 'failed')), \n\tCONSTRAINT ck_source_inventory_observation CHECK ((outcome IN ('succeeded', 'partial') AND source_observation_id IS NOT NULL) OR (outcome = 'failed' AND source_observation_id IS NULL)), \n\tCONSTRAINT ck_source_inventory_config_hash CHECK (length(retrieval_config_sha256) = 64), \n\tCONSTRAINT ck_source_inventory_clocks CHECK (completed_at >= started_at AND recorded_at >= completed_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(source_observation_id) REFERENCES evidence_source_observations (observation_id), \n\tFOREIGN KEY(supersedes_snapshot_id) REFERENCES source_inventory_snapshots (snapshot_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS source_obligation_revisions (\n\tobligation_revision_id VARCHAR(128) NOT NULL, \n\tidempotency_key VARCHAR(256) NOT NULL, \n\tobligation_key VARCHAR(256) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tissuer_id VARCHAR(128) NOT NULL, \n\treporting_entity_id VARCHAR(128), \n\tauthority_kind VARCHAR(32) NOT NULL, \n\tdocument_family VARCHAR(64) NOT NULL, \n\tobligation_state VARCHAR(16) NOT NULL, \n\tcompleteness_rule VARCHAR(32) NOT NULL, \n\tactive_from DATETIME NOT NULL, \n\tactive_to DATETIME, \n\tdecision_kind VARCHAR(16) NOT NULL, \n\treason_code VARCHAR(128) NOT NULL, \n\treason_details_json TEXT NOT NULL, \n\teffective_at DATETIME NOT NULL, \n\tknowledge_at DATETIME NOT NULL, \n\trecorded_at DATETIME NOT NULL, \n\tsupersedes_obligation_revision_id VARCHAR(128), \n\tPRIMARY KEY (obligation_revision_id), \n\tCONSTRAINT uq_source_obligation_revision UNIQUE (obligation_key, revision), \n\tCONSTRAINT ck_source_obligation_revision CHECK (revision > 0), \n\tCONSTRAINT ck_source_obligation_authority CHECK (authority_kind IN ('sec_edgar', 'sedar_plus', 'edinet', 'issuer_publisher')), \n\tCONSTRAINT ck_source_obligation_document_family CHECK (document_family IN ('operating_company_periodic', 'investment_company_periodic', 'continuous_disclosure', 'annual_securities_report', 'issuer_financial_statements', 'issuer_presentations', 'issuer_earnings_materials')), \n\tCONSTRAINT ck_source_obligation_state CHECK (obligation_state IN ('required', 'optional', 'not_applicable')), \n\tCONSTRAINT ck_source_obligation_completeness CHECK (completeness_rule IN ('regulator_inventory', 'publisher_surface_exhaustion', 'manual_exception')), \n\tCONSTRAINT ck_source_obligation_active_window CHECK (active_to IS NULL OR active_to > active_from), \n\tCONSTRAINT ck_source_obligation_decision CHECK (decision_kind IN ('deterministic', 'manual', 'imported')), \n\tCONSTRAINT ck_source_obligation_clocks CHECK (knowledge_at >= effective_at AND recorded_at >= knowledge_at), \n\tUNIQUE (idempotency_key), \n\tFOREIGN KEY(issuer_id) REFERENCES issuer_entities (issuer_id), \n\tFOREIGN KEY(reporting_entity_id) REFERENCES reporting_entities (reporting_entity_id), \n\tFOREIGN KEY(supersedes_obligation_revision_id) REFERENCES source_obligation_revisions (obligation_revision_id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS source_observation_taxonomy_assertions (\n            observation_id TEXT PRIMARY KEY\n                REFERENCES fact_observations_v2(observation_id),\n            idempotency_key TEXT NOT NULL UNIQUE,\n            extraction_run_id TEXT NOT NULL\n                REFERENCES evidence_extraction_runs(extraction_run_id),\n            taxonomy_name TEXT NOT NULL,\n            taxonomy_version TEXT NOT NULL,\n            fact_cell_semantic_key_sha256 TEXT NOT NULL\n                CHECK(length(fact_cell_semantic_key_sha256)=64\n                      AND fact_cell_semantic_key_sha256\n                          NOT GLOB '*[^0-9a-f]*'),\n            anchor_payload_sha256 TEXT NOT NULL\n                CHECK(length(anchor_payload_sha256)=64\n                      AND anchor_payload_sha256 NOT GLOB '*[^0-9a-f]*'),\n            observation_payload_sha256 TEXT NOT NULL\n                CHECK(length(observation_payload_sha256)=64\n                      AND observation_payload_sha256\n                          NOT GLOB '*[^0-9a-f]*'),\n            extraction_output_sha256 TEXT NOT NULL\n                CHECK(length(extraction_output_sha256)=64\n                      AND extraction_output_sha256\n                          NOT GLOB '*[^0-9a-f]*'),\n            raw_entry_sha256 TEXT NOT NULL\n                CHECK(length(raw_entry_sha256)=64\n                      AND raw_entry_sha256 NOT GLOB '*[^0-9a-f]*'),\n            observation_set_sha256 TEXT NOT NULL\n                CHECK(length(observation_set_sha256)=64\n                      AND observation_set_sha256\n                          NOT GLOB '*[^0-9a-f]*'),\n            commitment_json TEXT NOT NULL\n                CHECK(json_valid(commitment_json)\n                      AND json_type(commitment_json)='object'),\n            commitment_sha256 TEXT NOT NULL\n                CHECK(length(commitment_sha256)=64\n                      AND commitment_sha256 NOT GLOB '*[^0-9a-f]*'),\n            knowledge_at DATETIME NOT NULL,\n            recorded_at DATETIME NOT NULL,\n            CHECK(knowledge_at <= recorded_at)\n        )")
    op.execute("CREATE TABLE IF NOT EXISTS source_taxonomy_components (\n            component_id TEXT PRIMARY KEY,\n            idempotency_key TEXT NOT NULL UNIQUE,\n            component_kind TEXT NOT NULL\n                CHECK(component_kind IN ('concept','axis','member')),\n            taxonomy_namespace TEXT NOT NULL,\n            local_name TEXT NOT NULL,\n            taxonomy_name TEXT NOT NULL,\n            taxonomy_version TEXT NOT NULL,\n            definition_qualifier_sha256 TEXT NOT NULL\n                CHECK(length(definition_qualifier_sha256)=64\n                      AND definition_qualifier_sha256\n                          NOT GLOB '*[^0-9a-f]*'),\n            reporting_entity_id TEXT REFERENCES reporting_entities(\n                reporting_entity_id),\n            reporting_entity_scope_key TEXT NOT NULL,\n            is_extension INTEGER NOT NULL CHECK(is_extension IN (0,1)),\n            data_type TEXT,\n            period_type TEXT CHECK(period_type IS NULL\n                                   OR period_type IN ('instant','duration')),\n            balance TEXT CHECK(balance IS NULL OR balance IN ('debit','credit')),\n            is_abstract INTEGER CHECK(is_abstract IS NULL\n                                      OR is_abstract IN (0,1)),\n            standard_label TEXT,\n            definition_text TEXT,\n            references_json TEXT NOT NULL\n                CHECK(json_valid(references_json)\n                      AND json_type(references_json)='array'),\n            evidence_locator_json TEXT NOT NULL\n                CHECK(json_valid(evidence_locator_json)\n                      AND json_type(evidence_locator_json)='object'),\n            commitment_json TEXT NOT NULL\n                CHECK(json_valid(commitment_json)\n                      AND json_type(commitment_json)='object'),\n            commitment_sha256 TEXT NOT NULL\n                CHECK(length(commitment_sha256)=64\n                      AND commitment_sha256 NOT GLOB '*[^0-9a-f]*'),\n            effective_at DATETIME NOT NULL,\n            knowledge_at DATETIME NOT NULL,\n            recorded_at DATETIME NOT NULL,\n            UNIQUE(component_kind, taxonomy_namespace, local_name,\n                   taxonomy_name, taxonomy_version, definition_qualifier_sha256, reporting_entity_scope_key),\n            CHECK(reporting_entity_scope_key =\n                  COALESCE(reporting_entity_id, '__global__')),\n            CHECK(is_extension=0 OR reporting_entity_id IS NOT NULL),\n            CHECK(effective_at <= knowledge_at AND knowledge_at <= recorded_at)\n        )")
    op.execute('CREATE TABLE IF NOT EXISTS stage_transitions (\n\tid INTEGER NOT NULL, \n\trun_id VARCHAR NOT NULL, \n\tticker VARCHAR NOT NULL, \n\tperiod_end DATETIME, \n\tstage VARCHAR NOT NULL, \n\tstatus VARCHAR NOT NULL, \n\tstarted_at DATETIME NOT NULL, \n\tended_at DATETIME, \n\terror_msg TEXT, \n\tPRIMARY KEY (id)\n)')
    op.execute("CREATE TABLE IF NOT EXISTS stance_scores (\n\tid INTEGER NOT NULL, \n\tmemo_id INTEGER NOT NULL, \n\tuser_id TEXT DEFAULT 'bhanu' NOT NULL, \n\tverdict TEXT NOT NULL, \n\tbenchmark_basis TEXT DEFAULT 'none' NOT NULL, \n\thorizon_days INTEGER NOT NULL, \n\tstart_date TEXT, \n\tend_date TEXT, \n\tticker TEXT, \n\tcounter_ticker TEXT, \n\tticker_return_pct FLOAT, \n\tbenchmark_return_pct FLOAT, \n\texcess_return_pct FLOAT, \n\tcounter_return_pct FLOAT, \n\tdetail_json TEXT, \n\tcreated_at TEXT NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_stance_scores_verdict CHECK (verdict IN ('correct', 'wrong', 'mixed', 'screen_validated', 'screen_refuted', 'unscoreable')), \n\tCONSTRAINT ck_stance_scores_benchmark_basis CHECK (benchmark_basis IN ('tracker_spy', 'absolute', 'none'))\n)")
    op.execute("CREATE TABLE IF NOT EXISTS standup_messages (\n\tid INTEGER NOT NULL, \n\tuser_id TEXT DEFAULT 'bhanu' NOT NULL, \n\tticker TEXT, \n\tsignal_kind TEXT NOT NULL, \n\tsignature_sha TEXT NOT NULL, \n\tstatus TEXT NOT NULL, \n\tscore FLOAT, \n\tsession_id TEXT, \n\tturn_id INTEGER, \n\tconclusion TEXT, \n\theadline TEXT, \n\tevidence_json TEXT, \n\tcreated_at TEXT NOT NULL, \n\tPRIMARY KEY (id)\n)")
    op.execute("CREATE TABLE IF NOT EXISTS strategic_targets (\n\tid INTEGER NOT NULL, \n\tticker VARCHAR(16) NOT NULL, \n\tdeck_doc_id INTEGER, \n\ttarget_kind VARCHAR(32) NOT NULL, \n\ttarget_value NUMERIC(20, 4), \n\ttarget_unit VARCHAR(16) NOT NULL, \n\ttarget_period VARCHAR(16) NOT NULL, \n\ttarget_currency VARCHAR(8), \n\tnarrative_excerpt TEXT NOT NULL, \n\textracted_at DATETIME NOT NULL, \n\tconfidence FLOAT DEFAULT '1.0' NOT NULL, \n\tPRIMARY KEY (id)\n)")
