    op.execute('CREATE TABLE IF NOT EXISTS "thesis_ledger_entries" (\n\tid INTEGER NOT NULL, \n\tuser_id TEXT DEFAULT \'bhanu\' NOT NULL, \n\tticker TEXT NOT NULL, \n\tentry_kind TEXT NOT NULL, \n\tbody TEXT NOT NULL, \n\tsource_alert_id INTEGER, \n\tcreated_at TEXT NOT NULL, \n\taccepted_at TEXT NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT fk_thesis_ledger_entries_user_id_tenants FOREIGN KEY(user_id) REFERENCES tenants (id)\n)')
