    op.execute('CREATE TABLE IF NOT EXISTS ticker_settings (\n\tid INTEGER NOT NULL, \n\tticker TEXT NOT NULL, \n\tbypass_budget INTEGER DEFAULT 0 NOT NULL, \n\tcreated_at TEXT NOT NULL, \n\tupdated_at TEXT NOT NULL, auto_pre_earnings_brief INTEGER NOT NULL DEFAULT 0, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_ticker_settings_ticker UNIQUE (ticker)\n)')
    op.execute("CREATE TABLE IF NOT EXISTS timeseries_signals (\n\tid INTEGER NOT NULL, \n\tticker VARCHAR(16) NOT NULL, \n\tmetric_name VARCHAR(128) NOT NULL, \n\tmetric_kind VARCHAR(16) NOT NULL, \n\tsignal_type VARCHAR(32) NOT NULL, \n\tvalue_json TEXT NOT NULL, \n\tseverity VARCHAR(8) NOT NULL, \n\tnarrative TEXT, \n\tcomputed_at DATETIME NOT NULL, \n\trun_id VARCHAR(64), \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_timeseries_signals_metric_kind CHECK (metric_kind IN ('financial', 'kpi', 'segment')), \n\tCONSTRAINT ck_timeseries_signals_signal_type CHECK (signal_type IN ('trend', 'inflection', 'anomaly', 'yoy_acceleration', 'seasonal', 'correlation')), \n\tCONSTRAINT ck_timeseries_signals_severity CHECK (severity IN ('green', 'yellow', 'red')), \n\tCONSTRAINT uq_timeseries_signals_logical UNIQUE (ticker, metric_name, metric_kind, signal_type)\n)")
