    op.execute('CREATE UNIQUE INDEX IF NOT EXISTS uq_user_kpi_registry_user_ticker_kpi ON user_kpi_registry (user_id, ticker, kpi_name)')
    op.execute('CREATE UNIQUE INDEX IF NOT EXISTS uq_validation_issues_fingerprint ON validation_issues(fingerprint) WHERE fingerprint IS NOT NULL')
    op.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_earnings_surprises_ticker_release ON earnings_surprises (ticker, release_date)')
    op.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_expected_earnings_ticker_date ON expected_earnings (ticker, expected_date)')
    op.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_owner_profile_facts_latest ON owner_profile_facts(user_id, category, key) WHERE is_latest = 1')
    op.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_positioning_intents_latest ON positioning_intents(user_id) WHERE is_latest = 1')
    op.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_raw_capture_external ON raw_capture_sessions (channel, external_ref) WHERE external_ref IS NOT NULL')
    op.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_signals_event ON signals (ticker, signal_type, event_date) WHERE event_date IS NOT NULL')
    op.execute("CREATE UNIQUE INDEX IF NOT EXISTS ux_signals_media_url ON signals (ticker, url) WHERE signal_type = 'media_appearance' AND url IS NOT NULL")
    op.execute('CREATE UNIQUE INDEX IF NOT EXISTS ux_signals_news_id ON signals (news_id) WHERE news_id IS NOT NULL')

    # Created views
    op.execute("CREATE VIEW IF NOT EXISTS metrics AS\nWITH dedup AS (\n    SELECT\n        ticker,\n        CAST(substr(period_end, 1, 4) AS INTEGER) AS fiscal_year,\n        fiscal_period_type,\n        line_item,\n        value,\n        currency,\n        period_end,\n        ROW_NUMBER() OVER (\n            PARTITION BY\n                ticker,\n                CAST(substr(period_end, 1, 4) AS INTEGER),\n                fiscal_period_type,\n                line_item\n            ORDER BY source_doc_id DESC, period_end DESC\n        ) AS rn\n    FROM financial_facts\n)\nSELECT\n    ticker,\n    fiscal_year,\n    fiscal_period_type,\n    MAX(period_end) AS period_end,\n    MAX(currency) AS currency,\n    MAX(CASE WHEN line_item = 'revenue' THEN value END) AS revenue,\n    MAX(CASE WHEN line_item = 'cost_of_revenue' THEN value END) AS cost_of_revenue,\n    MAX(CASE WHEN line_item = 'gross_profit' THEN value END) AS gross_profit,\n    MAX(CASE WHEN line_item = 'research_and_development' THEN value END) AS rd,\n    MAX(CASE WHEN line_item = 'sga' THEN value END) AS sga,\n    MAX(CASE WHEN line_item = 'operating_expenses' THEN value END) AS operating_expenses,\n    MAX(CASE WHEN line_item = 'operating_income' THEN value END) AS operating_income,\n    MAX(CASE WHEN line_item = 'ebit' THEN value END) AS ebit,\n    MAX(CASE WHEN line_item = 'ebitda' THEN value END) AS ebitda,\n    MAX(CASE WHEN line_item = 'net_income' THEN value END) AS net_income,\n    MAX(CASE WHEN line_item = 'eps' THEN value END) AS eps,\n    MAX(CASE WHEN line_item = 'eps_diluted' THEN value END) AS eps_diluted,\n    MAX(CASE WHEN line_item = 'weighted_avg_shares_diluted' THEN value END)\n        AS weighted_avg_shares_diluted,\n    MAX(CASE WHEN line_item = 'total_assets' THEN value END) AS total_assets,\n    MAX(CASE WHEN line_item = 'total_current_assets' THEN value END) AS total_current_assets,\n    MAX(CASE WHEN line_item = 'cash_and_equivalents' THEN value END) AS cash_and_equivalents,\n    MAX(CASE WHEN line_item = 'total_liabilities' THEN value END) AS total_liabilities,\n    MAX(CASE WHEN line_item = 'total_current_liabilities' THEN value END)\n        AS total_current_liabilities,\n    MAX(CASE WHEN line_item = 'total_stockholders_equity' THEN value END) AS total_equity,\n    MAX(CASE WHEN line_item = 'total_debt' THEN value END) AS total_debt,\n    MAX(CASE WHEN line_item = 'long_term_debt' THEN value END) AS long_term_debt,\n    MAX(CASE WHEN line_item = 'net_debt' THEN value END) AS net_debt,\n    MAX(CASE WHEN line_item = 'operating_cash_flow' THEN value END) AS operating_cash_flow,\n    MAX(CASE WHEN line_item = 'capital_expenditure' THEN value END) AS capex,\n    MAX(CASE WHEN line_item = 'free_cash_flow' THEN value END) AS free_cash_flow,\n    MAX(CASE WHEN line_item = 'common_dividends_paid' THEN value END) AS dividends_paid,\n    MAX(CASE WHEN line_item = 'common_stock_repurchased' THEN value END) AS stock_repurchased,\n    MAX(CASE WHEN line_item = 'rpo' THEN value END) AS rpo,\n    MAX(CASE WHEN line_item = 'contract_liabilities' THEN value END) AS contract_liabilities,\n    MAX(CASE WHEN line_item = 'operating_lease_liability' THEN value END)\n        AS operating_lease_liability,\n    MAX(CASE WHEN line_item = 'operating_lease_rou_asset' THEN value END)\n        AS operating_lease_rou_asset\nFROM dedup\nWHERE rn = 1\nGROUP BY ticker, fiscal_year, fiscal_period_type")
    op.execute('CREATE VIEW IF NOT EXISTS ratios AS\nSELECT\n    ticker,\n    fiscal_year,\n    fiscal_period_type,\n    period_end,\n    currency,\n    revenue,\n    gross_profit,\n    operating_income,\n    net_income,\n    free_cash_flow,\n    total_assets,\n    total_equity,\n    total_debt,\n    capex,\n    operating_cash_flow,\n    rpo,\n    CAST(gross_profit AS REAL) / NULLIF(revenue, 0) AS gross_margin,\n    CAST(operating_income AS REAL) / NULLIF(revenue, 0) AS operating_margin,\n    CAST(net_income AS REAL) / NULLIF(revenue, 0) AS net_margin,\n    CAST(free_cash_flow AS REAL) / NULLIF(revenue, 0) AS fcf_margin,\n    CAST(net_income AS REAL) / NULLIF(total_assets, 0) AS roa,\n    CAST(net_income AS REAL) / NULLIF(total_equity, 0) AS roe,\n    CAST(operating_income AS REAL) / NULLIF(total_assets, 0) AS roa_op,\n    CAST(capex AS REAL) / NULLIF(revenue, 0) AS capex_intensity\nFROM metrics')
    op.execute('CREATE VIEW IF NOT EXISTS v_active_filing_sections AS SELECT * FROM filing_sections WHERE is_active = 1')
    op.execute('CREATE VIEW IF NOT EXISTS v_active_transcripts AS SELECT * FROM transcripts WHERE is_active = 1')
    op.execute('CREATE VIEW IF NOT EXISTS v_archive_generations_verified AS\n        SELECT g.*, r.receipt_id, r.request_sha256, r.result_sha256,\n               r.receipt_sha256, r.receipt_json, r.recorded_at AS receipt_recorded_at\n        FROM archive_generations g\n        JOIN archive_generation_registration_receipts r ON r.generation_id=g.generation_id')
    op.execute('CREATE VIEW IF NOT EXISTS v_ask_retrieval_scope_current AS SELECT promotion.* FROM ask_retrieval_scope_promotions promotion WHERE NOT EXISTS (SELECT 1 FROM ask_retrieval_scope_promotions newer WHERE newer.scope_key=promotion.scope_key AND newer.revision>promotion.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_decision_freshness AS\nSELECT\n    d.id                  AS decision_id,\n    d.ticker              AS ticker,\n    d.recommendation_kind AS recommendation_kind,\n    d.decided_by          AS decided_by,\n    d.outcome_label       AS outcome_label,\n    d.made_at             AS made_at,\n    d.basis_kind          AS basis_kind,\n    d.basis_ref_id        AS basis_ref_id,\n    d.basis_value         AS basis_value,\n    d.basis_as_of         AS basis_as_of,\n    cur.cur_ref_id        AS current_ref_id,\n    cur.cur_value         AS current_value,\n    cur.cur_as_of         AS current_as_of,\n    CASE\n        WHEN d.basis_kind IS NULL OR d.basis_value IS NULL THEN NULL\n        WHEN cur.cur_ref_id IS NULL THEN 0\n        WHEN d.basis_ref_id IS NOT NULL AND d.basis_ref_id = cur.cur_ref_id THEN 0\n        WHEN d.basis_as_of IS NOT NULL AND cur.cur_as_of IS NOT NULL\n             AND d.basis_as_of >= cur.cur_as_of THEN 0\n        ELSE 1\n    END AS valuation_superseded,\n    CASE\n        WHEN d.basis_value IS NOT NULL AND d.basis_value <> 0 AND cur.cur_value IS NOT NULL\n            THEN (cur.cur_value - d.basis_value) / d.basis_value\n        ELSE NULL\n    END AS basis_drift_pct,\n    CASE\n        WHEN d.basis_kind IS NULL OR d.basis_value IS NULL THEN 'unknown'\n        WHEN cur.cur_ref_id IS NULL THEN 'fresh'\n        WHEN (d.basis_ref_id IS NOT NULL AND d.basis_ref_id = cur.cur_ref_id)\n             OR (d.basis_as_of IS NOT NULL AND cur.cur_as_of IS NOT NULL\n                 AND d.basis_as_of >= cur.cur_as_of)\n            THEN 'fresh'\n        WHEN cur.cur_value IS NOT NULL AND d.basis_value <> 0\n             AND ABS((cur.cur_value - d.basis_value) / d.basis_value) >= 0.10\n            THEN 'superseded_material'\n        ELSE 'superseded_minor'\n    END AS basis_status\nFROM decisions d\nLEFT JOIN (\n\n    SELECT 'dcf' AS kind, ticker AS entity, id AS cur_ref_id,\n           npv_per_share AS cur_value, valuation_date AS cur_as_of\n    FROM dcf_runs\n    WHERE is_latest = 1 AND COALESCE(segment_name, '') = ''\n\n) cur ON cur.kind = d.basis_kind AND cur.entity = d.ticker")
    op.execute("CREATE VIEW IF NOT EXISTS v_decision_journal AS\nWITH linked_memo AS (\n    SELECT\n        d.id AS decision_id,\n        m.id AS memo_id,\n        m.kind AS memo_kind,\n        m.context_json AS memo_context_json,\n        m.created_at AS memo_created_at\n    FROM decisions d\n    JOIN advisor_memos m ON m.id = d.source_memo_id\n),\nadvice_before_ranked AS (\n    SELECT\n        d.id AS decision_id,\n        m.id AS memo_id,\n        m.kind AS memo_kind,\n        m.context_json AS memo_context_json,\n        m.created_at AS memo_created_at,\n        ROW_NUMBER() OVER (\n            PARTITION BY d.id ORDER BY m.created_at DESC, m.id DESC\n        ) AS rn\n    FROM decisions d\n    JOIN advisor_memos m\n        ON m.kind IN ('position_review', 'socratic')\n       AND d.ticker IS NOT NULL\n       AND UPPER(m.ticker) = UPPER(d.ticker)\n       AND m.created_at <= d.made_at\n       AND julianday(d.made_at) - julianday(m.created_at) <= 30\n       AND COALESCE(json_extract(m.context_json, '$.source'), '') != 'agent'\n),\nadvice_before AS (\n    SELECT decision_id, memo_id, memo_kind, memo_context_json, memo_created_at\n    FROM advice_before_ranked WHERE rn = 1\n),\ncoach_ping_ranked AS (\n    SELECT\n        d.id AS decision_id,\n        p.class_ AS ping_class,\n        p.status AS ping_status,\n        p.created_at AS ping_created_at,\n        ROW_NUMBER() OVER (\n            PARTITION BY d.id ORDER BY p.created_at DESC, p.id DESC\n        ) AS rn\n    FROM decisions d\n    JOIN coach_pings p\n        ON d.ticker IS NOT NULL\n       AND p.ticker IS NOT NULL\n       AND UPPER(p.ticker) = UPPER(d.ticker)\n       AND p.created_at <= d.made_at\n       AND julianday(d.made_at) - julianday(p.created_at) <= 30\n),\ncoach_ping_before AS (\n    SELECT decision_id, ping_class, ping_status, ping_created_at\n    FROM coach_ping_ranked WHERE rn = 1\n),\nprofile_active AS (\n    SELECT\n        d.id AS decision_id,\n        COUNT(*) AS active_fact_count,\n        MAX(f.affirmed_at) AS last_affirmed_at\n    FROM decisions d\n    JOIN owner_profile_facts f\n        ON f.status = 'affirmed'\n       AND f.created_at <= d.made_at\n       AND (f.superseded_at IS NULL OR f.superseded_at > d.made_at)\n    GROUP BY d.id\n),\nstance_ranked AS (\n    SELECT\n        s.memo_id,\n        s.verdict AS stance_verdict,\n        s.horizon_days AS stance_horizon_days,\n        s.end_date AS stance_end_date,\n        ROW_NUMBER() OVER (\n            PARTITION BY s.memo_id ORDER BY s.created_at DESC, s.id DESC\n        ) AS rn\n    FROM stance_scores s\n),\ndraft_ranked AS (\n    SELECT\n        dd.decision_id AS decision_id,\n        dd.id AS draft_id,\n        dd.source_channel AS draft_channel,\n        dd.source_note_id AS draft_note_id,\n        ROW_NUMBER() OVER (\n            PARTITION BY dd.decision_id ORDER BY dd.id DESC\n        ) AS rn\n    FROM decision_drafts dd\n    WHERE dd.decision_id IS NOT NULL\n),\ndraft_for_decision AS (\n    SELECT decision_id, draft_id, draft_channel, draft_note_id\n    FROM draft_ranked WHERE rn = 1\n)\nSELECT\n    d.id AS decision_id,\n    d.ticker AS ticker,\n    d.scope AS scope,\n    d.decided_by AS decided_by,\n    d.recommendation_kind AS recommendation_kind,\n    d.recommendation_value AS recommendation_value,\n    d.conviction AS conviction,\n    d.instrument AS instrument,\n    d.account AS account,\n    d.size_usd AS size_usd,\n    d.size_pct AS size_pct,\n    d.falsifier AS falsifier,\n    d.made_at AS made_at,\n    d.user_action_kind AS user_action_kind,\n    d.user_acted_at AS user_acted_at,\n    d.outcome_label AS outcome_label,\n    d.outcome_pct AS outcome_pct,\n    d.outcome_at AS outcome_at,\n    d.process_quality AS process_quality,\n    lm.memo_id AS linked_memo_id,\n    lm.memo_kind AS linked_memo_kind,\n    json_extract(lm.memo_context_json, '$.verdict_source') AS linked_memo_verdict_source,\n    ab.memo_id AS advice_before_memo_id,\n    ab.memo_kind AS advice_before_memo_kind,\n    ab.memo_created_at AS advice_before_memo_at,\n    json_extract(ab.memo_context_json, '$.verdict_source') AS advice_before_verdict_source,\n    CASE\n        WHEN json_extract(lm.memo_context_json, '$.verdict_source') = 'guard_override'\n          OR json_extract(ab.memo_context_json, '$.verdict_source') = 'guard_override'\n        THEN 1 ELSE 0\n    END AS guard_override_flag,\n    CASE\n        WHEN lm.memo_context_json IS NULL AND ab.memo_context_json IS NULL THEN NULL\n        WHEN json_extract(COALESCE(lm.memo_context_json, ab.memo_context_json),\n                           '$.owner_attested_change') = 1\n        THEN 1 ELSE 0\n    END AS owner_attested_change,\n    cp.ping_class AS coach_ping_class,\n    cp.ping_status AS coach_ping_status,\n    cp.ping_created_at AS coach_ping_at,\n    n.id AS decision_nudge_id,\n    n.status AS decision_nudge_status,\n    n.sent_at AS decision_nudge_sent_at,\n    pa.active_fact_count AS owner_profile_active_fact_count,\n    pa.last_affirmed_at AS owner_profile_last_affirmed_at,\n    st.stance_verdict AS stance_verdict,\n    st.stance_horizon_days AS stance_horizon_days,\n    st.stance_end_date AS stance_end_date,\n    d.advice_artifact_id AS advice_artifact_id,\n    art.purpose AS advice_purpose,\n    art.generated_at AS advice_created_at,\n    CASE\n        WHEN d.advice_artifact_id IS NULL THEN NULL\n        WHEN art.generated_at IS NOT NULL AND art.generated_at < d.made_at THEN 1\n        ELSE 0\n    END AS advice_preceded,\n    dfd.draft_id AS source_draft_id,\n    dfd.draft_channel AS source_draft_channel,\n    dfd.draft_note_id AS source_note_id\nFROM decisions d\nLEFT JOIN linked_memo lm ON lm.decision_id = d.id\nLEFT JOIN advice_before ab ON ab.decision_id = d.id\nLEFT JOIN coach_ping_before cp ON cp.decision_id = d.id\nLEFT JOIN decision_nudges n ON n.decision_id = d.id\nLEFT JOIN profile_active pa ON pa.decision_id = d.id\nLEFT JOIN stance_ranked st\n    ON st.memo_id = COALESCE(lm.memo_id, ab.memo_id) AND st.rn = 1\nLEFT JOIN llm_artifacts art ON art.id = d.advice_artifact_id\nLEFT JOIN draft_for_decision dfd ON dfd.decision_id = d.id")
    op.execute('CREATE VIEW IF NOT EXISTS v_document_semantic_dispositions_current AS SELECT disposition.* FROM document_semantic_disposition_revisions AS disposition WHERE NOT EXISTS (SELECT 1 FROM document_semantic_disposition_revisions AS newer WHERE newer.document_version_id = disposition.document_version_id AND newer.revision > disposition.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_evidence_blob_locations_current AS SELECT location_observation_id, idempotency_key, blob_sha256, storage_uri, location_kind, availability_state, location_sequence, verified_at, verified_byte_size, verified_sha256, supersedes_location_observation_id, recorded_at FROM evidence_blob_location_observations AS location_observation WHERE NOT EXISTS (SELECT 1 FROM evidence_blob_location_observations AS newer WHERE newer.blob_sha256 = location_observation.blob_sha256 AND newer.storage_uri = location_observation.storage_uri AND newer.location_sequence > location_observation.location_sequence)')
    op.execute('CREATE VIEW IF NOT EXISTS v_evidence_current AS SELECT node_id, evidence_key, revision, extraction_run_id, parent_node_id, supersedes_node_id, node_kind, text, locator_json, locator_sha256, recorded_at FROM evidence_nodes AS node WHERE NOT EXISTS (SELECT 1 FROM evidence_nodes AS newer WHERE newer.evidence_key = node.evidence_key AND newer.revision > node.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_evidence_document_current AS SELECT document_version_id, document_key, version_sequence, observation_id, blob_sha256, issuer_id, ticker, document_type, form_type, accession_number, exhibit_id, period_start, period_end, as_of_at, language, replaces_document_version_id, legacy_document_id, recorded_at FROM evidence_document_versions AS document_version WHERE NOT EXISTS (SELECT 1 FROM evidence_document_versions AS newer WHERE newer.document_key = document_version.document_key AND newer.version_sequence > document_version.version_sequence)')
    op.execute("CREATE VIEW IF NOT EXISTS v_evidence_document_versions_canonical AS SELECT document.document_version_id, document.document_key, document.version_sequence, document.observation_id, document.blob_sha256, COALESCE(subject.issuer_id, canonical.issuer_id, binding.canonical_issuer_id, document.issuer_id) AS issuer_id, document.issuer_id AS recorded_issuer_id, document.ticker, document.document_type, document.form_type, document.accession_number, document.exhibit_id, document.period_start, document.period_end, document.as_of_at, document.language, document.replaces_document_version_id, document.legacy_document_id, document.recorded_at, subject.reporting_entity_id, subject.security_id FROM evidence_document_versions AS document LEFT JOIN issuer_entities AS canonical ON canonical.issuer_id = document.issuer_id LEFT JOIN v_legacy_issuer_bindings_current AS binding ON binding.recorded_issuer_id = document.issuer_id AND binding.outcome = 'selected' LEFT JOIN v_recorded_subject_bindings_current AS subject ON subject.recorded_issuer_id = document.issuer_id AND subject.outcome = 'selected'")
    op.execute('CREATE VIEW IF NOT EXISTS v_expected_document_lifecycle_current AS SELECT lifecycle.* FROM expected_document_lifecycle_revisions AS lifecycle WHERE NOT EXISTS (SELECT 1 FROM expected_document_lifecycle_revisions AS newer WHERE newer.inventory_key = lifecycle.inventory_key AND newer.expected_document_key = lifecycle.expected_document_key AND newer.revision > lifecycle.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_expected_documents_current AS SELECT expected.* FROM expected_documents AS expected JOIN v_source_inventory_current AS inventory ON inventory.snapshot_id = expected.snapshot_id')
    op.execute('CREATE VIEW IF NOT EXISTS v_fact_cells_hardened_v2 AS SELECT cell.*, seal.semantic_key_version AS hardened_semantic_key_version, seal.semantic_identity_json, seal.dimension_count, seal.dimension_set_json, seal.dimension_set_sha256, seal.sealed_at FROM fact_cells_v2 AS cell JOIN fact_cell_identity_seals_v2 AS seal ON seal.fact_cell_id = cell.fact_cell_id')
    op.execute("CREATE VIEW IF NOT EXISTS v_fact_cells_resolved_current_v2 AS SELECT cell.*, resolution.resolution_revision_id, resolution.revision AS resolution_revision, resolution.selected_observation_id, resolution.knowledge_at AS resolution_knowledge_at, observation.observation_kind, observation.value_kind, observation.numeric_value, observation.text_value, observation.is_nil, observation.raw_lexical_value FROM v_fact_resolutions_current_v2 AS resolution JOIN fact_cells_v2 AS cell ON cell.fact_cell_id = resolution.fact_cell_id JOIN fact_cell_identity_seals_v2 AS cell_seal ON cell_seal.fact_cell_id = cell.fact_cell_id JOIN fact_observations_v2 AS observation ON observation.observation_id = resolution.selected_observation_id JOIN fact_observation_payload_commitments_v2 AS payload ON payload.observation_id = observation.observation_id WHERE resolution.status = 'resolved'")
    op.execute('CREATE VIEW IF NOT EXISTS v_fact_extraction_runs_complete_v2 AS SELECT run.*, seal.extraction_seal_id, seal.expected_node_count, seal.observed_node_count, seal.reported_fact_count, seal.node_set_sha256, seal.observation_set_sha256, seal.knowledge_at AS seal_knowledge_at, seal.recorded_at AS seal_recorded_at FROM evidence_extraction_runs AS run JOIN fact_extraction_run_completeness_seals_v2 AS seal ON seal.extraction_run_id = run.extraction_run_id')
    op.execute('CREATE VIEW IF NOT EXISTS v_fact_observation_match_proofs_current_valid AS SELECT proof.* FROM fact_observation_match_proofs AS proof JOIN fact_observation_revisions AS link ON link.fact_table = proof.fact_table AND link.fact_row_id = proof.fact_row_id AND link.fact_revision = proof.fact_revision AND link.observation_id = proof.observation_id JOIN reported_observations AS observation ON observation.observation_id = proof.observation_id JOIN v_legacy_fact_evidence_matches_accepted_current AS match ON match.match_revision_id = proof.match_revision_id AND match.fact_table = proof.fact_table AND match.fact_row_id = proof.fact_row_id AND match.evidence_node_id = observation.evidence_node_id WHERE proof.knowledge_at >= observation.available_at AND proof.knowledge_at >= match.knowledge_at')
    op.execute("CREATE VIEW IF NOT EXISTS v_fact_observations_as_reported_v2 AS SELECT cell.*, observation.observation_id, observation.value_kind, observation.numeric_value, observation.text_value, observation.is_nil, observation.raw_lexical_value, observation.document_version_id, observation.evidence_node_id, observation.source_locator_json, observation.source_locator_sha256, observation.source_entry_sha256, observation.source_context_id, observation.source_unit_id, observation.decimals, observation.precision, observation.legacy_match_revision_id, observation.revision_kind, anchor.subject_binding_revision_id, anchor.source_taxonomy_version, payload.observation_payload_sha256, observation.effective_at AS observation_effective_at, observation.knowledge_at AS observation_knowledge_at, observation.recorded_at AS observation_recorded_at FROM fact_observations_v2 AS observation JOIN fact_cells_v2 AS cell ON cell.fact_cell_id = observation.fact_cell_id JOIN fact_cell_identity_seals_v2 AS cell_seal ON cell_seal.fact_cell_id = cell.fact_cell_id JOIN fact_reported_observation_anchors_v2 AS anchor ON anchor.observation_id = observation.observation_id JOIN fact_observation_payload_commitments_v2 AS payload ON payload.observation_id = observation.observation_id JOIN recorded_subject_binding_revisions AS binding ON binding.binding_revision_id = anchor.subject_binding_revision_id AND binding.outcome = 'selected' WHERE observation.observation_kind = 'reported'")
    op.execute('CREATE VIEW IF NOT EXISTS v_fact_observations_committed_v2 AS SELECT observation.*, payload.payload_version, payload.canonical_payload_json, payload.observation_payload_sha256, payload.committed_at FROM fact_observations_v2 AS observation JOIN fact_observation_payload_commitments_v2 AS payload ON payload.observation_id = observation.observation_id')
    op.execute("CREATE VIEW IF NOT EXISTS v_fact_reported_anchors_selected_v2 AS SELECT observation.*, anchor.*, binding.recorded_issuer_id, binding.issuer_id AS bound_issuer_id, binding.reporting_entity_id AS bound_reporting_entity_id, binding.security_id AS bound_security_id FROM fact_observations_v2 AS observation JOIN fact_reported_observation_anchors_v2 AS anchor ON anchor.observation_id = observation.observation_id JOIN recorded_subject_binding_revisions AS binding ON binding.binding_revision_id = anchor.subject_binding_revision_id WHERE binding.outcome = 'selected'")
    op.execute('CREATE VIEW IF NOT EXISTS v_fact_resolutions_current_v2 AS SELECT resolution.* FROM fact_resolution_revisions_v2 AS resolution WHERE NOT EXISTS (SELECT 1 FROM fact_resolution_revisions_v2 AS newer WHERE newer.fact_cell_id = resolution.fact_cell_id AND newer.revision > resolution.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_fact_selection_current AS SELECT decision_id, idempotency_key, target_table, target_row_id, revision, selection_state, reason_code, reason_details_json, decision_kind, policy_name, policy_version, policy_config_sha256, evidence_node_id, validation_issue_id, effective_at, knowledge_at, recorded_at, supersedes_decision_id, material_dissent FROM fact_selection_decisions AS decision WHERE NOT EXISTS (SELECT 1 FROM fact_selection_decisions AS newer WHERE newer.target_table = decision.target_table AND newer.target_row_id = decision.target_row_id AND newer.revision > decision.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_filing_xbrl_extractions_disposition_sealed AS SELECT seal.*, publication.publication_seal_id FROM filing_xbrl_extraction_disposition_seals AS seal JOIN source_fact_publication_seals AS publication ON publication.publication_id = seal.publication_id')
    op.execute("CREATE VIEW IF NOT EXISTS v_financial_facts_resolved_current AS SELECT fact.*, link.observation_id AS reported_observation_id, resolution.resolution_id, resolution.policy_version AS resolution_policy_version, resolution.reason AS resolution_reason, resolution.material_dissent AS resolution_material_dissent, outcome.checks_json AS resolution_checks_json FROM financial_facts AS fact JOIN fact_observation_revisions AS link ON link.fact_table = 'financial_facts' AND link.fact_row_id = fact.id AND link.fact_revision = (SELECT MAX(latest.fact_revision) FROM fact_observation_revisions AS latest WHERE latest.fact_table = 'financial_facts' AND latest.fact_row_id = fact.id) JOIN v_observation_resolution_current AS resolution ON resolution.selected_observation_id = link.observation_id JOIN fact_resolution_outcomes AS outcome ON outcome.resolution_id = resolution.resolution_id AND outcome.resolution_status = 'resolved'")
    op.execute('CREATE VIEW IF NOT EXISTS v_issuer_authority_surfaces_current AS SELECT surface.* FROM issuer_authority_surface_revisions AS surface WHERE NOT EXISTS (SELECT 1 FROM issuer_authority_surface_revisions AS newer WHERE newer.issuer_id = surface.issuer_id AND newer.surface_key = surface.surface_key AND newer.revision > surface.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_issuer_identifier_resolutions_current AS SELECT resolution.* FROM issuer_identifier_resolution_outcomes AS resolution WHERE NOT EXISTS (SELECT 1 FROM issuer_identifier_resolution_outcomes AS newer WHERE newer.resolution_key = resolution.resolution_key AND newer.revision > resolution.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_issuer_identifiers_canonical AS SELECT assertion.*, resolution.resolution_id, resolution.revision AS resolution_revision, resolution.material_dissent, resolution.reason_code AS resolution_reason_code FROM v_issuer_identifier_resolutions_current AS resolution JOIN issuer_identifier_assertions AS assertion ON assertion.assertion_id = resolution.selected_assertion_id WHERE resolution.outcome = 'selected'")
    op.execute('CREATE VIEW IF NOT EXISTS v_issuer_profiles_current AS SELECT profile.* FROM issuer_profile_revisions AS profile WHERE NOT EXISTS (SELECT 1 FROM issuer_profile_revisions AS newer WHERE newer.issuer_id = profile.issuer_id AND newer.revision > profile.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_issuer_reporting_scope_current AS SELECT scope.* FROM issuer_reporting_scope_revisions AS scope WHERE NOT EXISTS (SELECT 1 FROM issuer_reporting_scope_revisions AS newer WHERE newer.scope_key = scope.scope_key AND newer.issuer_id = scope.issuer_id AND newer.revision > scope.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_kpi_facts_resolved_current AS SELECT fact.*, link.observation_id AS reported_observation_id, resolution.resolution_id, resolution.policy_version AS resolution_policy_version, resolution.reason AS resolution_reason, resolution.material_dissent AS resolution_material_dissent, outcome.checks_json AS resolution_checks_json FROM kpi_facts AS fact JOIN fact_observation_revisions AS link ON link.fact_table = 'kpi_facts' AND link.fact_row_id = fact.id AND link.fact_revision = (SELECT MAX(latest.fact_revision) FROM fact_observation_revisions AS latest WHERE latest.fact_table = 'kpi_facts' AND latest.fact_row_id = fact.id) JOIN v_observation_resolution_current AS resolution ON resolution.selected_observation_id = link.observation_id JOIN fact_resolution_outcomes AS outcome ON outcome.resolution_id = resolution.resolution_id AND outcome.resolution_status = 'resolved'")
    op.execute('CREATE VIEW IF NOT EXISTS v_legacy_document_evidence_bindings_current AS SELECT binding.* FROM legacy_document_evidence_binding_revisions AS binding WHERE NOT EXISTS (SELECT 1 FROM legacy_document_evidence_binding_revisions AS newer WHERE newer.legacy_document_id = binding.legacy_document_id AND newer.revision > binding.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_legacy_fact_evidence_matches_accepted_current AS SELECT match.* FROM v_legacy_fact_evidence_matches_current AS match JOIN v_legacy_document_evidence_bindings_current AS binding ON binding.binding_revision_id = match.legacy_binding_revision_id AND binding.revision = match.legacy_binding_revision AND binding.scope_content_sha256 = match.binding_scope_content_sha256 AND binding.evidence_node_id = match.evidence_node_id WHERE match.outcome = 'accepted'")
    op.execute('CREATE VIEW IF NOT EXISTS v_legacy_fact_evidence_matches_current AS SELECT match.* FROM legacy_fact_evidence_match_revisions AS match WHERE NOT EXISTS (SELECT 1 FROM legacy_fact_evidence_match_revisions AS newer WHERE newer.fact_table = match.fact_table AND newer.fact_row_id = match.fact_row_id AND newer.revision > match.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_legacy_issuer_bindings_current AS SELECT binding.recorded_issuer_id, binding.issuer_id AS canonical_issuer_id, binding.binding_revision_id, binding.revision, binding.outcome, binding.decision_kind, binding.reason_code, binding.material_dissent, binding.effective_at, binding.knowledge_at, binding.recorded_at FROM legacy_issuer_binding_revisions AS binding WHERE NOT EXISTS (SELECT 1 FROM legacy_issuer_binding_revisions AS newer WHERE newer.recorded_issuer_id = binding.recorded_issuer_id AND newer.revision > binding.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_observation_resolution_current AS SELECT resolution_id, idempotency_key, logical_key, revision, selected_observation_id, resolver_kind, policy_version, reason, knowledge_cutoff, effective_at, material_dissent, supersedes_resolution_id, recorded_at FROM observation_resolution_revisions AS revision WHERE NOT EXISTS (SELECT 1 FROM observation_resolution_revisions AS newer WHERE newer.logical_key = revision.logical_key AND newer.revision > revision.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_ontology_snapshot_expected_members AS\n        SELECT header.ontology_snapshot_id, 'canonical_metric' AS member_kind,\n               record.metric_id AS member_id,\n               record.commitment_sha256 AS member_sha256\n        FROM ontology_snapshot_headers header\n        JOIN canonical_metrics record\n          ON record.effective_at <= header.cutoff_at\n         AND record.knowledge_at <= header.cutoff_at\n         AND record.recorded_at <= header.cutoff_at\n        UNION ALL\n        SELECT header.ontology_snapshot_id, 'canonical_axis',\n               record.axis_id, record.commitment_sha256\n        FROM ontology_snapshot_headers header\n        JOIN canonical_axes record\n          ON record.effective_at <= header.cutoff_at\n         AND record.knowledge_at <= header.cutoff_at\n         AND record.recorded_at <= header.cutoff_at\n        UNION ALL\n        SELECT header.ontology_snapshot_id, 'canonical_member',\n               record.member_id, record.commitment_sha256\n        FROM ontology_snapshot_headers header\n        JOIN canonical_members record\n          ON record.effective_at <= header.cutoff_at\n         AND record.knowledge_at <= header.cutoff_at\n         AND record.recorded_at <= header.cutoff_at\n        UNION ALL\n        SELECT header.ontology_snapshot_id, 'source_component',\n               record.component_id, record.commitment_sha256\n        FROM ontology_snapshot_headers header\n        JOIN source_taxonomy_components record\n          ON record.effective_at <= header.cutoff_at\n         AND record.knowledge_at <= header.cutoff_at\n         AND record.recorded_at <= header.cutoff_at\n        UNION ALL\n        SELECT header.ontology_snapshot_id, 'source_taxonomy_assertion',\n               record.observation_id, record.commitment_sha256\n        FROM ontology_snapshot_headers header\n        JOIN source_observation_taxonomy_assertions record\n          ON datetime(record.knowledge_at) <= datetime(header.cutoff_at)\n         AND datetime(record.recorded_at) <= datetime(header.cutoff_at)\n        UNION ALL\n        SELECT header.ontology_snapshot_id, 'metric_definition',\n               record.metric_definition_revision_id, record.commitment_sha256\n        FROM ontology_snapshot_headers header\n        JOIN canonical_metric_definition_revisions record\n          ON record.effective_at <= header.cutoff_at\n         AND record.knowledge_at <= header.cutoff_at\n         AND record.recorded_at <= header.cutoff_at\n         AND NOT EXISTS (\n            SELECT 1 FROM canonical_metric_definition_revisions newer\n            WHERE newer.metric_id=record.metric_id\n              AND newer.revision > record.revision\n              AND newer.effective_at <= header.cutoff_at\n              AND newer.knowledge_at <= header.cutoff_at\n              AND newer.recorded_at <= header.cutoff_at)\n        UNION ALL\n        SELECT header.ontology_snapshot_id, 'dimension_mapping',\n               record.dimension_mapping_revision_id, record.commitment_sha256\n        FROM ontology_snapshot_headers header\n        JOIN source_dimension_mapping_revisions record\n          ON record.effective_at <= header.cutoff_at\n         AND record.knowledge_at <= header.cutoff_at\n         AND record.recorded_at <= header.cutoff_at\n         AND NOT EXISTS (\n            SELECT 1 FROM source_dimension_mapping_revisions newer\n            WHERE newer.source_component_id=record.source_component_id\n              AND newer.revision > record.revision\n              AND newer.effective_at <= header.cutoff_at\n              AND newer.knowledge_at <= header.cutoff_at\n              AND newer.recorded_at <= header.cutoff_at)\n        UNION ALL\n        SELECT header.ontology_snapshot_id, 'metric_mapping',\n               record.mapping_revision_id, record.commitment_sha256\n        FROM ontology_snapshot_headers header\n        JOIN metric_mapping_revisions record\n          ON record.effective_at <= header.cutoff_at\n         AND record.knowledge_at <= header.cutoff_at\n         AND record.recorded_at <= header.cutoff_at\n         AND NOT EXISTS (\n            SELECT 1 FROM metric_mapping_revisions newer\n            WHERE newer.source_component_id=record.source_component_id\n              AND newer.revision > record.revision\n              AND newer.effective_at <= header.cutoff_at\n              AND newer.knowledge_at <= header.cutoff_at\n              AND newer.recorded_at <= header.cutoff_at)\n        UNION ALL\n        SELECT header.ontology_snapshot_id, 'canonical_cell',\n               seal.canonical_metric_cell_id, seal.semantic_key_sha256\n        FROM ontology_snapshot_headers header\n        JOIN canonical_metric_cell_seals seal\n        JOIN canonical_metric_cells cell\n          ON cell.canonical_metric_cell_id=seal.canonical_metric_cell_id\n         AND cell.effective_at <= header.cutoff_at\n         AND cell.knowledge_at <= header.cutoff_at\n         AND cell.recorded_at <= header.cutoff_at\n         AND seal.sealed_at <= header.cutoff_at\n        UNION ALL\n        SELECT header.ontology_snapshot_id, 'binding',\n               record.binding_revision_id, record.commitment_sha256\n        FROM ontology_snapshot_headers header\n        JOIN fact_cell_canonical_binding_revisions record\n          ON record.effective_at <= header.cutoff_at\n         AND record.knowledge_at <= header.cutoff_at\n         AND record.recorded_at <= header.cutoff_at\n         AND NOT EXISTS (\n            SELECT 1 FROM fact_cell_canonical_binding_revisions newer\n            WHERE newer.source_observation_id=record.source_observation_id\n              AND newer.revision > record.revision\n              AND newer.effective_at <= header.cutoff_at\n              AND newer.knowledge_at <= header.cutoff_at\n              AND newer.recorded_at <= header.cutoff_at)")
    op.execute('CREATE VIEW IF NOT EXISTS v_population_cutover_current AS SELECT receipt.*,run.policy_name,run.policy_version,run.policy_config_sha256,run.source_snapshot_sha256,run.knowledge_cutoff,run.observed_through,run.verified_at FROM population_cutover_receipts receipt JOIN population_run_headers run USING (population_run_id) ORDER BY datetime(run.knowledge_cutoff) DESC,datetime(run.observed_through) DESC,datetime(receipt.sealed_at) DESC,receipt.population_run_id DESC LIMIT 1')
    op.execute("CREATE VIEW IF NOT EXISTS v_quarters AS\nSELECT\n    ff.ticker,\n    ff.period_end,\n    ff.fiscal_period_type,\n    CAST(STRFTIME('%Y', ff.period_end) AS INTEGER) AS calendar_year,\n    CASE\n        WHEN CAST(STRFTIME('%m', ff.period_end) AS INTEGER) BETWEEN 1 AND 3 THEN 1\n        WHEN CAST(STRFTIME('%m', ff.period_end) AS INTEGER) BETWEEN 4 AND 6 THEN 2\n        WHEN CAST(STRFTIME('%m', ff.period_end) AS INTEGER) BETWEEN 7 AND 9 THEN 3\n        ELSE 4\n    END AS calendar_quarter\nFROM financial_facts ff\nGROUP BY ff.ticker, ff.period_end, ff.fiscal_period_type")
    op.execute('CREATE VIEW IF NOT EXISTS v_recorded_subject_bindings_current AS SELECT binding.* FROM recorded_subject_binding_revisions AS binding WHERE NOT EXISTS (SELECT 1 FROM recorded_subject_binding_revisions AS newer WHERE newer.recorded_issuer_id = binding.recorded_issuer_id AND newer.revision > binding.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_reporting_entity_identifier_resolutions_current AS SELECT resolution.* FROM reporting_entity_identifier_resolution_outcomes AS resolution WHERE NOT EXISTS (SELECT 1 FROM reporting_entity_identifier_resolution_outcomes AS newer WHERE newer.resolution_key = resolution.resolution_key AND newer.revision > resolution.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_reporting_entity_identifiers_canonical AS SELECT entity.issuer_id, assertion.*, resolution.resolution_id, resolution.material_dissent FROM v_reporting_entity_identifier_resolutions_current AS resolution JOIN reporting_entity_identifier_assertions AS assertion ON assertion.assertion_id = resolution.selected_assertion_id JOIN reporting_entities AS entity ON entity.reporting_entity_id = assertion.reporting_entity_id WHERE resolution.outcome = 'selected'")
    op.execute("CREATE VIEW IF NOT EXISTS v_search_corpus_coverage AS SELECT manifest_id, COUNT(*) AS expected_document_count, SUM(CASE WHEN membership_status = 'included' THEN 1 ELSE 0 END) AS included_document_count, SUM(CASE WHEN membership_status = 'missing' THEN 1 ELSE 0 END) AS missing_document_count, SUM(CASE WHEN membership_status = 'quarantined' THEN 1 ELSE 0 END) AS quarantined_document_count FROM search_corpus_document_memberships GROUP BY manifest_id")
    op.execute('CREATE VIEW IF NOT EXISTS v_search_corpus_current AS SELECT manifest_id, corpus_key, revision, selection_config_sha256, selector_code_version, knowledge_cutoff, supersedes_manifest_id, recorded_at FROM search_corpus_manifests AS manifest WHERE NOT EXISTS (SELECT 1 FROM search_corpus_manifests AS newer WHERE newer.corpus_key = manifest.corpus_key AND newer.revision > manifest.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_search_embedding_model_promotion_current AS SELECT promotion.* FROM search_embedding_model_promotions AS promotion WHERE NOT EXISTS (SELECT 1 FROM search_embedding_model_promotions AS newer WHERE newer.purpose = promotion.purpose AND newer.revision > promotion.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_search_fact_hits_current AS SELECT row.* FROM search_fact_projection_rows AS row JOIN v_search_fact_projection_current_sealed AS current ON current.projection_run_id = row.projection_run_id')
    op.execute('CREATE VIEW IF NOT EXISTS v_search_fact_projection_current_sealed AS SELECT run.*, seal.projection_seal_id, seal.eligible_fact_cell_count, seal.membership_count, seal.included_count, seal.unresolved_material_count, seal.missing_provenance_count, seal.quarantined_count, seal.row_count, seal.membership_set_sha256, seal.row_set_sha256, seal.sealed_at FROM search_fact_projection_runs AS run JOIN search_fact_projection_seals AS seal ON seal.projection_run_id = run.projection_run_id WHERE NOT EXISTS (SELECT 1 FROM search_fact_projection_runs AS newer JOIN search_fact_projection_seals AS newer_seal ON newer_seal.projection_run_id = newer.projection_run_id WHERE newer.projection_key = run.projection_key AND newer.revision > run.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_search_index_current AS SELECT index_run_id, index_key, revision, manifest_id, index_kind, config_sha256, code_version, outcome, failure_reason, started_at, completed_at FROM search_index_runs AS run WHERE NOT EXISTS (SELECT 1 FROM search_index_runs AS newer WHERE newer.index_key = run.index_key AND newer.revision > run.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_search_index_successful AS SELECT run.* FROM search_index_runs AS run JOIN search_projection_seals AS seal ON seal.index_run_id = run.index_run_id WHERE run.outcome = 'succeeded' AND NOT EXISTS (SELECT 1 FROM search_index_runs AS newer WHERE newer.index_key = run.index_key AND newer.revision > run.revision)")
    op.execute('CREATE VIEW IF NOT EXISTS v_security_identifier_resolutions_current AS SELECT resolution.* FROM security_identifier_resolution_outcomes AS resolution WHERE NOT EXISTS (SELECT 1 FROM security_identifier_resolution_outcomes AS newer WHERE newer.resolution_key = resolution.resolution_key AND newer.revision > resolution.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_security_identifiers_canonical AS SELECT security.issuer_id, assertion.*, resolution.resolution_id, resolution.material_dissent FROM v_security_identifier_resolutions_current AS resolution JOIN security_identifier_assertions AS assertion ON assertion.assertion_id = resolution.selected_assertion_id JOIN securities AS security ON security.security_id = assertion.security_id WHERE resolution.outcome = 'selected'")
    op.execute('CREATE VIEW IF NOT EXISTS v_security_listing_resolutions_current AS SELECT resolution.* FROM security_listing_resolution_outcomes AS resolution WHERE NOT EXISTS (SELECT 1 FROM security_listing_resolution_outcomes AS newer WHERE newer.resolution_key = resolution.resolution_key AND newer.revision > resolution.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_security_listings_canonical AS SELECT security.issuer_id, assertion.*, resolution.resolution_id, resolution.revision AS resolution_revision, resolution.material_dissent, resolution.reason_code AS resolution_reason_code FROM v_security_listing_resolutions_current AS resolution JOIN security_listing_assertions AS assertion ON assertion.assertion_id = resolution.selected_assertion_id JOIN securities AS security ON security.security_id = assertion.security_id WHERE resolution.outcome = 'selected'")
    op.execute('CREATE VIEW IF NOT EXISTS v_security_reporting_entities_current AS SELECT relation.* FROM security_reporting_entity_revisions AS relation WHERE NOT EXISTS (SELECT 1 FROM security_reporting_entity_revisions AS newer WHERE newer.relationship_key = relation.relationship_key AND newer.revision > relation.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_source_coverage_current AS SELECT assessment.* FROM source_coverage_assessments AS assessment WHERE NOT EXISTS (SELECT 1 FROM source_coverage_assessments AS newer WHERE newer.expected_document_id = assessment.expected_document_id AND newer.revision > assessment.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_source_fact_publications_sealed AS SELECT publication.*, seal.publication_seal_id, seal.canonical_member_set_json, seal.sealed_at FROM source_fact_publications AS publication JOIN source_fact_publication_seals AS seal ON seal.publication_id = publication.publication_id')
    op.execute('CREATE VIEW IF NOT EXISTS v_source_inventory_current AS SELECT * FROM source_inventory_snapshots AS snapshot WHERE NOT EXISTS (SELECT 1 FROM source_inventory_snapshots AS newer WHERE newer.inventory_key = snapshot.inventory_key AND newer.revision > snapshot.revision)')
    op.execute('CREATE VIEW IF NOT EXISTS v_source_inventory_sealed AS SELECT inventory.*, seal.expected_component_count, seal.component_digest_sha256, seal.completion_status, seal.sealed_at FROM v_source_inventory_current AS inventory JOIN source_inventory_snapshot_seals AS seal ON seal.snapshot_id = inventory.snapshot_id')
    op.execute("CREATE VIEW IF NOT EXISTS v_source_inventory_sealed_complete AS SELECT * FROM v_source_inventory_sealed WHERE completion_status = 'complete'")
    op.execute('CREATE VIEW IF NOT EXISTS v_source_obligations_current AS SELECT obligation.* FROM source_obligation_revisions AS obligation WHERE NOT EXISTS (SELECT 1 FROM source_obligation_revisions AS newer WHERE newer.obligation_key = obligation.obligation_key AND newer.revision > obligation.revision)')
    op.execute("CREATE VIEW IF NOT EXISTS v_thesis_status AS\nWITH tk(ticker) AS (\n    SELECT UPPER(ticker) FROM thesis_state\n        WHERE ticker IS NOT NULL AND TRIM(ticker) <> ''\n    UNION\n    SELECT UPPER(ticker) FROM thesis_ledger_entries\n        WHERE ticker IS NOT NULL AND TRIM(ticker) <> ''\n    UNION\n    SELECT UPPER(ticker) FROM analyst_notes\n        WHERE ticker IS NOT NULL AND TRIM(ticker) <> ''\n)\nSELECT\n    tk.ticker                          AS ticker,\n    COALESCE(ts.has_thesis, 0)         AS has_written_thesis,\n    ts.breach_status                   AS breach_status,\n    ts.thesis_updated_at               AS thesis_updated_at,\n    COALESCE(le.entry_count, 0)        AS ledger_entry_count,\n    le.last_ledger_at                  AS last_ledger_at,\n    COALESCE(an.open_notes, 0)         AS open_notes_count,\n    COALESCE(an.open_questions, 0)     AS open_questions_count\nFROM tk\nLEFT JOIN (\n    SELECT UPPER(ticker)                                        AS ticker,\n           MAX(last_updated)                                    AS thesis_updated_at,\n           breach_status                                        AS breach_status,\n           CASE WHEN TRIM(COALESCE(thesis, '')) <> '' AND thesis NOT LIKE '%STUB:%' THEN 1 ELSE 0 END AS has_thesis\n    FROM thesis_state\n    GROUP BY UPPER(ticker)\n) ts ON ts.ticker = tk.ticker\nLEFT JOIN (\n    SELECT UPPER(ticker)   AS ticker,\n           COUNT(*)        AS entry_count,\n           MAX(created_at) AS last_ledger_at\n    FROM thesis_ledger_entries\n    GROUP BY UPPER(ticker)\n) le ON le.ticker = tk.ticker\nLEFT JOIN (\n    SELECT UPPER(ticker) AS ticker,\n           SUM(CASE WHEN status = 'open' THEN 1 ELSE 0 END)                        AS open_notes,\n           SUM(CASE WHEN status = 'open' AND kind = 'question' THEN 1 ELSE 0 END)  AS open_questions\n    FROM analyst_notes\n    GROUP BY UPPER(ticker)\n) an ON an.ticker = tk.ticker")

    # Created triggers
    op.execute("CREATE TRIGGER IF NOT EXISTS analyst_notes_fts_ad AFTER DELETE ON analyst_notes BEGIN INSERT INTO analyst_notes_fts(analyst_notes_fts, rowid, body) VALUES ('delete', old.id, old.body); END")
    op.execute('CREATE TRIGGER IF NOT EXISTS analyst_notes_fts_ai AFTER INSERT ON analyst_notes BEGIN INSERT INTO analyst_notes_fts(rowid, body) VALUES (new.id, new.body); END')
    op.execute("CREATE TRIGGER IF NOT EXISTS analyst_notes_fts_au AFTER UPDATE ON analyst_notes BEGIN INSERT INTO analyst_notes_fts(analyst_notes_fts, rowid, body) VALUES ('delete', old.id, old.body); INSERT INTO analyst_notes_fts(rowid, body) VALUES (new.id, new.body); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_archive_generation_registration_receipts_immutable_delete BEFORE DELETE ON archive_generation_registration_receipts BEGIN SELECT RAISE(ABORT, 'immutable archive_generation_registration_receipts'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_archive_generation_registration_receipts_immutable_update BEFORE UPDATE ON archive_generation_registration_receipts BEGIN SELECT RAISE(ABORT, 'immutable archive_generation_registration_receipts'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_archive_generation_table_commitments_immutable_delete BEFORE DELETE ON archive_generation_table_commitments BEGIN SELECT RAISE(ABORT, 'immutable archive_generation_table_commitments'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_archive_generation_table_commitments_immutable_update BEFORE UPDATE ON archive_generation_table_commitments BEGIN SELECT RAISE(ABORT, 'immutable archive_generation_table_commitments'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_archive_generations_immutable_delete BEFORE DELETE ON archive_generations BEGIN SELECT RAISE(ABORT, 'immutable archive_generations'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_archive_generations_immutable_update BEFORE UPDATE ON archive_generations BEGIN SELECT RAISE(ABORT, 'immutable archive_generations'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_archive_registration_complete\n        BEFORE INSERT ON archive_generation_registration_receipts\n        BEGIN\n          SELECT CASE WHEN NOT EXISTS (\n            SELECT 1 FROM archive_generations g WHERE g.generation_id=NEW.generation_id\n          ) THEN RAISE(ABORT, 'archive generation is missing') END;\n          SELECT CASE WHEN (\n            SELECT COUNT(*) FROM archive_generation_table_commitments t WHERE t.generation_id=NEW.generation_id\n          ) <> (\n            SELECT table_count FROM archive_generations g WHERE g.generation_id=NEW.generation_id\n          ) THEN RAISE(ABORT, 'archive generation table commitments incomplete') END;\n          SELECT CASE WHEN (\n            SELECT predecessor_generation_id FROM archive_generations\n            WHERE generation_id=NEW.generation_id\n          ) IS NULL AND EXISTS (\n            SELECT 1 FROM archive_generation_registration_receipts\n          ) THEN RAISE(ABORT, 'archive generation has multiple genesis receipts') END;\n          SELECT CASE WHEN (\n            SELECT predecessor_generation_id FROM archive_generations\n            WHERE generation_id=NEW.generation_id\n          ) IS NOT NULL AND NOT EXISTS (\n            SELECT 1 FROM archive_generation_registration_receipts prior\n            JOIN archive_generations current ON current.generation_id=NEW.generation_id\n            JOIN archive_generations predecessor\n              ON predecessor.generation_id=current.predecessor_generation_id\n            WHERE prior.generation_id=predecessor.generation_id\n              AND current.predecessor_manifest_sha256=predecessor.manifest_sha256\n              AND current.publication_sequence_start=predecessor.publication_sequence_end+1\n          ) THEN RAISE(ABORT, 'archive generation predecessor is not verified and contiguous') END;\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_archive_table_after_seal\n        BEFORE INSERT ON archive_generation_table_commitments\n        WHEN EXISTS (\n          SELECT 1 FROM archive_generation_registration_receipts r WHERE r.generation_id=NEW.generation_id\n        )\n        BEGIN SELECT RAISE(ABORT, 'archive generation is sealed'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_artifacts_dirty_on_commitment_insert\nAFTER INSERT ON management_commitments\nBEGIN\n  UPDATE llm_artifacts\n  SET dirty = 1, dirty_reason = 'management_commitments_insert'\n  WHERE ticker = NEW.ticker\n    AND superseded_by_id IS NULL\n    AND dirty = 0\n    AND purpose IN ('saydo_filter', 'bear_case');\nEND")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_artifacts_dirty_on_exec_comp_insert\nAFTER INSERT ON exec_comp_packages\nBEGIN\n  UPDATE llm_artifacts\n  SET dirty = 1, dirty_reason = 'exec_comp_packages_insert'\n  WHERE ticker = NEW.ticker\n    AND superseded_by_id IS NULL\n    AND dirty = 0\n    AND purpose IN ('exec_comp_alignment');\nEND")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_artifacts_dirty_on_insider_insert\nAFTER INSERT ON insider_transactions\nBEGIN\n  UPDATE llm_artifacts\n  SET dirty = 1, dirty_reason = 'insider_transactions_insert'\n  WHERE ticker = NEW.ticker\n    AND superseded_by_id IS NULL\n    AND dirty = 0\n    AND purpose IN ('exec_comp_alignment');\nEND")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_artifacts_dirty_on_segment_dimensions_insert\n        AFTER INSERT ON segment_dimensions\n        BEGIN\n            UPDATE llm_artifacts\n            SET dirty = 1, dirty_reason = 'segment_dimensions_insert'\n            WHERE ticker = (\n                SELECT ticker FROM segment_periods WHERE id = NEW.period_id\n            )\n              AND superseded_by_id IS NULL\n              AND dirty = 0\n              AND purpose IN ('bear_case', 'company_description');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_citation_exact BEFORE INSERT ON ask_answer_audit_citations WHEN NOT EXISTS (SELECT 1 FROM ask_answer_audit_retrievals bound JOIN heterogeneous_retrieval_trace_results result ON result.trace_id=bound.trace_id AND result.result_ordinal=NEW.result_ordinal JOIN heterogeneous_retrieval_trace_candidates candidate ON candidate.trace_id=result.trace_id AND candidate.candidate_ordinal=result.candidate_ordinal WHERE bound.answer_id=NEW.answer_id AND bound.trace_id=NEW.trace_id AND candidate.candidate_kind=NEW.candidate_kind AND candidate.candidate_id=NEW.candidate_id AND candidate.source_commitment_sha256=NEW.source_commitment_sha256) BEGIN SELECT RAISE(ABORT, 'citation must reference an exact bound trace result'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_citations_append_only BEFORE UPDATE ON ask_answer_audit_citations BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
