    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_citations_identity_immutable BEFORE INSERT ON ask_answer_audit_citations WHEN EXISTS (SELECT 1 FROM ask_answer_audit_citations existing WHERE existing.answer_id=NEW.answer_id AND (existing.citation_number=NEW.citation_number OR (existing.trace_id=NEW.trace_id AND existing.result_ordinal=NEW.result_ordinal))) BEGIN SELECT RAISE(ABORT, 'sealed Ask audit identity is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_citations_unsealed BEFORE INSERT ON ask_answer_audit_citations WHEN EXISTS (SELECT 1 FROM ask_answer_audit_seals WHERE answer_id=NEW.answer_id) BEGIN SELECT RAISE(ABORT, 'sealed Ask answer cannot receive children'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_claim_citations_append_only BEFORE UPDATE ON ask_answer_audit_claim_citations BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_claim_citations_append_only_delete BEFORE DELETE ON ask_answer_audit_claim_citations BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_claim_citations_identity_immutable BEFORE INSERT ON ask_answer_audit_claim_citations WHEN EXISTS (SELECT 1 FROM ask_answer_audit_claim_citations existing WHERE existing.answer_id=NEW.answer_id AND existing.claim_ordinal=NEW.claim_ordinal AND existing.citation_number=NEW.citation_number) BEGIN SELECT RAISE(ABORT, 'sealed Ask audit identity is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_claim_citations_unsealed BEFORE INSERT ON ask_answer_audit_claim_citations WHEN EXISTS (SELECT 1 FROM ask_answer_audit_seals WHERE answer_id=NEW.answer_id) BEGIN SELECT RAISE(ABORT, 'sealed Ask answer cannot receive children'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_claim_exact_span BEFORE INSERT ON ask_answer_audit_claims WHEN NOT EXISTS (SELECT 1 FROM ask_answer_audit_records answer WHERE answer.answer_id=NEW.answer_id AND NEW.char_end<=length(answer.answer_text) AND substr(answer.answer_text,NEW.char_start+1,NEW.char_end-NEW.char_start)=NEW.claim_text) BEGIN SELECT RAISE(ABORT, 'Ask claim text does not equal its answer span'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_claims_append_only BEFORE UPDATE ON ask_answer_audit_claims BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_claims_append_only_delete BEFORE DELETE ON ask_answer_audit_claims BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_claims_identity_immutable BEFORE INSERT ON ask_answer_audit_claims WHEN EXISTS (SELECT 1 FROM ask_answer_audit_claims existing WHERE existing.answer_id=NEW.answer_id AND existing.claim_ordinal=NEW.claim_ordinal) BEGIN SELECT RAISE(ABORT, 'sealed Ask audit identity is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_claims_unsealed BEFORE INSERT ON ask_answer_audit_claims WHEN EXISTS (SELECT 1 FROM ask_answer_audit_seals WHERE answer_id=NEW.answer_id) BEGIN SELECT RAISE(ABORT, 'sealed Ask answer cannot receive children'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_record_claim_llm BEFORE INSERT ON ask_answer_audit_records WHEN NOT EXISTS (SELECT 1 FROM llm_calls call WHERE call.id=NEW.claim_audit_llm_call_id AND call.run_id=NEW.claim_audit_run_id AND call.purpose=NEW.claim_audit_purpose AND call.template_id=NEW.claim_audit_template_id AND call.template_version=NEW.claim_audit_template_version AND call.template_vars_sha256=NEW.claim_audit_template_vars_sha256 AND call.model=NEW.claim_auditor_model AND call.provider=NEW.claim_audit_provider AND call.transport=NEW.claim_audit_transport AND call.prompt_sha256=NEW.claim_audit_prompt_sha256 AND call.response_sha256=NEW.claim_audit_response_sha256 AND call.error IS NULL) BEGIN SELECT RAISE(ABORT, 'Ask claim-audit LLM call identity mismatch'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_record_llm BEFORE INSERT ON ask_answer_audit_records WHEN NOT EXISTS (SELECT 1 FROM llm_calls call WHERE call.id=NEW.llm_call_id AND call.purpose=NEW.llm_purpose AND call.run_id=NEW.llm_run_id AND call.model=NEW.llm_model AND call.provider=NEW.llm_provider AND call.transport=NEW.llm_transport AND call.template_id=NEW.prompt_template_id AND call.template_version=NEW.prompt_template_version AND call.template_vars_sha256=NEW.prompt_template_vars_sha256 AND call.prompt_sha256=NEW.prompt_sha256 AND call.response_sha256=NEW.answer_sha256 AND call.error IS NULL) BEGIN SELECT RAISE(ABORT, 'Ask answer LLM call identity mismatch'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_record_session BEFORE INSERT ON ask_answer_audit_records WHEN NEW.session_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ask_sessions session WHERE session.id=NEW.session_id AND session.scope=NEW.surface) BEGIN SELECT RAISE(ABORT, 'Ask answer session identity mismatch'); END")
