    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_records_identity_immutable BEFORE INSERT ON ask_answer_audit_records WHEN EXISTS (SELECT 1 FROM ask_answer_audit_records existing WHERE existing.answer_id=NEW.answer_id OR existing.idempotency_key=NEW.idempotency_key OR existing.request_id=NEW.request_id) BEGIN SELECT RAISE(ABORT, 'sealed Ask audit identity is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_retrieval_exact BEFORE INSERT ON ask_answer_audit_retrievals WHEN NOT EXISTS (SELECT 1 FROM ask_answer_audit_records answer JOIN ask_retrieval_scope_promotions promotion ON promotion.promotion_id=NEW.promotion_id JOIN heterogeneous_retrieval_trace_headers header ON header.trace_id=NEW.trace_id JOIN heterogeneous_retrieval_trace_seals seal ON seal.trace_id=header.trace_id WHERE answer.answer_id=NEW.answer_id AND answer.request_id=NEW.request_id AND answer.query_sha256=NEW.query_sha256 AND header.query_sha256=NEW.query_sha256 AND header.idempotency_key='ask-request:'||NEW.request_id||':'||NEW.query_sha256||':'||NEW.promotion_id AND header.research_snapshot_id=promotion.research_snapshot_id AND header.fact_generation_id=promotion.fact_generation_id AND seal.trace_sha256=NEW.trace_sha256 AND header.research_snapshot_sha256=NEW.research_snapshot_sha256) BEGIN SELECT RAISE(ABORT, 'answer retrieval must reference an exact sealed trace'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_retrievals_append_only BEFORE UPDATE ON ask_answer_audit_retrievals BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_retrievals_append_only_delete BEFORE DELETE ON ask_answer_audit_retrievals BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_retrievals_identity_immutable BEFORE INSERT ON ask_answer_audit_retrievals WHEN EXISTS (SELECT 1 FROM ask_answer_audit_retrievals existing WHERE existing.answer_id=NEW.answer_id AND (existing.trace_ordinal=NEW.trace_ordinal OR existing.trace_id=NEW.trace_id)) BEGIN SELECT RAISE(ABORT, 'sealed Ask audit identity is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_retrievals_unsealed BEFORE INSERT ON ask_answer_audit_retrievals WHEN EXISTS (SELECT 1 FROM ask_answer_audit_seals WHERE answer_id=NEW.answer_id) BEGIN SELECT RAISE(ABORT, 'sealed Ask answer cannot receive children'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_seal_counts BEFORE INSERT ON ask_answer_audit_seals WHEN NEW.retrieval_count<>(SELECT COUNT(*) FROM ask_answer_audit_retrievals WHERE answer_id=NEW.answer_id) OR NEW.citation_count<>(SELECT COUNT(*) FROM ask_answer_audit_citations WHERE answer_id=NEW.answer_id) OR NEW.claim_count<>(SELECT COUNT(*) FROM ask_answer_audit_claims WHERE answer_id=NEW.answer_id) OR NEW.unsupported_claim_count<>(SELECT COUNT(*) FROM ask_answer_audit_claims WHERE answer_id=NEW.answer_id AND supported=0) OR NEW.claim_citation_count<>(SELECT COUNT(*) FROM ask_answer_audit_claim_citations WHERE answer_id=NEW.answer_id) BEGIN SELECT RAISE(ABORT, 'Ask answer audit seal counts do not match'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_seal_ordinals BEFORE INSERT ON ask_answer_audit_seals WHEN (NEW.retrieval_count>0 AND ((SELECT MIN(trace_ordinal) FROM ask_answer_audit_retrievals WHERE answer_id=NEW.answer_id)<>0 OR (SELECT MAX(trace_ordinal) FROM ask_answer_audit_retrievals WHERE answer_id=NEW.answer_id)<>NEW.retrieval_count-1)) OR (NEW.claim_count>0 AND ((SELECT MIN(claim_ordinal) FROM ask_answer_audit_claims WHERE answer_id=NEW.answer_id)<>0 OR (SELECT MAX(claim_ordinal) FROM ask_answer_audit_claims WHERE answer_id=NEW.answer_id)<>NEW.claim_count-1)) BEGIN SELECT RAISE(ABORT, 'Ask answer audit ordinals are not contiguous'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_seal_support BEFORE INSERT ON ask_answer_audit_seals WHEN EXISTS (SELECT 1 FROM ask_answer_audit_claims claim WHERE claim.answer_id=NEW.answer_id AND ((claim.supported=1 AND NOT EXISTS (SELECT 1 FROM ask_answer_audit_claim_citations edge WHERE edge.answer_id=claim.answer_id AND edge.claim_ordinal=claim.claim_ordinal)) OR (claim.supported=0 AND EXISTS (SELECT 1 FROM ask_answer_audit_claim_citations edge WHERE edge.answer_id=claim.answer_id AND edge.claim_ordinal=claim.claim_ordinal)))) OR EXISTS (SELECT 1 FROM ask_answer_audit_citations citation WHERE citation.answer_id=NEW.answer_id AND NOT EXISTS (SELECT 1 FROM ask_answer_audit_claim_citations edge WHERE edge.answer_id=citation.answer_id AND edge.citation_number=citation.citation_number)) BEGIN SELECT RAISE(ABORT, 'Ask answer support graph is incomplete'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_seals_append_only BEFORE UPDATE ON ask_answer_audit_seals BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_seals_append_only_delete BEFORE DELETE ON ask_answer_audit_seals BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_audit_seals_identity_immutable BEFORE INSERT ON ask_answer_audit_seals WHEN EXISTS (SELECT 1 FROM ask_answer_audit_seals existing WHERE existing.answer_id=NEW.answer_id) BEGIN SELECT RAISE(ABORT, 'sealed Ask audit identity is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_groundings_append_only BEFORE UPDATE ON ask_answer_groundings BEGIN SELECT RAISE(ABORT, 'Ask grounding lineage is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_answer_groundings_append_only_delete BEFORE DELETE ON ask_answer_groundings BEGIN SELECT RAISE(ABORT, 'Ask grounding lineage is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_scope_promotion_chain BEFORE INSERT ON ask_retrieval_scope_promotions WHEN NEW.revision>1 AND NOT EXISTS (SELECT 1 FROM ask_retrieval_scope_promotions prior WHERE prior.promotion_id=NEW.supersedes_promotion_id AND prior.scope_key=NEW.scope_key AND prior.revision=NEW.revision-1) BEGIN SELECT RAISE(ABORT, 'Ask retrieval promotion chain is incomplete'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_scope_promotion_population_cutover BEFORE INSERT ON ask_retrieval_scope_promotions WHEN NEW.population_run_id IS NULL OR NEW.population_receipt_set_sha256 IS NULL OR NEW.population_observed_through IS NULL OR NOT (length(NEW.population_receipt_set_sha256)=64 AND NEW.population_receipt_set_sha256 NOT GLOB '*[^0-9a-f]*') OR NOT EXISTS (SELECT 1 FROM population_run_headers run JOIN population_cutover_receipts receipt ON receipt.population_run_id=run.population_run_id WHERE run.population_run_id=NEW.population_run_id AND receipt.receipt_set_sha256=NEW.population_receipt_set_sha256 AND datetime(run.knowledge_cutoff)=datetime(NEW.cutoff_at) AND datetime(run.observed_through)=datetime(NEW.population_observed_through) AND datetime(receipt.knowledge_cutoff)=datetime(NEW.cutoff_at) AND datetime(receipt.observed_through)=datetime(NEW.population_observed_through)) OR NOT EXISTS (SELECT 1 FROM v_population_cutover_current current WHERE current.population_run_id=NEW.population_run_id AND current.receipt_set_sha256=NEW.population_receipt_set_sha256 AND datetime(current.knowledge_cutoff)=datetime(NEW.cutoff_at) AND datetime(current.observed_through)=datetime(NEW.population_observed_through)) BEGIN SELECT RAISE(ABORT, 'Ask retrieval promotion requires its exact current population cutover'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_scope_promotion_projection BEFORE INSERT ON ask_retrieval_scope_promotions WHEN NOT EXISTS (SELECT 1 FROM canonical_fact_projection_seals seal WHERE seal.generation_id=NEW.fact_generation_id AND seal.projection_seal_sha256=NEW.fact_projection_seal_sha256) BEGIN SELECT RAISE(ABORT, 'Ask promotion requires a sealed fact projection'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_scope_promotion_snapshot BEFORE INSERT ON ask_retrieval_scope_promotions WHEN NOT EXISTS (SELECT 1 FROM research_snapshot_seals seal JOIN research_snapshot_admission_receipts receipt ON receipt.research_snapshot_id=seal.research_snapshot_id JOIN research_snapshot_universe_commitments universe ON universe.research_snapshot_id=seal.research_snapshot_id WHERE seal.research_snapshot_id=NEW.research_snapshot_id AND seal.member_set_sha256=NEW.research_snapshot_sha256 AND receipt.research_snapshot_sha256=NEW.research_snapshot_sha256 AND universe.issuer_id=NEW.issuer_id AND EXISTS (SELECT 1 FROM json_each(universe.reporting_entity_ids_json) WHERE value=NEW.reporting_entity_id)) BEGIN SELECT RAISE(ABORT, 'Ask promotion requires an admitted Research Snapshot'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_scope_promotion_source_scope_exact BEFORE INSERT ON ask_retrieval_scope_promotions WHEN NEW.scope_key<>derive_retrieval_scope_id(NEW.source_scope_key,NEW.issuer_id) OR length(NEW.scope_key)<>77 OR substr(NEW.scope_key,1,13)<>'ask-scope:v1:' OR substr(NEW.scope_key,14) GLOB '*[^0-9a-f]*' OR NEW.source_scope_key IS NULL OR length(NEW.source_scope_key)=0 OR NEW.source_scope_revision_id IS NULL OR length(NEW.source_scope_revision_id)=0 OR NOT EXISTS (SELECT 1 FROM v_issuer_reporting_scope_current source WHERE source.scope_revision_id=NEW.source_scope_revision_id AND source.scope_key=NEW.source_scope_key AND source.issuer_id=NEW.issuer_id AND source.inclusion_state='core') BEGIN SELECT RAISE(ABORT, 'Ask promotion requires its exact current composite source scope'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_scope_promotions_append_only BEFORE UPDATE ON ask_retrieval_scope_promotions BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_scope_promotions_append_only_delete BEFORE DELETE ON ask_retrieval_scope_promotions BEGIN SELECT RAISE(ABORT, 'sealed Ask audit data is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_scope_promotions_identity_immutable BEFORE INSERT ON ask_retrieval_scope_promotions WHEN EXISTS (SELECT 1 FROM ask_retrieval_scope_promotions existing WHERE existing.promotion_id=NEW.promotion_id OR existing.idempotency_key=NEW.idempotency_key OR (existing.scope_key=NEW.scope_key AND existing.revision=NEW.revision)) BEGIN SELECT RAISE(ABORT, 'sealed Ask audit identity is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_trace_hits_append_only BEFORE UPDATE ON ask_retrieval_trace_hits BEGIN SELECT RAISE(ABORT, 'heterogeneous retrieval trace is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_trace_hits_append_only_delete BEFORE DELETE ON ask_retrieval_trace_hits BEGIN SELECT RAISE(ABORT, 'heterogeneous retrieval trace is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_trace_hits_document BEFORE INSERT ON ask_retrieval_trace_hits WHEN NEW.hit_kind = 'document' AND NOT EXISTS (SELECT 1 FROM search_chunks AS chunk JOIN search_corpus_manifest_seals AS seal ON seal.manifest_id = chunk.manifest_id WHERE chunk.chunk_id = NEW.chunk_id AND chunk.manifest_id = NEW.manifest_id AND seal.completion_status = 'complete') BEGIN SELECT RAISE(ABORT, 'document hit requires a chunk from its complete corpus'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_trace_hits_fact BEFORE INSERT ON ask_retrieval_trace_hits WHEN NEW.hit_kind = 'fact' AND NOT EXISTS (SELECT 1 FROM search_fact_projection_rows AS row JOIN search_fact_projection_seals AS seal ON seal.projection_run_id = row.projection_run_id WHERE row.fact_hit_id = NEW.fact_hit_id AND row.projection_run_id = NEW.projection_run_id) BEGIN SELECT RAISE(ABORT, 'fact hit requires a row from its sealed projection'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_trace_hits_rank_legacy BEFORE INSERT ON ask_retrieval_trace_hits WHEN EXISTS (SELECT 1 FROM ask_retrieval_trace_items AS item WHERE item.trace_id = NEW.trace_id AND item.rank = NEW.rank) BEGIN SELECT RAISE(ABORT, 'retrieval rank already belongs to a legacy document hit'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_trace_items_append_only BEFORE UPDATE ON ask_retrieval_trace_items BEGIN SELECT RAISE(ABORT, 'Ask grounding lineage is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_trace_items_append_only_delete BEFORE DELETE ON ask_retrieval_trace_items BEGIN SELECT RAISE(ABORT, 'Ask grounding lineage is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_trace_items_rank_v2 BEFORE INSERT ON ask_retrieval_trace_items WHEN EXISTS (SELECT 1 FROM ask_retrieval_trace_hits AS hit WHERE hit.trace_id = NEW.trace_id AND hit.rank = NEW.rank) BEGIN SELECT RAISE(ABORT, 'retrieval rank already belongs to a heterogeneous hit'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_traces_append_only BEFORE UPDATE ON ask_retrieval_traces BEGIN SELECT RAISE(ABORT, 'Ask grounding lineage is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ask_retrieval_traces_append_only_delete BEFORE DELETE ON ask_retrieval_traces BEGIN SELECT RAISE(ABORT, 'Ask grounding lineage is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_binding_derived_quarantine\n        BEFORE INSERT ON fact_cell_canonical_binding_revisions\n        WHEN NEW.binding_status='quarantined'\n         AND NOT EXISTS (\n            SELECT 1 FROM fact_observations_v2 observation\n            WHERE observation.observation_id=NEW.source_observation_id\n              AND observation.fact_cell_id=NEW.fact_cell_id\n              AND observation.observation_kind='derived')\n        BEGIN\n            SELECT RAISE(ABORT,\n                'only derived observations use terminal ontology quarantine');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_binding_exact_coordinate\n        BEFORE INSERT ON fact_cell_canonical_binding_revisions\n        WHEN NEW.binding_status='bound' AND NOT EXISTS (\n            SELECT 1\n            FROM fact_cells_v2 source_cell\n            JOIN fact_observations_v2 observation\n              ON observation.observation_id=NEW.source_observation_id\n             AND observation.fact_cell_id=source_cell.fact_cell_id\n             AND observation.observation_kind='reported'\n            JOIN fact_reported_observation_anchors_v2 anchor\n              ON anchor.observation_id=observation.observation_id\n            JOIN source_observation_taxonomy_assertions taxonomy\n              ON taxonomy.observation_id=observation.observation_id\n             AND taxonomy.taxonomy_version=anchor.source_taxonomy_version\n            JOIN source_taxonomy_components source\n              ON source.component_id=NEW.source_component_id\n             AND source.component_kind='concept'\n             AND source.taxonomy_namespace=source_cell.concept_namespace\n             AND source.local_name=source_cell.concept_name\n             AND source.taxonomy_version=anchor.source_taxonomy_version\n             AND source.taxonomy_name=taxonomy.taxonomy_name\n             AND source.definition_qualifier_sha256=fact_sha256(json_object(\n                    'accounting_basis',source_cell.accounting_basis,\n                    'concept_name',source_cell.concept_name,\n                    'concept_namespace',source_cell.concept_namespace,\n                    'consolidation_scope',source_cell.consolidation_scope,\n                    'period_kind',source_cell.period_kind,\n                    'reporting_entity_id',source_cell.reporting_entity_id,\n                    'schema_version','source-definition-identity/v1',\n                    'taxonomy_name',source_cell.taxonomy_name,\n                    'taxonomy_version',anchor.source_taxonomy_version,\n                    'unit_family',CASE\n                        WHEN source_cell.currency IS NOT NULL THEN 'currency'\n                        WHEN lower(source_cell.unit_key) IN ('pure','shares')\n                            THEN lower(source_cell.unit_key)\n                        ELSE source_cell.unit_key END,\n                    'value_kind',(\n                        SELECT MIN(kind.value_kind)\n                        FROM fact_observations_v2 kind\n                        WHERE kind.fact_cell_id=source_cell.fact_cell_id\n                          AND kind.observation_kind='reported'\n                          AND kind.value_kind<>'nil'\n                        GROUP BY kind.fact_cell_id\n                        HAVING COUNT(DISTINCT kind.value_kind)=1)))\n             AND source.reporting_entity_scope_key IN (\n                    '__global__', source_cell.reporting_entity_id)\n            JOIN metric_mapping_revisions mapping\n              ON mapping.mapping_revision_id=NEW.mapping_revision_id\n             AND mapping.source_component_id=source.component_id\n             AND mapping.disposition IN ('exact','equivalent','derived')\n            JOIN canonical_metric_cells target\n              ON target.canonical_metric_cell_id=NEW.canonical_metric_cell_id\n             AND target.metric_id=mapping.metric_id\n             AND target.reporting_entity_id=source_cell.reporting_entity_id\n             AND target.scope_security_id IS source_cell.scope_security_id\n             AND target.period_kind=source_cell.period_kind\n             AND datetime(target.period_start) IS datetime(source_cell.period_start)\n             AND datetime(target.period_end)=datetime(source_cell.period_end)\n             AND target.accounting_basis=source_cell.accounting_basis\n             AND target.consolidation_scope=source_cell.consolidation_scope\n             AND target.unit_family=CASE\n                    WHEN source_cell.currency IS NOT NULL THEN 'currency'\n                    WHEN lower(source_cell.unit_key) IN ('pure','shares')\n                        THEN lower(source_cell.unit_key)\n                    ELSE source_cell.unit_key END\n            JOIN canonical_metric_cell_seals target_seal\n              ON target_seal.canonical_metric_cell_id=target.canonical_metric_cell_id\n            WHERE source_cell.fact_cell_id=NEW.fact_cell_id\n              AND datetime(mapping.effective_at) <= datetime(NEW.effective_at)\n              AND datetime(mapping.knowledge_at) <= datetime(NEW.knowledge_at)\n              AND datetime(mapping.recorded_at) <= datetime(NEW.recorded_at)\n              AND datetime(taxonomy.knowledge_at) <= datetime(NEW.knowledge_at)\n              AND datetime(taxonomy.recorded_at) <= datetime(NEW.recorded_at)\n              AND datetime(source.effective_at) <= datetime(NEW.effective_at)\n              AND datetime(source.knowledge_at) <= datetime(NEW.knowledge_at)\n              AND datetime(source.recorded_at) <= datetime(NEW.recorded_at)\n              AND datetime(source_cell.effective_at) <= datetime(NEW.effective_at)\n              AND datetime(source_cell.knowledge_at) <= datetime(NEW.knowledge_at)\n              AND datetime(source_cell.recorded_at) <= datetime(NEW.recorded_at)\n              AND datetime(target.effective_at) <= datetime(NEW.effective_at)\n              AND datetime(target.knowledge_at) <= datetime(NEW.knowledge_at)\n              AND datetime(target.recorded_at) <= datetime(NEW.recorded_at)\n              AND datetime(target_seal.sealed_at) <= datetime(NEW.recorded_at)\n              AND target.dimension_count = (\n                    SELECT COUNT(*) FROM fact_dimensions_normalized_v2 dim\n                    WHERE dim.fact_cell_id=source_cell.fact_cell_id)\n              AND NOT EXISTS (\n                SELECT 1\n                FROM fact_dimensions_normalized_v2 dim\n                WHERE dim.fact_cell_id=source_cell.fact_cell_id\n                  AND (\n                    dim.member_kind <> 'explicit'\n                    OR NOT EXISTS (\n                        SELECT 1\n                        FROM source_taxonomy_components source_axis\n                        JOIN source_dimension_mapping_revisions axis_map\n                          ON axis_map.source_component_id=source_axis.component_id\n                        JOIN source_taxonomy_components source_member\n                          ON source_member.component_kind='member'\n                         AND source_member.taxonomy_namespace=\n                             dim.explicit_member_namespace\n                         AND source_member.local_name=dim.explicit_member_name\n                         AND source_member.taxonomy_name=taxonomy.taxonomy_name\n                         AND source_member.taxonomy_version=\n                             anchor.source_taxonomy_version\n                         AND source_member.reporting_entity_scope_key IN (\n                             '__global__', source_cell.reporting_entity_id)\n                        JOIN source_dimension_mapping_revisions member_map\n                          ON member_map.source_component_id=\n                             source_member.component_id\n                        JOIN canonical_metric_cell_dimensions target_dim\n                          ON target_dim.canonical_metric_cell_id=\n                             target.canonical_metric_cell_id\n                         AND target_dim.axis_id=axis_map.canonical_axis_id\n                         AND target_dim.member_id=member_map.canonical_member_id\n                        WHERE source_axis.component_kind='axis'\n                          AND source_axis.taxonomy_namespace=dim.axis_namespace\n                          AND source_axis.local_name=dim.axis_name\n                          AND source_axis.taxonomy_name=taxonomy.taxonomy_name\n                          AND source_axis.taxonomy_version=\n                              anchor.source_taxonomy_version\n                          AND source_axis.reporting_entity_scope_key IN (\n                              '__global__', source_cell.reporting_entity_id)\n                          AND axis_map.disposition IN ('exact','equivalent')\n                          AND member_map.disposition IN ('exact','equivalent')\n                          AND axis_map.revision=(\n                              SELECT MAX(candidate.revision)\n                              FROM source_dimension_mapping_revisions candidate\n                              WHERE candidate.source_component_id=\n                                    source_axis.component_id\n                                AND datetime(candidate.effective_at)\n                                    <= datetime(NEW.effective_at)\n                                AND datetime(candidate.knowledge_at)\n                                    <= datetime(NEW.knowledge_at)\n                                AND datetime(candidate.recorded_at)\n                                    <= datetime(NEW.recorded_at))\n                          AND member_map.revision=(\n                              SELECT MAX(candidate.revision)\n                              FROM source_dimension_mapping_revisions candidate\n                              WHERE candidate.source_component_id=\n                                    source_member.component_id\n                                AND datetime(candidate.effective_at)\n                                    <= datetime(NEW.effective_at)\n                                AND datetime(candidate.knowledge_at)\n                                    <= datetime(NEW.knowledge_at)\n                                AND datetime(candidate.recorded_at)\n                                    <= datetime(NEW.recorded_at))\n                    )\n                  )\n              )\n        )\n        BEGIN\n            SELECT RAISE(ABORT,\n                'binding source assertion is incompatible with canonical cell');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_binding_observation_coordinate\n        BEFORE INSERT ON fact_cell_canonical_binding_revisions\n        WHEN NOT EXISTS (\n            SELECT 1 FROM fact_observations_v2 observation\n            WHERE observation.observation_id=NEW.source_observation_id\n              AND observation.fact_cell_id=NEW.fact_cell_id)\n        BEGIN\n            SELECT RAISE(ABORT,\n                'binding observation does not belong to its fact cell');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_binding_quarantine_terminal\n        BEFORE INSERT ON fact_cell_canonical_binding_revisions\n        WHEN NEW.supersedes_binding_revision_id IS NOT NULL\n         AND EXISTS (\n            SELECT 1 FROM fact_cell_canonical_binding_revisions parent\n            WHERE parent.binding_revision_id=NEW.supersedes_binding_revision_id\n              AND parent.binding_status='quarantined')\n        BEGIN\n            SELECT RAISE(ABORT, 'quarantined binding revisions are terminal');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_binding_reason_details_exact\n        BEFORE INSERT ON fact_cell_canonical_binding_revisions\n        WHEN NEW.reason_details_json IS NOT NULL\n         AND NEW.reason_details_sha256 <> fact_sha256(NEW.reason_details_json)\n        BEGIN\n            SELECT RAISE(ABORT, 'binding reason details mismatch');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_canonical_axes_commitment_exact BEFORE INSERT ON canonical_axes WHEN NEW.commitment_sha256 <> fact_sha256(NEW.commitment_json) BEGIN SELECT RAISE(ABORT, 'canonical_axes commitment mismatch'); END")
