    op.execute("CREATE TRIGGER IF NOT EXISTS trg_canonical_fact_projection_buckets_unsealed BEFORE INSERT ON canonical_fact_projection_buckets WHEN EXISTS (SELECT 1 FROM canonical_fact_projection_seals seal WHERE seal.generation_id=NEW.generation_id) BEGIN SELECT RAISE(ABORT, 'canonical fact projection is sealed'); END")
