    op.execute("CREATE TRIGGER IF NOT EXISTS trg_canonical_fact_projection_entries_unsealed BEFORE INSERT ON canonical_fact_projection_entries WHEN EXISTS (SELECT 1 FROM canonical_fact_projection_seals seal WHERE seal.generation_id=NEW.generation_id) BEGIN SELECT RAISE(ABORT, 'canonical fact projection is sealed'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_canonical_fact_projection_generation_parent BEFORE INSERT ON canonical_fact_projection_generations WHEN NEW.parent_generation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM canonical_fact_projection_generations parent JOIN canonical_fact_projection_seals seal ON seal.generation_id=parent.generation_id WHERE parent.generation_id=NEW.parent_generation_id AND parent.delta_depth+1=NEW.delta_depth AND parent.cutoff_at<=NEW.cutoff_at) BEGIN SELECT RAISE(ABORT, 'projection delta requires exact sealed parent'); END")
