    op.execute("CREATE TRIGGER IF NOT EXISTS trg_canonical_fact_relation_assertions_update_append_only BEFORE UPDATE ON canonical_fact_relation_assertions BEGIN SELECT RAISE(ABORT, 'canonical_fact_relation_assertions is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_canonical_fact_relation_final_exact BEFORE INSERT ON canonical_fact_relation_set_seals WHEN NOT EXISTS (SELECT 1 FROM canonical_fact_relation_set_revisions h WHERE h.relation_set_id=NEW.relation_set_id AND h.relation_count=NEW.relation_count AND h.canonical_relation_set_json=NEW.canonical_relation_set_json AND h.relation_set_sha256=NEW.relation_set_sha256 AND h.recorded_at=NEW.sealed_at) OR NEW.relation_count<>(SELECT COUNT(*) FROM canonical_fact_relation_assertions a WHERE a.relation_set_id=NEW.relation_set_id) OR (NEW.relation_count>0 AND ((SELECT MIN(relation_ordinal) FROM canonical_fact_relation_assertions WHERE relation_set_id=NEW.relation_set_id)<>0 OR (SELECT MAX(relation_ordinal) FROM canonical_fact_relation_assertions WHERE relation_set_id=NEW.relation_set_id)<>NEW.relation_count-1)) OR NEW.canonical_relation_set_json<>COALESCE((SELECT json_group_array(json(ordered.payload)) FROM (SELECT json_object('evidence',json(a.evidence_json),'object_observation_id',a.object_observation_id,'relation_kind',a.relation_kind,'subject_filing_disposition_id',a.subject_filing_disposition_id,'subject_observation_id',a.subject_observation_id) payload FROM canonical_fact_relation_assertions a WHERE a.relation_set_id=NEW.relation_set_id ORDER BY a.relation_ordinal) ordered),'[]') OR NEW.relation_set_sha256<>fact_sha256(NEW.canonical_relation_set_json) BEGIN SELECT RAISE(ABORT, 'canonical relation set final seal mismatch'); END")
