    op.execute("CREATE TRIGGER IF NOT EXISTS trg_canonical_fact_relation_set_sealed BEFORE INSERT ON canonical_fact_relation_assertions WHEN EXISTS (SELECT 1 FROM canonical_fact_relation_set_seals s WHERE s.relation_set_id=NEW.relation_set_id) BEGIN SELECT RAISE(ABORT, 'canonical relation set is sealed'); END")
