    op.execute("CREATE TRIGGER IF NOT EXISTS trg_document_processing_evidence_header_native_parent BEFORE INSERT ON document_processing_evidence_headers WHEN NOT EXISTS (SELECT 1 FROM evidence_extraction_runs run JOIN evidence_document_versions document ON document.document_version_id=run.document_version_id WHERE run.extraction_run_id=NEW.extraction_run_id AND run.document_version_id=NEW.document_version_id AND run.input_sha256=NEW.input_blob_sha256 AND run.output_sha256=NEW.native_output_sha256 AND run.outcome='succeeded' AND datetime(run.completed_at)<=datetime(NEW.cutoff_at) AND datetime(document.recorded_at)<=datetime(NEW.recorded_at)) BEGIN SELECT RAISE(ABORT, 'processing evidence header does not match its native run'); END")
