    op.execute("CREATE TRIGGER IF NOT EXISTS trg_document_processing_snapshot_seals_exact BEFORE INSERT ON document_processing_snapshot_seals WHEN NEW.member_count <> (SELECT COUNT(*) FROM document_processing_snapshot_members member WHERE member.processing_snapshot_id=NEW.processing_snapshot_id) OR (NEW.member_count > 0 AND NEW.member_count <> 1 + (SELECT MAX(member_ordinal) FROM document_processing_snapshot_members member WHERE member.processing_snapshot_id=NEW.processing_snapshot_id)) OR NEW.canonical_member_set_json <> COALESCE((SELECT json_group_array(json(canonical_member_json)) FROM (SELECT canonical_member_json FROM document_processing_snapshot_members WHERE processing_snapshot_id=NEW.processing_snapshot_id ORDER BY member_ordinal)), '[]') OR NEW.member_set_sha256 <> fact_sha256(NEW.canonical_member_set_json) OR datetime(NEW.sealed_at) < datetime((SELECT recorded_at FROM document_processing_snapshot_headers header WHERE header.processing_snapshot_id=NEW.processing_snapshot_id)) BEGIN SELECT RAISE(ABORT, 'Document Processing Snapshot final seal mismatch'); END")
