    op.execute("CREATE TRIGGER IF NOT EXISTS trg_document_semantic_disposition_revisions_append_only_delete BEFORE DELETE ON document_semantic_disposition_revisions BEGIN SELECT RAISE(ABORT, 'semantic disposition ledger is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_document_semantic_disposition_revisions_revision_chain BEFORE INSERT ON document_semantic_disposition_revisions WHEN (NEW.revision = 1 AND NEW.supersedes_assessment_id IS NOT NULL) OR (NEW.revision > 1 AND NOT EXISTS (SELECT 1 FROM document_semantic_disposition_revisions AS prior WHERE prior.assessment_id = NEW.supersedes_assessment_id AND prior.document_version_id = NEW.document_version_id AND prior.revision = NEW.revision - 1)) BEGIN SELECT RAISE(ABORT, 'semantic disposition revision chain is invalid'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_embedding_artifacts_runtime_binding BEFORE INSERT ON search_embedding_artifacts WHEN NEW.outcome='succeeded' AND (length(NEW.runtime_artifact_sha256)<>64 OR NEW.runtime_artifact_sha256 GLOB '*[^0-9a-f]*' OR NOT EXISTS (SELECT 1 FROM search_embedding_runtime_registrations runtime WHERE runtime.purpose='evidence_vector_retrieval' AND runtime.provider=NEW.provider AND runtime.model=NEW.model AND runtime.dimensions=NEW.dimensions AND runtime.runtime_artifact_sha256=NEW.runtime_artifact_sha256)) BEGIN SELECT RAISE(ABORT, 'successful embedding requires registered runtime artifact'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_embedding_evaluation_receipt_exact BEFORE INSERT ON search_embedding_evaluation_receipts WHEN NEW.evaluation_artifact_sha256<>fact_sha256(NEW.evaluation_artifact_json) OR NEW.candidate_set_sha256<>fact_sha256(NEW.candidate_set_json) OR NEW.evaluation_receipt_id<>('embedding-evaluation:'||NEW.evaluation_artifact_sha256) OR NEW.idempotency_key<>NEW.evaluation_receipt_id OR (SELECT COUNT(*) FROM json_each(NEW.evaluation_artifact_json))<>9 OR EXISTS (SELECT 1 FROM json_each(NEW.evaluation_artifact_json) WHERE key NOT IN ('candidate_coordinates','evaluated_at','golden_sha256','k','purpose','reason','recommended_model','results','thresholds')) OR json_extract(NEW.evaluation_artifact_json,'$.purpose')<>NEW.purpose OR json_extract(NEW.evaluation_artifact_json,'$.golden_sha256')<>NEW.golden_sha256 OR datetime(json_extract(NEW.evaluation_artifact_json,'$.evaluated_at'))<>datetime(NEW.evaluated_at) OR json_extract(NEW.evaluation_artifact_json,'$.candidate_coordinates')<>NEW.candidate_set_json OR json_type(NEW.evaluation_artifact_json,'$.results') IS NOT 'array' OR json_array_length(NEW.evaluation_artifact_json,'$.results')<>json_array_length(NEW.candidate_set_json) OR EXISTS (SELECT 1 FROM json_each(NEW.evaluation_artifact_json,'$.results') result WHERE (SELECT COUNT(*) FROM json_each(result.value))<>8 OR EXISTS (SELECT 1 FROM json_each(result.value) WHERE key NOT IN ('case_count','coverage','mean_latency_ms','model','mrr','ndcg','recall_at_k','runtime_artifact_sha256')) OR NOT EXISTS (SELECT 1 FROM json_each(NEW.candidate_set_json) candidate WHERE candidate.key=result.key AND json_extract(candidate.value,'$.model')=json_extract(result.value,'$.model') AND json_extract(candidate.value,'$.runtime_artifact_sha256')=json_extract(result.value,'$.runtime_artifact_sha256'))) OR (json_extract(NEW.evaluation_artifact_json,'$.recommended_model') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM json_each(NEW.evaluation_artifact_json,'$.results') result WHERE json_extract(result.value,'$.model')=json_extract(NEW.evaluation_artifact_json,'$.recommended_model'))) OR (SELECT COUNT(*) FROM json_each(NEW.candidate_set_json))<>2 OR (SELECT COUNT(*) FROM json_each(NEW.candidate_set_json) candidate WHERE json_extract(candidate.value,'$.model')='BAAI/bge-base-en-v1.5')<>1 OR (SELECT COUNT(*) FROM json_each(NEW.candidate_set_json) candidate WHERE json_extract(candidate.value,'$.model')='BAAI/bge-small-en-v1.5')<>1 OR (SELECT COUNT(DISTINCT json_extract(value,'$.model')) FROM json_each(NEW.candidate_set_json))<>json_array_length(NEW.candidate_set_json) OR (SELECT COUNT(DISTINCT json_extract(value,'$.runtime_registration_id')) FROM json_each(NEW.candidate_set_json))<>json_array_length(NEW.candidate_set_json) OR (SELECT COUNT(DISTINCT json_extract(value,'$.projection_seal_id')) FROM json_each(NEW.candidate_set_json))<>json_array_length(NEW.candidate_set_json) OR EXISTS (SELECT 1 FROM json_each(NEW.candidate_set_json) earlier JOIN json_each(NEW.candidate_set_json) later ON earlier.key<later.key WHERE json_extract(earlier.value,'$.model')>=json_extract(later.value,'$.model')) OR EXISTS (SELECT 1 FROM json_each(NEW.candidate_set_json) candidate WHERE (SELECT COUNT(*) FROM json_each(candidate.value))<>12 OR EXISTS (SELECT 1 FROM json_each(candidate.value) WHERE key NOT IN ('artifact_set_sha256','chunk_count','chunk_set_sha256','config_sha256','index_run_id','manifest_id','model','projection_records_sha256','projection_seal_id','runtime_artifact_sha256','runtime_registration_id','sealed_at')) OR NOT EXISTS (SELECT 1 FROM search_projection_seals seal JOIN search_embedding_runtime_registrations runtime ON runtime.runtime_registration_id=json_extract(candidate.value,'$.runtime_registration_id') WHERE seal.projection_seal_id=json_extract(candidate.value,'$.projection_seal_id') AND seal.index_kind='vector' AND seal.provider='fastembed' AND seal.model=json_extract(candidate.value,'$.model') AND seal.index_run_id=json_extract(candidate.value,'$.index_run_id') AND seal.manifest_id=json_extract(candidate.value,'$.manifest_id') AND seal.chunk_count=json_extract(candidate.value,'$.chunk_count') AND seal.chunk_set_sha256=json_extract(candidate.value,'$.chunk_set_sha256') AND seal.projection_records_sha256=json_extract(candidate.value,'$.projection_records_sha256') AND seal.artifact_set_sha256=json_extract(candidate.value,'$.artifact_set_sha256') AND seal.config_sha256=json_extract(candidate.value,'$.config_sha256') AND datetime(seal.sealed_at)=datetime(json_extract(candidate.value,'$.sealed_at')) AND seal.runtime_artifact_sha256=json_extract(candidate.value,'$.runtime_artifact_sha256') AND runtime.purpose=NEW.purpose AND runtime.provider=seal.provider AND runtime.model=json_extract(candidate.value,'$.model') AND runtime.dimensions=seal.dimensions AND runtime.runtime_artifact_sha256=seal.runtime_artifact_sha256)) OR (SELECT COUNT(DISTINCT json_extract(value,'$.manifest_id')||':'||json_extract(value,'$.chunk_count')||':'||json_extract(value,'$.chunk_set_sha256')) FROM json_each(NEW.candidate_set_json))<>1 BEGIN SELECT RAISE(ABORT, 'embedding evaluation receipt mismatch'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_embedding_promotions_governed BEFORE INSERT ON search_embedding_model_promotions WHEN NEW.evaluation_receipt_id IS NULL OR NEW.evaluation_artifact_json IS NULL OR NEW.runtime_registration_id IS NULL OR NEW.approval_receipt_json IS NULL OR NEW.approval_receipt_sha256 IS NULL OR NEW.evaluation_artifact_sha256<>fact_sha256(NEW.evaluation_artifact_json) OR NEW.approval_receipt_sha256<>fact_sha256(NEW.approval_receipt_json) OR (SELECT COUNT(*) FROM json_each(NEW.approval_receipt_json))<>7 OR EXISTS (SELECT 1 FROM json_each(NEW.approval_receipt_json) WHERE key NOT IN ('approved_at','approved_by','approved_model','decision','evaluation_artifact_sha256','purpose','rationale')) OR NOT EXISTS (SELECT 1 FROM search_embedding_runtime_registrations runtime WHERE runtime.runtime_registration_id=NEW.runtime_registration_id AND runtime.purpose=NEW.purpose AND runtime.provider=NEW.provider AND runtime.model=NEW.model AND runtime.dimensions=NEW.dimensions AND runtime.runtime_artifact_sha256=NEW.runtime_artifact_sha256 AND runtime.runtime_artifact_json=NEW.runtime_artifact_json) OR NOT EXISTS (SELECT 1 FROM search_embedding_evaluation_receipts receipt WHERE receipt.evaluation_receipt_id=NEW.evaluation_receipt_id AND receipt.evaluation_artifact_sha256=NEW.evaluation_artifact_sha256 AND receipt.evaluation_artifact_json=NEW.evaluation_artifact_json AND receipt.golden_sha256=NEW.golden_sha256 AND json_extract(receipt.evaluation_artifact_json,'$.recommended_model')=NEW.model) OR json_extract(NEW.approval_receipt_json,'$.decision')<>'approved' OR json_extract(NEW.approval_receipt_json,'$.purpose')<>NEW.purpose OR json_extract(NEW.approval_receipt_json,'$.approved_model')<>NEW.model OR json_extract(NEW.approval_receipt_json,'$.approved_by')<>NEW.approved_by OR datetime(json_extract(NEW.approval_receipt_json,'$.approved_at'))<>datetime(NEW.approved_at) OR json_extract(NEW.approval_receipt_json,'$.evaluation_artifact_sha256')<>NEW.evaluation_artifact_sha256 BEGIN SELECT RAISE(ABORT, 'embedding promotion governance receipt mismatch'); END")
