    op.execute("CREATE TRIGGER IF NOT EXISTS trg_fact_derivation_edges_v2_resolution BEFORE INSERT ON fact_derivation_input_edges_v2 WHEN NEW.input_resolution_revision_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM fact_resolution_revisions_v2 AS resolution JOIN fact_observations_v2 AS input ON input.observation_id = NEW.input_observation_id WHERE resolution.resolution_revision_id = NEW.input_resolution_revision_id AND resolution.status = 'resolved' AND resolution.selected_observation_id = NEW.input_observation_id AND resolution.fact_cell_id = input.fact_cell_id) BEGIN SELECT RAISE(ABORT, 'derivation input resolution must select the exact input observation'); END")
