    op.execute("CREATE TRIGGER IF NOT EXISTS trg_filing_xbrl_disposition_input_binding BEFORE INSERT ON filing_xbrl_extraction_dispositions WHEN EXISTS (SELECT 1 FROM evidence_extraction_runs run WHERE run.extraction_run_id=NEW.extraction_run_id AND run.extractor_name='filing-native-xbrl') AND NOT EXISTS (SELECT 1 FROM filing_xbrl_raw_fact_commitments raw JOIN filing_xbrl_extraction_input_seals seal ON seal.extraction_run_id=raw.extraction_run_id WHERE raw.extraction_run_id=NEW.extraction_run_id AND raw.input_ordinal=NEW.input_ordinal AND raw.source_entry_sha256=NEW.source_entry_sha256 AND raw.source_locator_sha256=NEW.source_locator_sha256 AND ((raw.normalization_outcome='normalized' AND NEW.disposition IN ('published','duplicate')) OR (raw.normalization_outcome='rejected' AND NEW.disposition='quarantined')) AND julianday(raw.recorded_at)=julianday(NEW.recorded_at) AND julianday(seal.recorded_at)=julianday(NEW.recorded_at)) BEGIN SELECT RAISE(ABORT, 'filing-XBRL disposition lacks its sealed raw commitment'); END")
