    op.execute("CREATE TRIGGER IF NOT EXISTS trg_legacy_fact_evidence_match_revisions_knowledge_clock BEFORE INSERT ON legacy_fact_evidence_match_revisions WHEN NOT EXISTS (SELECT 1 FROM legacy_document_evidence_binding_revisions AS binding JOIN evidence_document_versions AS document ON document.document_version_id = binding.document_version_id JOIN evidence_source_observations AS source ON source.observation_id = document.observation_id WHERE binding.binding_revision_id = NEW.legacy_binding_revision_id AND NEW.knowledge_at >= binding.knowledge_at AND NEW.knowledge_at >= source.retrieved_at) BEGIN SELECT RAISE(ABORT, 'legacy fact match knowledge predates binding or retrieval'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_legacy_fact_evidence_match_revisions_kpi_facts_accepted_delete BEFORE DELETE ON kpi_facts WHEN EXISTS (SELECT 1 FROM v_legacy_fact_evidence_matches_accepted_current AS match WHERE match.fact_table = 'kpi_facts' AND match.fact_row_id = OLD.id) BEGIN SELECT RAISE(ABORT, 'accepted legacy fact evidence match freezes semantic fact fields'); END")
