    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ocr_page_preflight_membership BEFORE INSERT ON ocr_page_results WHEN NOT EXISTS (SELECT 1 FROM ocr_extraction_governance AS governance JOIN ocr_preflight_pages AS page ON page.assessment_id = governance.assessment_id WHERE governance.extraction_run_id = NEW.extraction_run_id AND page.page_number = NEW.page_number AND page.requires_ocr = 1) BEGIN SELECT RAISE(ABORT, 'OCR result page must be required by preflight'); END")
