    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ontology_snapshot_headers_delete_append_only BEFORE DELETE ON ontology_snapshot_headers BEGIN SELECT RAISE(ABORT, 'ontology_snapshot_headers is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ontology_snapshot_headers_update_append_only BEFORE UPDATE ON ontology_snapshot_headers BEGIN SELECT RAISE(ABORT, 'ontology_snapshot_headers is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ontology_snapshot_member_unsealed\n        BEFORE INSERT ON ontology_snapshot_members\n        WHEN EXISTS (\n            SELECT 1 FROM ontology_snapshot_seals seal\n            WHERE seal.ontology_snapshot_id=NEW.ontology_snapshot_id)\n        BEGIN\n            SELECT RAISE(ABORT, 'ontology snapshot is sealed');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ontology_snapshot_members_delete_append_only BEFORE DELETE ON ontology_snapshot_members BEGIN SELECT RAISE(ABORT, 'ontology_snapshot_members is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ontology_snapshot_members_update_append_only BEFORE UPDATE ON ontology_snapshot_members BEGIN SELECT RAISE(ABORT, 'ontology_snapshot_members is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ontology_snapshot_seal_exact\n        BEFORE INSERT ON ontology_snapshot_seals\n        WHEN\n            NEW.member_set_sha256 <> fact_sha256(NEW.canonical_member_set_json)\n            OR NEW.member_count <> (\n                SELECT COUNT(*) FROM ontology_snapshot_members member\n                WHERE member.ontology_snapshot_id=NEW.ontology_snapshot_id)\n            OR (NEW.member_count > 0 AND (\n                (SELECT MIN(member_ordinal) FROM ontology_snapshot_members\n                 WHERE ontology_snapshot_id=NEW.ontology_snapshot_id) <> 0\n                OR\n                (SELECT MAX(member_ordinal) FROM ontology_snapshot_members\n                 WHERE ontology_snapshot_id=NEW.ontology_snapshot_id)\n                    <> NEW.member_count-1))\n            OR NEW.canonical_member_set_json <> COALESCE((\n                SELECT json_group_array(json(item)) FROM (\n                    SELECT json_object(\n                        'id', member_id,\n                        'kind', member_kind,\n                        'sha256', member_sha256\n                    ) AS item\n                    FROM ontology_snapshot_members\n                    WHERE ontology_snapshot_id=NEW.ontology_snapshot_id\n                    ORDER BY member_ordinal\n                )\n            ), '[]')\n            OR EXISTS (\n                SELECT member_kind, member_id, member_sha256\n                FROM v_ontology_snapshot_expected_members\n                WHERE ontology_snapshot_id=NEW.ontology_snapshot_id\n                EXCEPT\n                SELECT member_kind, member_id, member_sha256\n                FROM ontology_snapshot_members\n                WHERE ontology_snapshot_id=NEW.ontology_snapshot_id)\n            OR EXISTS (\n                SELECT member_kind, member_id, member_sha256\n                FROM ontology_snapshot_members\n                WHERE ontology_snapshot_id=NEW.ontology_snapshot_id\n                EXCEPT\n                SELECT member_kind, member_id, member_sha256\n                FROM v_ontology_snapshot_expected_members\n                WHERE ontology_snapshot_id=NEW.ontology_snapshot_id)\n        BEGIN\n            SELECT RAISE(ABORT, 'ontology snapshot seal mismatch');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ontology_snapshot_seals_delete_append_only BEFORE DELETE ON ontology_snapshot_seals BEGIN SELECT RAISE(ABORT, 'ontology_snapshot_seals is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_ontology_snapshot_seals_update_append_only BEFORE UPDATE ON ontology_snapshot_seals BEGIN SELECT RAISE(ABORT, 'ontology_snapshot_seals is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_pdf_table_artifact_final_seal BEFORE INSERT ON pdf_table_extraction_artifact_seals WHEN NEW.member_count <> (SELECT COUNT(*) FROM pdf_table_extraction_artifact_members member WHERE member.artifact_id=NEW.artifact_id) OR (NEW.member_count > 0 AND NEW.member_count <> 1 + (SELECT MAX(member_ordinal) FROM pdf_table_extraction_artifact_members member WHERE member.artifact_id=NEW.artifact_id)) OR NEW.canonical_member_set_json <> COALESCE((SELECT json_group_array(json(canonical_member_json)) FROM (SELECT json_object('canonical_object_sha256',canonical_object_sha256,'disposition',disposition,'locator_sha256',locator_sha256,'member_kind',member_kind,'member_ordinal',member_ordinal,'native_id',native_id,'native_parent_id',native_parent_id) AS canonical_member_json FROM pdf_table_extraction_artifact_members WHERE artifact_id=NEW.artifact_id ORDER BY member_ordinal)), '[]') OR NEW.member_set_sha256<>fact_sha256(NEW.canonical_member_set_json) OR datetime(NEW.sealed_at)<datetime((SELECT recorded_at FROM pdf_table_extraction_artifact_headers header WHERE header.artifact_id=NEW.artifact_id)) BEGIN SELECT RAISE(ABORT, 'PDF table artifact final seal mismatch'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_pdf_table_artifact_member_unsealed BEFORE INSERT ON pdf_table_extraction_artifact_members WHEN EXISTS (SELECT 1 FROM pdf_table_extraction_artifact_seals seal WHERE seal.artifact_id=NEW.artifact_id) BEGIN SELECT RAISE(ABORT, 'PDF table artifact is sealed'); END")
