    op.execute("CREATE TRIGGER IF NOT EXISTS trg_population_run_header_exact BEFORE INSERT ON population_run_headers WHEN NEW.identity_sha256<>fact_sha256(NEW.canonical_identity_json) OR NEW.population_run_id<>'population-run:'||NEW.identity_sha256 OR NEW.idempotency_key<>NEW.population_run_id OR (SELECT COUNT(*) FROM json_each(NEW.canonical_identity_json))<>5 OR EXISTS (SELECT 1 FROM json_each(NEW.canonical_identity_json) WHERE key NOT IN ('knowledge_cutoff','observed_through','policy_config_sha256','source_snapshot_sha256','version')) OR json_extract(NEW.canonical_identity_json,'$.version')<>'population-run-identity.v2' OR json_extract(NEW.canonical_identity_json,'$.policy_config_sha256')<>NEW.policy_config_sha256 OR json_extract(NEW.canonical_identity_json,'$.source_snapshot_sha256')<>NEW.source_snapshot_sha256 OR datetime(json_extract(NEW.canonical_identity_json,'$.knowledge_cutoff'))<>datetime(NEW.knowledge_cutoff) OR datetime(json_extract(NEW.canonical_identity_json,'$.observed_through'))<>datetime(NEW.observed_through) OR datetime(NEW.observed_through)<datetime(NEW.knowledge_cutoff) OR datetime(NEW.verified_at)<datetime(NEW.observed_through) BEGIN SELECT RAISE(ABORT, 'population run header mismatch'); END")
