    op.execute("CREATE TRIGGER IF NOT EXISTS trg_research_snapshot_members_unsealed BEFORE INSERT ON research_snapshot_members WHEN EXISTS (SELECT 1 FROM research_snapshot_seals seal WHERE seal.research_snapshot_id=NEW.research_snapshot_id) BEGIN SELECT RAISE(ABORT, 'Research Snapshot is sealed'); END")
