    op.execute("CREATE TRIGGER IF NOT EXISTS trg_research_snapshot_seal_requires_universe BEFORE INSERT ON research_snapshot_seals WHEN NOT EXISTS (SELECT 1 FROM research_snapshot_universe_commitments AS universe JOIN research_snapshot_members AS member ON member.research_snapshot_id=universe.research_snapshot_id WHERE universe.research_snapshot_id=NEW.research_snapshot_id AND member.requested_lane='research_universe' AND member.reference_table='research_snapshot_universe_commitments' AND member.reference_id=universe.research_snapshot_id AND member.reference_commitment_sha256=universe.universe_sha256 AND datetime(member.reference_knowledge_at)=datetime(universe.cutoff_at) AND datetime(member.reference_recorded_at)=datetime(universe.recorded_at) GROUP BY universe.research_snapshot_id HAVING COUNT(*)=1) BEGIN SELECT RAISE(ABORT, 'Research Snapshot seal requires exact universe commitment'); END")
