    op.execute("CREATE TRIGGER IF NOT EXISTS trg_research_snapshot_seals_exact BEFORE INSERT ON research_snapshot_seals WHEN NEW.member_count <> (SELECT COUNT(*) FROM research_snapshot_members member WHERE member.research_snapshot_id=NEW.research_snapshot_id) OR (NEW.member_count > 0 AND NEW.member_count <> 1 + (SELECT MAX(member_ordinal) FROM research_snapshot_members member WHERE member.research_snapshot_id=NEW.research_snapshot_id)) OR NEW.canonical_member_set_json <> COALESCE((SELECT json_group_array(json(canonical_member_json)) FROM (SELECT canonical_member_json FROM research_snapshot_members WHERE research_snapshot_id=NEW.research_snapshot_id ORDER BY member_ordinal)), '[]') OR NEW.member_set_sha256 <> fact_sha256(NEW.canonical_member_set_json) OR datetime(NEW.sealed_at) < datetime((SELECT recorded_at FROM research_snapshot_headers header WHERE header.research_snapshot_id=NEW.research_snapshot_id)) BEGIN SELECT RAISE(ABORT, 'Research Snapshot final seal mismatch'); END")
