    op.execute("CREATE TRIGGER IF NOT EXISTS trg_research_snapshot_universe_exact BEFORE INSERT ON research_snapshot_universe_commitments WHEN NOT EXISTS (SELECT 1 FROM research_snapshot_headers AS header WHERE header.research_snapshot_id=NEW.research_snapshot_id AND header.cutoff_at=NEW.cutoff_at AND header.recorded_at=NEW.recorded_at AND json_extract(header.request_json,'$.research_universe.issuer_id')=NEW.issuer_id AND json_extract(header.request_json,'$.research_universe.reporting_entity_ids')=NEW.reporting_entity_ids_json AND json_extract(header.request_json,'$.research_universe.document_version_ids')=NEW.document_version_ids_json AND json_extract(header.request_json,'$.research_universe.source_obligation_revision_ids')=NEW.source_obligation_revision_ids_json) OR NEW.canonical_universe_json<>json_object('document_version_ids',json(NEW.document_version_ids_json),'issuer_id',NEW.issuer_id,'reporting_entity_ids',json(NEW.reporting_entity_ids_json),'source_obligation_revision_ids',json(NEW.source_obligation_revision_ids_json)) OR NEW.universe_sha256<>fact_sha256(NEW.canonical_universe_json) OR (SELECT COUNT(*) FROM json_each(NEW.reporting_entity_ids_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.reporting_entity_ids_json)) OR (SELECT COUNT(*) FROM json_each(NEW.document_version_ids_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.document_version_ids_json)) OR (SELECT COUNT(*) FROM json_each(NEW.source_obligation_revision_ids_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.source_obligation_revision_ids_json)) OR EXISTS (SELECT 1 FROM json_each(NEW.reporting_entity_ids_json) item LEFT JOIN reporting_entities entity ON entity.reporting_entity_id=item.value WHERE item.type<>'text' OR length(item.value)=0 OR entity.reporting_entity_id IS NULL OR entity.issuer_id<>NEW.issuer_id) OR EXISTS (SELECT 1 FROM json_each(NEW.document_version_ids_json) item LEFT JOIN v_evidence_document_versions_canonical document ON document.document_version_id=item.value WHERE item.type<>'text' OR length(item.value)=0 OR document.document_version_id IS NULL OR document.issuer_id<>NEW.issuer_id OR document.reporting_entity_id IS NULL OR NOT EXISTS (SELECT 1 FROM json_each(NEW.reporting_entity_ids_json) entity_id WHERE entity_id.value=document.reporting_entity_id)) OR EXISTS (SELECT 1 FROM json_each(NEW.source_obligation_revision_ids_json) item LEFT JOIN source_obligation_revisions obligation ON obligation.obligation_revision_id=item.value WHERE item.type<>'text' OR length(item.value)=0 OR obligation.obligation_revision_id IS NULL OR obligation.issuer_id<>NEW.issuer_id OR obligation.reporting_entity_id IS NULL OR NOT EXISTS (SELECT 1 FROM json_each(NEW.reporting_entity_ids_json) entity_id WHERE entity_id.value=obligation.reporting_entity_id)) BEGIN SELECT RAISE(ABORT, 'research universe commitment mismatch'); END")
