    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_membership_hardened_v2 BEFORE INSERT ON search_fact_projection_memberships WHEN NEW.disposition = 'included' AND NOT EXISTS (SELECT 1 FROM fact_resolution_revisions_v2 AS resolution JOIN fact_observation_payload_commitments_v2 AS payload ON payload.observation_id = resolution.selected_observation_id LEFT JOIN fact_reported_observation_anchors_v2 AS anchor ON anchor.observation_id = resolution.selected_observation_id LEFT JOIN fact_extraction_run_completeness_seals_v2 AS seal ON seal.extraction_run_id = anchor.extraction_run_id WHERE resolution.resolution_revision_id = NEW.resolution_revision_id AND ((anchor.observation_id IS NULL) OR seal.extraction_seal_id IS NOT NULL)) BEGIN SELECT RAISE(ABORT, 'included fact projection requires committed complete evidence'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_memberships_append_only BEFORE UPDATE ON search_fact_projection_memberships BEGIN SELECT RAISE(ABORT, 'fact projection membership is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_memberships_append_only_delete BEFORE DELETE ON search_fact_projection_memberships BEGIN SELECT RAISE(ABORT, 'fact projection membership is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_memberships_included BEFORE INSERT ON search_fact_projection_memberships WHEN NEW.disposition = 'included' AND NOT EXISTS (SELECT 1 FROM search_fact_projection_runs AS run JOIN fact_resolution_revisions_v2 AS resolution ON resolution.resolution_revision_id = NEW.resolution_revision_id JOIN fact_observations_v2 AS observation ON observation.observation_id = resolution.selected_observation_id WHERE run.projection_run_id = NEW.projection_run_id AND resolution.fact_cell_id = NEW.fact_cell_id AND resolution.status = 'resolved' AND resolution.knowledge_at <= run.knowledge_cutoff AND resolution.recorded_at <= run.knowledge_cutoff AND observation.knowledge_at <= run.knowledge_cutoff AND observation.recorded_at <= run.knowledge_cutoff AND resolution.candidate_count = (SELECT COUNT(*) FROM fact_resolution_candidates_v2 AS candidate WHERE candidate.candidate_set_id = resolution.candidate_set_id) AND NOT EXISTS (SELECT 1 FROM fact_resolution_revisions_v2 AS newer WHERE newer.fact_cell_id = resolution.fact_cell_id AND newer.knowledge_at <= run.knowledge_cutoff AND newer.recorded_at <= run.knowledge_cutoff AND newer.revision > resolution.revision) AND ((observation.observation_kind = 'reported' AND EXISTS (SELECT 1 FROM search_corpus_document_memberships AS membership JOIN evidence_extraction_runs AS extraction ON extraction.document_version_id = membership.document_version_id JOIN evidence_nodes AS node ON node.extraction_run_id = extraction.extraction_run_id JOIN evidence_document_versions AS document ON document.document_version_id = membership.document_version_id WHERE membership.manifest_id = run.manifest_id AND membership.membership_status = 'included' AND membership.document_version_id = observation.document_version_id AND node.node_id = observation.evidence_node_id AND (document.document_type <> 'sec_companyfacts' OR observation.legacy_match_revision_id IS NOT NULL))) OR (observation.observation_kind = 'derived' AND EXISTS (SELECT 1 FROM fact_derivation_seals_v2 AS derivation WHERE derivation.output_observation_id = observation.observation_id AND derivation.knowledge_at <= run.knowledge_cutoff AND derivation.recorded_at <= run.knowledge_cutoff AND derivation.input_count = (SELECT COUNT(*) FROM fact_derivation_input_edges_v2 AS edge WHERE edge.output_observation_id = observation.observation_id) AND NOT EXISTS (SELECT 1 FROM fact_derivation_input_edges_v2 AS edge JOIN fact_observations_v2 AS input ON input.observation_id = edge.input_observation_id WHERE edge.output_observation_id = observation.observation_id AND (edge.recorded_at > run.knowledge_cutoff OR input.knowledge_at > run.knowledge_cutoff OR input.recorded_at > run.knowledge_cutoff OR (input.observation_kind = 'reported' AND NOT EXISTS (SELECT 1 FROM search_corpus_document_memberships AS input_membership JOIN evidence_extraction_runs AS input_run ON input_run.document_version_id = input_membership.document_version_id JOIN evidence_nodes AS input_node ON input_node.extraction_run_id = input_run.extraction_run_id WHERE input_membership.manifest_id = run.manifest_id AND input_membership.membership_status = 'included' AND input_membership.document_version_id = input.document_version_id AND input_node.node_id = input.evidence_node_id)) OR (input.observation_kind = 'derived' AND NOT EXISTS (SELECT 1 FROM fact_derivation_seals_v2 AS input_seal WHERE input_seal.output_observation_id = input.observation_id AND input_seal.knowledge_at <= run.knowledge_cutoff AND input_seal.recorded_at <= run.knowledge_cutoff)))))))) BEGIN SELECT RAISE(ABORT, 'included fact requires a complete as-known resolution and provenance'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_memberships_resolution_scope BEFORE INSERT ON search_fact_projection_memberships WHEN NEW.resolution_revision_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM search_fact_projection_runs AS run JOIN fact_resolution_revisions_v2 AS resolution ON resolution.resolution_revision_id = NEW.resolution_revision_id WHERE run.projection_run_id = NEW.projection_run_id AND resolution.fact_cell_id = NEW.fact_cell_id AND resolution.knowledge_at <= run.knowledge_cutoff AND resolution.recorded_at <= run.knowledge_cutoff AND NOT EXISTS (SELECT 1 FROM fact_resolution_revisions_v2 AS newer WHERE newer.fact_cell_id = resolution.fact_cell_id AND newer.knowledge_at <= run.knowledge_cutoff AND newer.recorded_at <= run.knowledge_cutoff AND newer.revision > resolution.revision)) BEGIN SELECT RAISE(ABORT, 'membership resolution must be latest as known at cutoff'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_memberships_scope BEFORE INSERT ON search_fact_projection_memberships WHEN NOT EXISTS (SELECT 1 FROM search_fact_projection_runs AS run JOIN fact_cells_v2 AS cell ON cell.fact_cell_id = NEW.fact_cell_id WHERE run.projection_run_id = NEW.projection_run_id AND cell.knowledge_at <= run.knowledge_cutoff AND NEW.recorded_at >= cell.recorded_at AND NEW.recorded_at <= run.recorded_at) BEGIN SELECT RAISE(ABORT, 'fact projection membership requires a cell known at cutoff'); END")
