    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_memberships_unsealed BEFORE INSERT ON search_fact_projection_memberships WHEN EXISTS (SELECT 1 FROM search_fact_projection_seals AS seal WHERE seal.projection_run_id = NEW.projection_run_id) BEGIN SELECT RAISE(ABORT, 'sealed fact projection cannot receive memberships'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_rows_append_only BEFORE UPDATE ON search_fact_projection_rows BEGIN SELECT RAISE(ABORT, 'fact projection row is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_rows_append_only_delete BEFORE DELETE ON search_fact_projection_rows BEGIN SELECT RAISE(ABORT, 'fact projection row is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_rows_exact BEFORE INSERT ON search_fact_projection_rows WHEN NOT EXISTS (SELECT 1 FROM search_fact_projection_runs AS run JOIN fact_cells_v2 AS cell ON cell.fact_cell_id = NEW.fact_cell_id JOIN fact_resolution_revisions_v2 AS resolution ON resolution.resolution_revision_id = NEW.resolution_revision_id JOIN fact_observations_v2 AS observation ON observation.observation_id = NEW.observation_id LEFT JOIN fact_derivation_seals_v2 AS derivation ON derivation.output_observation_id = observation.observation_id WHERE run.projection_run_id = NEW.projection_run_id AND resolution.fact_cell_id = cell.fact_cell_id AND resolution.status = 'resolved' AND resolution.selected_observation_id = observation.observation_id AND observation.fact_cell_id = cell.fact_cell_id AND NEW.reporting_entity_id = cell.reporting_entity_id AND NEW.scope_security_id IS cell.scope_security_id AND NEW.concept_namespace = cell.concept_namespace AND NEW.concept_name = cell.concept_name AND NEW.taxonomy_name = cell.taxonomy_name AND NEW.taxonomy_version IS cell.taxonomy_version AND NEW.accounting_basis = cell.accounting_basis AND NEW.consolidation_scope = cell.consolidation_scope AND NEW.period_kind = cell.period_kind AND NEW.period_start IS cell.period_start AND NEW.period_end = cell.period_end AND NEW.fiscal_year IS cell.fiscal_year AND NEW.fiscal_period IS cell.fiscal_period AND NEW.canonical_dimensions_json = cell.canonical_dimensions_json AND NEW.canonical_dimensions_sha256 = cell.canonical_dimensions_sha256 AND NEW.unit_key = cell.unit_key AND NEW.currency IS cell.currency AND NEW.observation_kind = observation.observation_kind AND NEW.value_kind = observation.value_kind AND NEW.numeric_value IS observation.numeric_value AND NEW.text_value IS observation.text_value AND NEW.is_nil = observation.is_nil AND NEW.raw_lexical_value IS observation.raw_lexical_value AND NEW.candidate_set_id = resolution.candidate_set_id AND NEW.candidate_count = resolution.candidate_count AND NEW.candidate_set_digest_sha256 = resolution.candidate_set_digest_sha256 AND NEW.document_version_id IS observation.document_version_id AND NEW.evidence_node_id IS observation.evidence_node_id AND NEW.source_locator_json IS observation.source_locator_json AND NEW.source_locator_sha256 IS observation.source_locator_sha256 AND NEW.source_entry_sha256 IS observation.source_entry_sha256 AND NEW.legacy_match_revision_id IS observation.legacy_match_revision_id AND NEW.derivation_seal_id IS derivation.derivation_seal_id AND NEW.derivation_input_count IS derivation.input_count AND NEW.derivation_input_digest_sha256 IS derivation.canonical_input_digest_sha256 AND NEW.cell_knowledge_at = cell.knowledge_at AND NEW.observation_knowledge_at = observation.knowledge_at AND NEW.resolution_knowledge_at = resolution.knowledge_at AND NEW.recorded_at <= run.recorded_at) BEGIN SELECT RAISE(ABORT, 'fact projection row must exactly match its resolved source'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_rows_membership BEFORE INSERT ON search_fact_projection_rows WHEN NOT EXISTS (SELECT 1 FROM search_fact_projection_memberships AS membership WHERE membership.projection_run_id = NEW.projection_run_id AND membership.fact_cell_id = NEW.fact_cell_id AND membership.disposition = 'included' AND membership.resolution_revision_id = NEW.resolution_revision_id) BEGIN SELECT RAISE(ABORT, 'fact projection row requires its included membership'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_rows_unsealed BEFORE INSERT ON search_fact_projection_rows WHEN EXISTS (SELECT 1 FROM search_fact_projection_seals AS seal WHERE seal.projection_run_id = NEW.projection_run_id) BEGIN SELECT RAISE(ABORT, 'sealed fact projection cannot receive rows'); END")
