    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_runs_manifest BEFORE INSERT ON search_fact_projection_runs WHEN NOT EXISTS (SELECT 1 FROM search_corpus_manifests AS manifest JOIN search_corpus_manifest_seals AS seal ON seal.manifest_id = manifest.manifest_id WHERE manifest.manifest_id = NEW.manifest_id AND manifest.knowledge_cutoff IS NOT NULL AND manifest.knowledge_cutoff = NEW.knowledge_cutoff AND seal.completion_status = 'complete') BEGIN SELECT RAISE(ABORT, 'fact projection requires a complete corpus at the same cutoff'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_runs_parent BEFORE INSERT ON search_fact_projection_runs WHEN NEW.revision > 1 AND (NEW.supersedes_projection_run_id IS NULL OR NOT EXISTS (SELECT 1 FROM search_fact_projection_runs AS prior WHERE prior.projection_run_id = NEW.supersedes_projection_run_id AND prior.projection_key = NEW.projection_key AND prior.revision = NEW.revision - 1 AND NEW.recorded_at >= prior.recorded_at)) BEGIN SELECT RAISE(ABORT, 'fact projection must supersede its prior revision'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_seals_append_only BEFORE UPDATE ON search_fact_projection_seals BEGIN SELECT RAISE(ABORT, 'fact projection seal is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_seals_append_only_delete BEFORE DELETE ON search_fact_projection_seals BEGIN SELECT RAISE(ABORT, 'fact projection seal is append-only'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_seals_contract BEFORE INSERT ON search_fact_projection_seals WHEN NOT EXISTS (SELECT 1 FROM search_fact_projection_runs AS run JOIN search_corpus_manifest_seals AS corpus_seal ON corpus_seal.manifest_id = run.manifest_id WHERE run.projection_run_id = NEW.projection_run_id AND run.manifest_id = NEW.manifest_id AND run.config_sha256 = NEW.config_sha256 AND corpus_seal.completion_status = 'complete' AND NEW.sealed_at >= run.recorded_at) BEGIN SELECT RAISE(ABORT, 'fact projection seal requires its complete configured run'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_seals_counts BEFORE INSERT ON search_fact_projection_seals WHEN NEW.eligible_fact_cell_count <> (SELECT COUNT(*) FROM fact_cells_v2 AS cell JOIN search_fact_projection_runs AS run ON run.projection_run_id = NEW.projection_run_id WHERE cell.knowledge_at <= run.knowledge_cutoff AND cell.recorded_at <= run.recorded_at) OR NEW.membership_count <> (SELECT COUNT(*) FROM search_fact_projection_memberships AS membership WHERE membership.projection_run_id = NEW.projection_run_id) OR NEW.membership_count <> NEW.eligible_fact_cell_count OR NEW.included_count <> (SELECT COUNT(*) FROM search_fact_projection_memberships AS membership WHERE membership.projection_run_id = NEW.projection_run_id AND membership.disposition = 'included') OR NEW.unresolved_material_count <> (SELECT COUNT(*) FROM search_fact_projection_memberships AS membership WHERE membership.projection_run_id = NEW.projection_run_id AND membership.disposition = 'unresolved_material') OR NEW.missing_provenance_count <> (SELECT COUNT(*) FROM search_fact_projection_memberships AS membership WHERE membership.projection_run_id = NEW.projection_run_id AND membership.disposition = 'missing_provenance') OR NEW.quarantined_count <> (SELECT COUNT(*) FROM search_fact_projection_memberships AS membership WHERE membership.projection_run_id = NEW.projection_run_id AND membership.disposition = 'quarantined') OR NEW.membership_count <> (NEW.included_count + NEW.unresolved_material_count + NEW.missing_provenance_count + NEW.quarantined_count) OR NEW.row_count <> (SELECT COUNT(*) FROM search_fact_projection_rows AS row WHERE row.projection_run_id = NEW.projection_run_id) OR NEW.row_count <> NEW.included_count BEGIN SELECT RAISE(ABORT, 'fact projection seal counts do not match complete membership'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_projection_seals_coverage BEFORE INSERT ON search_fact_projection_seals WHEN EXISTS (SELECT 1 FROM fact_cells_v2 AS cell JOIN search_fact_projection_runs AS run ON run.projection_run_id = NEW.projection_run_id LEFT JOIN search_fact_projection_memberships AS membership ON membership.projection_run_id = run.projection_run_id AND membership.fact_cell_id = cell.fact_cell_id WHERE cell.knowledge_at <= run.knowledge_cutoff AND cell.recorded_at <= run.recorded_at AND membership.membership_id IS NULL) OR EXISTS (SELECT 1 FROM search_fact_projection_memberships AS membership LEFT JOIN search_fact_projection_rows AS row ON row.projection_run_id = membership.projection_run_id AND row.fact_cell_id = membership.fact_cell_id WHERE membership.projection_run_id = NEW.projection_run_id AND ((membership.disposition = 'included' AND row.fact_hit_id IS NULL) OR (membership.disposition <> 'included' AND row.fact_hit_id IS NOT NULL))) OR EXISTS (SELECT 1 FROM search_fact_projection_memberships AS membership WHERE membership.projection_run_id = NEW.projection_run_id AND membership.recorded_at > NEW.sealed_at) OR EXISTS (SELECT 1 FROM search_fact_projection_rows AS row WHERE row.projection_run_id = NEW.projection_run_id AND row.recorded_at > NEW.sealed_at) BEGIN SELECT RAISE(ABORT, 'fact projection seal requires exact disposition and row coverage'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_fact_rows_hardened_v2 BEFORE INSERT ON search_fact_projection_rows WHEN NOT EXISTS (SELECT 1 FROM fact_observation_payload_commitments_v2 AS payload LEFT JOIN fact_reported_observation_anchors_v2 AS anchor ON anchor.observation_id = payload.observation_id LEFT JOIN fact_extraction_run_completeness_seals_v2 AS seal ON seal.extraction_run_id = anchor.extraction_run_id WHERE payload.observation_id = NEW.observation_id AND ((anchor.observation_id IS NULL) OR seal.extraction_seal_id IS NOT NULL)) BEGIN SELECT RAISE(ABORT, 'fact search row requires committed complete evidence'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_index_membership_manifest BEFORE INSERT ON search_index_memberships WHEN (SELECT manifest_id FROM search_index_runs WHERE index_run_id = NEW.index_run_id) <> (SELECT manifest_id FROM search_chunks WHERE chunk_id = NEW.chunk_id) BEGIN SELECT RAISE(ABORT, 'index membership must use the index manifest'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_index_memberships_append_only BEFORE UPDATE ON search_index_memberships BEGIN SELECT RAISE(ABORT, 'grounded search ledger is append-only'); END")
