    op.execute("CREATE TRIGGER IF NOT EXISTS trg_search_manifest_source_inventories_append_only_delete BEFORE DELETE ON search_manifest_source_inventories BEGIN SELECT RAISE(ABORT, 'source inventory provenance is append-only'); END")
