    op.execute("CREATE TRIGGER IF NOT EXISTS trg_source_taxonomy_assertion_exact\n        BEFORE INSERT ON source_observation_taxonomy_assertions\n        WHEN NOT EXISTS (\n            SELECT 1\n            FROM fact_observations_v2 observation\n            JOIN fact_cells_v2 cell\n              ON cell.fact_cell_id=observation.fact_cell_id\n            JOIN fact_cell_identity_seals_v2 cell_seal\n              ON cell_seal.fact_cell_id=cell.fact_cell_id\n            JOIN fact_reported_observation_anchors_v2 anchor\n              ON anchor.observation_id=observation.observation_id\n            JOIN fact_observation_payload_commitments_v2 payload\n              ON payload.observation_id=observation.observation_id\n            JOIN evidence_extraction_runs run\n              ON run.extraction_run_id=anchor.extraction_run_id\n            JOIN fact_extraction_run_completeness_seals_v2 completeness\n              ON completeness.extraction_run_id=run.extraction_run_id\n            WHERE observation.observation_id=NEW.observation_id\n              AND observation.observation_kind='reported'\n              AND run.extraction_run_id=NEW.extraction_run_id\n              AND run.outcome='succeeded'\n              AND cell.taxonomy_name=NEW.taxonomy_name\n              AND anchor.source_taxonomy_version=NEW.taxonomy_version\n              AND cell_seal.semantic_key_sha256=\n                    NEW.fact_cell_semantic_key_sha256\n              AND anchor.anchor_payload_sha256=NEW.anchor_payload_sha256\n              AND payload.observation_payload_sha256=\n                    NEW.observation_payload_sha256\n              AND run.output_sha256=NEW.extraction_output_sha256\n              AND anchor.extraction_output_sha256=\n                    NEW.extraction_output_sha256\n              AND completeness.extraction_output_sha256=\n                    NEW.extraction_output_sha256\n              AND anchor.raw_entry_sha256=NEW.raw_entry_sha256\n              AND observation.source_entry_sha256=NEW.raw_entry_sha256\n              AND completeness.observation_set_sha256=\n                    NEW.observation_set_sha256\n              AND EXISTS (\n                    SELECT 1\n                    FROM json_each(completeness.observation_set_json) member\n                    WHERE member.value=NEW.observation_id)\n              AND datetime(cell.recorded_at) <= datetime(NEW.knowledge_at)\n              AND datetime(cell_seal.sealed_at) <= datetime(NEW.knowledge_at)\n              AND datetime(observation.recorded_at)\n                    <= datetime(NEW.knowledge_at)\n              AND datetime(anchor.recorded_at) <= datetime(NEW.knowledge_at)\n              AND datetime(payload.committed_at) <= datetime(NEW.knowledge_at)\n              AND datetime(run.completed_at) <= datetime(NEW.knowledge_at)\n              AND datetime(completeness.knowledge_at)\n                    <= datetime(NEW.knowledge_at)\n              AND datetime(completeness.recorded_at)\n                    <= datetime(NEW.knowledge_at)\n        )\n        BEGIN\n            SELECT RAISE(ABORT,\n                'taxonomy assertion lacks exact committed fact evidence');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_source_taxonomy_components_commitment_exact\n        BEFORE INSERT ON source_taxonomy_components\n        WHEN NEW.commitment_sha256 <> fact_sha256(NEW.commitment_json)\n        BEGIN\n            SELECT RAISE(ABORT, 'source_taxonomy_components commitment mismatch');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_source_taxonomy_components_delete_append_only\n        BEFORE DELETE ON source_taxonomy_components\n        BEGIN\n            SELECT RAISE(ABORT, 'source_taxonomy_components is append-only');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_source_taxonomy_components_update_append_only\n        BEFORE UPDATE ON source_taxonomy_components\n        BEGIN\n            SELECT RAISE(ABORT, 'source_taxonomy_components is append-only');\n        END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcript_documents_immutable BEFORE UPDATE OF file_path, sha256 ON documents WHEN EXISTS (SELECT 1 FROM transcripts WHERE document_id = OLD.id) BEGIN SELECT RAISE(ABORT, 'transcript document evidence is immutable'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcript_documents_no_delete BEFORE DELETE ON documents WHEN EXISTS (SELECT 1 FROM transcripts WHERE document_id = OLD.id) BEGIN SELECT RAISE(ABORT, 'transcript documents cannot be deleted'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcript_segments_immutable BEFORE UPDATE ON transcript_segments BEGIN SELECT RAISE(ABORT, 'transcript segments are immutable'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcript_segments_no_delete BEFORE DELETE ON transcript_segments BEGIN SELECT RAISE(ABORT, 'transcript segments cannot be deleted'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcripts_document_immutable BEFORE UPDATE OF document_id ON transcripts WHEN OLD.document_id <> NEW.document_id BEGIN SELECT RAISE(ABORT, 'transcript document provenance is immutable'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcripts_immutable_evidence BEFORE UPDATE OF document_id, ticker, call_date, fiscal_period_type, period_end, source_url, has_qa_section, version_number, recorded_at ON transcripts BEGIN SELECT RAISE(ABORT, 'transcript evidence versions are immutable'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcripts_lifecycle_insert BEFORE INSERT ON transcripts WHEN (NEW.is_current NOT IN (0, 1)) OR (NEW.is_current = 1 AND (NEW.superseded_at IS NOT NULL OR NEW.superseded_by_transcript_id IS NOT NULL)) OR (NEW.is_current = 0 AND (NEW.superseded_at IS NULL OR NEW.superseded_by_transcript_id IS NULL)) OR (NEW.superseded_by_transcript_id = NEW.id) OR (NEW.superseded_by_transcript_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM transcripts winner WHERE winner.id = NEW.superseded_by_transcript_id AND winner.ticker = NEW.ticker AND winner.fiscal_period_type IS NEW.fiscal_period_type AND winner.period_end IS NEW.period_end)) OR (NEW.is_active != NEW.is_current) OR (NEW.superseded_by_id IS NOT NEW.superseded_by_transcript_id)  BEGIN SELECT RAISE(ABORT, 'invalid transcript lifecycle'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcripts_lifecycle_update BEFORE UPDATE OF is_current, is_active, superseded_at, superseded_by_id, superseded_by_transcript_id ON transcripts WHEN (NEW.is_current NOT IN (0, 1)) OR (NEW.is_current = 1 AND (NEW.superseded_at IS NOT NULL OR NEW.superseded_by_transcript_id IS NOT NULL)) OR (NEW.is_current = 0 AND (NEW.superseded_at IS NULL OR NEW.superseded_by_transcript_id IS NULL)) OR (NEW.superseded_by_transcript_id = NEW.id) OR (NEW.superseded_by_transcript_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM transcripts winner WHERE winner.id = NEW.superseded_by_transcript_id AND winner.ticker = NEW.ticker AND winner.fiscal_period_type IS NEW.fiscal_period_type AND winner.period_end IS NEW.period_end)) OR (NEW.is_active != NEW.is_current) OR (NEW.superseded_by_id IS NOT NEW.superseded_by_transcript_id)  BEGIN SELECT RAISE(ABORT, 'invalid transcript lifecycle'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcripts_no_delete BEFORE DELETE ON transcripts BEGIN SELECT RAISE(ABORT, 'transcript evidence versions cannot be deleted'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_transcripts_source_once BEFORE UPDATE OF source ON transcripts WHEN OLD.source IS NOT NULL OR NEW.source IS NULL BEGIN SELECT RAISE(ABORT, 'transcript source provenance is immutable'); END")
    op.execute("CREATE TRIGGER IF NOT EXISTS trg_vector_seals_runtime_binding BEFORE INSERT ON search_projection_seals WHEN NEW.index_kind='vector' AND (length(NEW.runtime_artifact_sha256)<>64 OR NEW.runtime_artifact_sha256 GLOB '*[^0-9a-f]*' OR NOT EXISTS (SELECT 1 FROM search_embedding_runtime_registrations runtime WHERE runtime.purpose='evidence_vector_retrieval' AND runtime.provider=NEW.provider AND runtime.model=NEW.model AND runtime.dimensions=NEW.dimensions AND runtime.runtime_artifact_sha256=NEW.runtime_artifact_sha256) OR NOT EXISTS (SELECT 1 FROM search_embedding_artifacts artifact WHERE artifact.index_run_id=NEW.index_run_id AND artifact.outcome='succeeded') OR EXISTS (SELECT 1 FROM search_embedding_artifacts artifact WHERE artifact.index_run_id=NEW.index_run_id AND artifact.outcome='succeeded' AND (artifact.runtime_artifact_sha256 IS NULL OR artifact.runtime_artifact_sha256<>NEW.runtime_artifact_sha256))) BEGIN SELECT RAISE(ABORT, 'vector seal requires one registered runtime artifact'); END")
    op.execute("INSERT OR IGNORE INTO tenants (id, created_at) VALUES ('bhanu', datetime('now'))")


